INSERT INTO new_exams (exam_no, tag_code, display_order, config_id, name_ar, name_en, description_ar, description_en, question_count) VALUES
  (0, 'agile', 1, 2, 'أجايل 1', 'Agile 1', 'تدريب من 170 سؤالًا بدون توقيت، مع عرض الإجابة الصحيحة والشرح بعد كل سؤال.', '170 untimed practice questions, with the correct answer and explanation shown after each one.', 170);
INSERT INTO new_questions (exam_no, question_index, text_ar, text_en, explanation_ar, explanation_en, answer_count) VALUES
  (0, 0, 'لقد انضممت إلى فريق مشروع جديد يتجه نحو أسلوب عمل أجايل (Agile). ويتضمن ذلك جمع الفريق في مكان واحد (Co-location) للاستفادة من التواصل الأسموزي (Osmotic Communication). يسألك راعي المشروع (Project Sponsor) عن معنى ذلك. بماذا تجيبه؟', 'You have joined a new project team and are moving to an Agile way of work. Part of this is co-locating the team to gain the benefit of osmotic communication. Your project sponsor asks what this means. What do you tell them?', 'التواصل الأسموزي (Osmotic Communication) هو الاستماع العرضي إلى معلومات خلفية قد تتبين أهميتها لاحقًا، وهو جزء من فائدة تواجد الفريق في مكان واحد في أجايل.', 'Osmotic communication is the accidental overhearing of background information that may later end up being important – part of the benefit to co-locating a team in Agile.', 1),
  (0, 1, 'أنت تعمل مع فريق أجايل (Agile) غير متواجد في مكان واحد، إذ يتوزع أعضاؤه على مواقع مختلفة في أنحاء البلاد. بصفتك قائد أجايل (Agile Lead)، كيف ستحقق فوائد أجايل دون فريق متواجد في مكان واحد؟', 'You are working with an Agile team who are not co-located. They are in various locations around the country. As the Agile lead, how will you get the benefit of Agile without a co-located team?', 'قد لا يكون نقل فرق بأكملها أو توظيف فرق جديدة أمرًا ممكنًا عمليًا. والاستفادة من الخيارات الإلكترونية المتعددة حتى يظل فريقك يحصل على فائدة التواصل والاتصال المتكرر هي النهج الأكثر فعالية من حيث التكلفة.', 'It may not be feasible to move entire teams, or hire new ones. Utilising the many electronic options so your team can still get the benefit of frequent contact and communication is the most cost-effective approach.', 1),
  (0, 2, 'أنت تقود فريق أجايل (Agile) يضم أعضاء في مواقع مختلفة في أنحاء البلاد. وقد رتّبت اجتماعات وقوف يومية (Daily Stand-ups) عبر الهاتف، مع لوحة كانبان (Kanban) وقوائم أعمال متراكمة (Backlogs) إلكترونية، لكن الفريق غير قادر على الاجتماع وجهًا لوجه. ما الذي ستفعله أيضًا لزيادة العمل المشترك بين أعضاء الفريق وتعارفهم؟', 'You are leading an Agile team that has members in various locations around the country. You have arranged daily stand-ups via phone, with electronic Kanban and backlogs, but the team is not able to meet face to face. What else will you do to increase the team working together and getting to know each other?', 'البرمجة الثنائية (Pair Programming) تقنية شائعة في أجايل ويمكن استخدامها في معظم المهام. ويمنح تشكيل أزواج من أعضاء الفريق للعمل على مهمة أو تكرار (Iteration) الفرصة للتحدث والعمل معًا بشكل فردي مباشر.', 'Pair programming is a common technique in Agile and can be used for most tasks. Pairing up team members on a task or iteration gives them the opportunity to talk and work with each other one-on-one', 1),
  (0, 3, 'أنت تصطحب راعي المشروع (Project Sponsor) في جولة في منطقة عمل الفريق لمشروع أجايل (Agile) الخاص بك، وترى مخطط الإنجاز التنازلي (Burndown Chart) بجوار لوحة كانبان (Kanban Board) الخاصة بالفريق. يسألك راعي المشروع عما يخبرك به هذا المخطط. بماذا ستجيب؟', 'You are showing the project sponsor around the team area for your Agile project and see the burndown chart next to the team Kanban board. The project sponsor asks what the chart tells you. What will you say?', 'مخطط الإنجاز التنازلي (Burndown Chart) هو مخطط خطي يوضح مهام التكرار (Iteration) المكتملة مقارنةً بما كان مخططًا له على مدار التكرار. ويمكن استخدام الفكرة نفسها للميزات على مدى حياة المشروع، أو حتى للمخاطر المرتبطة بالمشروع نفسه، ويمكن قياسه بأي طريقة تختارها: بالساعات، أو المهام، أو البطاقات، أو القصص المكتملة، وغير ذلك.', 'A burndown chart is a line chart showing the iteration tasks completed versus what was planned over the iteration. The same idea can be used for features over the life of a project, or even risks with the project itself, and can be measured in any way you choose – by hours, tasks, cards or stories completed and more.', 1),
  (0, 4, 'أنت تراجع قائمة الميزات المتراكمة (Feature Backlog) مع المدير الوظيفي (Functional Manager) في المنظمة، وهو مالك المنتج (Product Owner) لفريق أجايل (Agile) الخاص بك. يسألك عن مخطط السرعة (Velocity Chart) المعلّق في منطقة عمل الفريق. بماذا تخبره عن ماهيته؟', 'You are working through the feature backlog with the functional manager of the organisation, who is the product owner for your Agile team. They ask about the velocity chart that is hanging in the team area. What do you tell them it is?', 'سرعة الفريق (Velocity) هي مقدار العمل الذي يمكن للفريق إكماله في تكرار (Iteration) معين، سواء قيست بالنقاط أو الساعات أو بطاقات القصص أو المهام أو الميزات نفسها. وبالتالي يوضح مخطط السرعة عدد وحدات القياس التي تختارها لكل تكرار.', 'Team velocity is the amount of work a team can complete in a given iteration, whether it’s measured by points, hours, story cards, tasks, or features themselves. A velocity chart therefore shows the number of whatever unit of measure you choose per iteration.', 1),
  (0, 5, 'في عام 2001، اتفقت مجموعة من الأفراد الممثلين لأكثر منهجيات تطوير البرمجيات خفيفة الوزن استخدامًا على مجموعة مشتركة من القيم والمبادئ عُرفت لاحقًا باسم بيان أجايل (Agile Manifesto). أي مما يلي يُعد إحدى القيم الأساسية لبيان أجايل؟', 'In 2001, a group of individuals, representing the most widely used lightweight software development methodologies, agreed on a common set of values and principles which became known as the Agile Manifesto. Which of the following is one of the Agile Manifesto''s core values?', 'يتكون بيان أجايل (Agile Manifesto) من أربع قيم أساسية، إحداها تقدّر التعاون مع العميل أهم من التفاوض على العقد.', 'The Agile manifesto is made up of four core values, one of which values Customer collaboration over contract negotiation.', 1),
  (0, 6, 'أنت تعمل مع فريق مشروعك بطريقة تضمن تحليل المتطلبات، ثم التصميم والبناء والاختبار وفقًا لتلك المتطلبات، مع تكرار هذه الأنشطة حتى يصبح المنتج صحيحًا، وتعديل منتجك أو نهجك حسب الحاجة قبل الإصدار في ميزة واحدة كبيرة. ما دورة حياة المشروع (Project Life Cycle) التي تستخدمها؟', 'You are working with your project team in a way that ensures you Analyse the requirements, then Design, Build and Test for those requirements, repeating them until the product is correct, and adjusting your product or approach as necessary before releasing in one large feature. Which project lifecycle are you using?', 'تقوم دورة حياة المشروع التكرارية (Iterative Life Cycle) بالتحليل والتصميم والبناء والاختبار، وتكرر هذه الأنشطة حتى يصبح المنتج صحيحًا، ثم تسلّمه في إصدار واحد. أما الدورة التزايدية (Incremental) فتسلّم زيادات صغيرة من القيمة (أي الميزات)، وأجايل (Agile) هي مزيج من التكرارية والتزايدية، والدورة التنبؤية (Predictive) تقوم بإصدار واحد فقط مع القليل من التغذية الراجعة التكرارية أو بدونها.', 'The iterative project lifecycle Analyses, Designs, Builds, Tests, and repeats these activities until it is correct, then delivers in one release. Incremental delivers small increments of value (i.e. features), Agile is a combination of Iterative and Incremental, and Predictive does one release only with little or no iterative feedback.', 1),
  (0, 7, 'أنت مدير مشروع أجايل (Agile) تقود فريق مشروع معتادًا على أسلوب عمل الشلال (Waterfall). يريد راعي المشروع (Project Sponsor) تخطيط المشروع بأكمله مسبقًا حتى يتمكن من معرفة موعد تسليم المشروع. تخبره بأن أجايل يستخدم التخطيط التكيفي (Adaptive Planning). لماذا قد يكون هذا بديلاً أفضل؟', 'You are an Agile project manager leading a project team who is used to a Waterfall way of work. The project sponsor wants to plan the entire project up front so they can see when the project will be delivered. You tell them that Agile uses adaptive planning. Why might this be a better alternative?', 'يتيح التخطيط التكيفي (Adaptive Planning) لراعي المشروع الحصول على قيمة تزايدية تُسلَّم على شكل ميزات، كما يتيح لمالك المنتج (Product Owner) إعادة ترتيب أولويات تلك الميزات طوال حياة المشروع. وكما يُقال، تبدأ كثير من مشاريع الشلال بتخطيط تنبؤي، وتنتهي بتخطيط تكيفي (عندما لا تتحقق توقعات الجدول الزمني والتكلفة ويضطرون إلى التعديل).', 'Adaptive planning allows the project sponsor to receive incremental value delivered as features, and for those features to be re-prioritised by the product owner throughout the life of the project. As the saying goes, many waterfall projects start out as predictive planned, and end up as adaptive planned (when schedule and cost projections are not met and they need to adjust).', 1),
  (0, 8, 'أنت سكرم ماستر (Scrum Master) وعلى وشك بدء تكرار (Iteration) جديد في مشروع أجايل (Agile) الخاص بك. أُضيفت ميزات جديدة إلى قائمة الأعمال المتراكمة (Backlog)، والفريق غير متأكد من أي تلك الميزات ينبغي العمل عليها تاليًا. كيف ستوجّه مالك المنتج (Product Owner) والفريق عند تحليل الأولوية التالية؟', 'You are the Scrum Master and about to begin a new iteration in your Agile project. New features have been added to the backlog, and the team are unsure of which of those features to work on next. How will you guide the product owner and the team when analysing next priority?', 'في حين أن القيمة تُحدَّد عادةً بالميزات التي يريدها العملاء، فإن الأولوية يقررها في نهاية المطاف مالك المنتج (Product Owner)، الذي يمثل العميل أو الأعمال ويقوم باستمرار بتنقيح قائمة الميزات المتراكمة (Backlog) وترتيب أولوياتها. ولا يقل أهمية عن ذلك تطوير البنود عالية المخاطر، والنظر في جهد التطوير مقابل المنفعة.', 'While value is typically determined by features that customers want, the priority is ultimately decided by the product owner, who represents the customer or the business and constantly refines and prioritises the backlog of features. Just as important is developing high risk items, and considering the development effort versus the benefit.', 1),
  (0, 9, 'أنت تراجع قائمة الأعمال المتراكمة (Backlog) مع مالك المنتج (Product Owner) وتقدّر بطاقات القصص (Story Cards) مع فريق التطوير. الفريق غير متأكد مما إذا كانت تقديراته دقيقة بما فيه الكفاية. وقد عمل بعض أعضاء الفريق في مشاريع مماثلة في الماضي. ما الذي ستوصي باستخدامه؟', 'You are working through the backlog with the product owner and estimating the story cards with the development team. The team are unsure if their estimates are accurate enough. Some of the team have worked on similar projects in the past. What will you recommend they use?', 'في حين أن معظم أساليب التقدير تفي بالغرض، فإن الأفضل في هذه الحالة هو التقدير التناظري (Analogous Estimating)، باستخدام مثال مماثل من مشروع سابق. ويُجرى التقدير في أجايل غالبًا بتجزئة الميزات إلى مهام صغيرة، ثم تقدير تلك المهام (التقدير التصاعدي). وعندما لا ينجح ذلك، يسد التقدير التناظري الفجوات.', 'While most estimation methods will do, the best one in this case is Analogous estimating, using a similar example from a previous project. Agile estimating is most often done by breaking down the features into small tasks, then estimating on those tasks (bottom-up). Where that doesn’t work, Analogous estimating will fill in the blanks.', 1),
  (0, 10, 'أثناء عملك ضمن فريق مشروع أجايل (Agile)، تقوم بترتيب أولويات قائمة الميزات المتراكمة (Backlog) مع مالك المنتج (Product Owner)، وتتفقان على ما ستعملان عليه أولاً. يريد راعي المشروع (Project Sponsor) معرفة المدة اللازمة لتسليم بعض القيمة. كيف ستقدّر المدة التي يستغرقها إكمال كل ميزة من هذه الميزات؟', 'While on an Agile project team, you prioritise the backlog of features with the product owner, and agree what you will work on first. Your project sponsor wants to know how long it will take to deliver some value. How will you estimate how long each of these features will take to complete?', 'يفضّل أجايل النهج التصاعدي في التقدير (Bottom-up Estimating)، حيث يُجزّأ العمل إلى أدنى مستوى له، وهو عادةً قصة المستخدم (User Story)، ويقدّره فريق التطوير. وسيمنحك ذلك تقديرًا للجهد والوقت اللازمين لإكمال الميزة.', 'Agile favours a bottom-up approach to estimating, where the work is broken down to its lowest level, typically a user story, and estimated by the development team. This will give you an estimate of the effort and time required to complete the feature.', 1),
  (0, 11, 'أنت تعمل مع فريق أجايل (Agile) الخاص بك على أول تكرار (Iteration). اختار مالك المنتج (Product Owner) الميزة، ويقوم الفريق بتجزئتها إلى قصص مستخدم (User Stories) للعمل عليها. ما قصة المستخدم؟', 'You are working with your Agile team on your first iteration. The feature has been chosen by the product owner and the team breaks it down into user stories to work on. What is a user story?', 'قصة المستخدم (User Story) هي أصغر وحدة عمل في فريق أجايل، وهي مهمة يمكن إكمالها في مدة لا تتجاوز 3 أيام. وإذا كانت المهمة ستستغرق وقتًا أطول، فمن الشائع محاولة تجزئتها إلى جزأين أو أكثر للالتزام بقاعدة قصة المستخدم. ومن الأمثل أن تُكتب كل قصة مستخدم من وجهة نظر العميل، وغالبًا بصيغة "بصفتي..." "أريد..." "حتى أتمكن من...".', 'A user story is the smallest unit of work in an Agile team – a task that can be completed in no more than three days. If a task will take longer, it is common to try and break it into two or more pieces to accommodate the user story rule. Each single User Story is ideally written from the Customer''s viewpoint, often in the form of "As a..." "I want..." "So I can...".', 1),
  (0, 12, 'لقد بدأت مشروعًا جديدًا في منظمة جديدة، ويذكر فريق المشروع أنك تعمل في بيئة مشروع تكرارية. كيف تعرف أنك تعمل ضمن دورة حياة مشروع تكرارية (Iterative Life Cycle)؟', 'You have begun a new project in a new organisation, and the project team mentions you are working in an iterative project environment. How do you know you are working within an iterative project life cycle?', 'تستخدم دورة حياة المشروع التكرارية (Iterative Life Cycle) نماذج أولية متعاقبة أو إثباتات للمفهوم لجمع التغذية الراجعة، ثم تُصدر المنتج دفعة واحدة.', 'An Iterative project lifecycle uses successive prototypes or proofs of concept to gather feedback, then release the product in one go.', 1),
  (0, 13, 'في عام 2001، اتفقت مجموعة من الأفراد الممثلين لأكثر منهجيات تطوير البرمجيات خفيفة الوزن استخدامًا على مجموعة مشتركة من القيم والمبادئ عُرفت لاحقًا باسم بيان أجايل (Agile Manifesto). أي مما يلي يُعد إحدى القيم الأساسية لبيان أجايل؟', 'In 2001, a group of individuals, representing the most widely used lightweight software development methodologies, agreed on a common set of values and principles which became known as the Agile Manifesto. Which of the following is one of the Agile Manifesto''s core values?', 'يتكون بيان أجايل (Agile Manifesto) من أربع قيم أساسية، إحداها تقدّر "الاستجابة للتغيير أهم من اتباع خطة".', 'The Agile manifesto is made up of four core values, one of which values “Responding to change over following a plan”.', 1),
  (0, 14, 'أنت تعمل في مشروع حيث تريد المنظمة التوجه نحو أسلوب عمل أجايل (Agile). ما دورتا حياة المشروع اللتان تتحدان معًا لإنشاء بيئة أجايل؟', 'You are working on a project where the organisation wants to move towards an Agile way of work. Which two project lifecycles combine to create an Agile environment?', 'تُنشأ بيئة مشروع أجايل (Agile) من خلال الجمع بين نُهج المشروع التزايدية (Incremental)، حيث تُصدر ميزات أصغر بوتيرة أكثر انتظامًا، ونُهج المشروع التكرارية (Iterative)، حيث يتحسن المنتج من خلال التكرارات ويُصدر بعد الحصول على التغذية الراجعة.', 'An Agile project environment is created by combining Incremental project approaches, where smaller features are released more regularly, and iterative project approaches, where the product improves through iterations and is released after the feedback.', 1),
  (0, 15, 'أنت تعمل مديرًا للمشروع في فريق أجايل (Agile). أي مما يلي لا يُعد مثالاً على ممارسات التنفيذ التي ستراها في أجايل؟', 'You are working as a project manager in an Agile team. Which of the below are NOT examples of execution practices you will see in Agile?', 'خطة إدارة المشروع (Project Management Plan) هي أداة رئيسية في نهج المشروع التنبؤي أو الشلال. أما الاختبار على جميع المستويات، والتطوير المعتمد على الاختبار (TDD)، والسبايك (Spike) فجميعها ممارسات أجايل ستراها.', 'A project management plan is a key artefact in a predictive or waterfall project approach. Test at all levels, Test driven development and Spikes are all Agile practices you will see.', 1),
  (0, 16, 'عمل مالك المنتج (Product Owner) مع فريق التطوير لإدراج جميع الأعمال الواجب إنجازها، وكتابة قصص المستخدم (User Stories) لكل ميزة، ووضعها في قائمة أعمال المنتج المتراكمة (Product Backlog). ما الذي ستفعله بعد ذلك؟', 'The product owner has worked with the development team to list all work to be done, write up user stories for each feature and place them in the product backlog. What will you do next?', 'إدارة متطلبات المشروع من خلال قائمة أعمال المنتج المتراكمة (Product Backlog) ممارسة أساسية في أجايل. فقائمة أعمال المنتج المتراكمة هي مصدر الحقيقة، ويُعاد ترتيب أولوياتها باستمرار مع إنجاز العمل لضمان تسليم أقصى قيمة أولاً.', 'Managing the project requirements via the product backlog is a fundamental Agile practice. The product backlog is the source of truth, and is continuously re-prioritised as the work gets done to ensure maximum value is delivered first.', 1),
  (0, 17, 'يقوم شريك الأعمال أو مالك المنتج (Product Owner) باستمرار بتنقيح قائمة أعمال المنتج المتراكمة (Product Backlog). ويشمل ذلك إضافة قصص جديدة، وإعادة ترتيب أولويات القصص، وإزالة القصص عند الحاجة. ما الدور الذي يتولاه فريق التطوير خلال هذه العملية؟', 'The business partner or product owner continuously refines, or grooms, the product backlog. This includes adding new stories, reprioritizing stories, and removing stories when needed. What role does the development team take during this process?', 'خلال تنقيح قائمة الأعمال المتراكمة (Backlog Refinement)، يكون فريق التطوير مسؤولاً عن تحديد حجم العمل أو تقديره. ويتيح ذلك لمالك المنتج أو ممثل الأعمال أو العميل ترتيب الأولويات بفعالية، بناءً على القيمة والوقت اللازم للتسليم.', 'During backlog grooming the development team is responsible for sizing or estimating the work. This allows the product owner, business representative or customer to prioritise effectively, based on value and time to delivery.', 1),
  (0, 18, 'أنت تعمل مع فريق مشروع أجايل (Agile) الخاص بك لتقدير كل مهمة والمدة التي قد تستغرقها. يجد الفريق صعوبة في إعطاء رقم دقيق، ويخشى أن يؤثر ذلك على تسليم المشروع. ما الذي يمكنك أن تعرضه عليهم للتقدير بدقة أكبر؟', 'You are working with your Agile project team to estimate each task and how long they might take. The team is finding it difficult to give an exact figure, and worries that it might impact project delivery. What can you show them, to estimate more accurately?', 'من الممارسات الشائعة في أجايل الاعتماد على تحديد الحجم النسبي (Relative Sizing) مثل نقاط القصة (Story Points) أو "مقاسات القمصان" (T-shirt Sizing). ثم تُقاس سرعة الفريق (Velocity) باستخدام الأساليب نفسها مع إكمال الفريق لعدد معين من النقاط في كل تكرار. وهذا أسهل من محاولة التنبؤ بفترة زمنية دقيقة.', 'A common Agile practice is to rely on relative sizing such as story points or “T-Shirt sizing.” Team velocity is then measured using those same methods as the team completes a certain amount of points per iteration. This is easier than trying to predict an exact time period.', 1),
  (0, 19, 'أنت مدير مشروع أجايل (Agile) وتناقش التكرار (Iteration) مع مالك المنتج (Product Owner). وقد أنشأ قائمة البنود في قائمة أعمال المنتج المتراكمة (Product Backlog)، لكن هناك التباسًا في الفريق حول من ينبغي أن يقوم بعملية تحديد حجم بطاقات القصص. بماذا ستخبرهم؟', 'You are an Agile project manager and talking through the iteration with the product owner. They have created the list of items in the product backlog, but there is confusion in the team about who should perform the process of story card sizing. What will you tell them?', 'يقوم فريق أجايل بعملية تحديد الحجم بنقاط القصة (Story Points)، ويتولى تقديرها بشكل رئيسي المطورون والمختبرون الذين سينفذون العمل.', 'The story point sizing process is performed by the Agile team, primarily estimated by developers and testers who will be doing the work.', 1),
  (0, 20, 'لقد كنت تقدّر بطاقات القصص مع فريق مشروع أجايل (Agile) الخاص بك، لكن الجهد المسجل لم يكن متطابقًا مع الوقت الذي يستغرقه الإكمال فعليًا. ما السبب الأكثر ترجيحًا لحدوث ذلك؟', 'You have been estimating story cards with your Agile project team, but the effort captured has not been matching the time it ends up taking to complete. What is the most likely reason for this occurring?', 'ينبغي أن تشمل تقديرات بطاقات القصص جميع الأنشطة المعروفة اللازمة لإكمال تلك البطاقة، بما في ذلك الاختبار وإعادة الهيكلة (Refactoring) والتعقيد والمخاطر.', 'Estimates for story cards should include all known activities required to complete that card, including testing and refactoring, complexity and risk.', 1),
  (0, 21, 'أنت قائد فريق أجايل (Agile) وتشرح عملية أول اجتماع استعادي (Retrospective) لك. يتساءل الفريق عما ينبغي عليهم فعله. ما الطريقة التي يسير بها الاجتماع الاستعادي للفريق عادةً؟', 'You are an Agile team leader and talking through the process for your first retrospective. The team is curious as to what they should do. What is the way a team retrospective would normally work?', 'يمكّن الاجتماع الاستعادي (Retrospective) الفريق من الإجابة عن أسئلة تحسّن عملية الفريق وأسلوب عمله، مثل "ما الذي سار على نحو جيد"، و"ما الذي يمكن تحسينه"، و"ما الذي لا يزال يحيّرني".', 'A team retrospective enables the team to answer questions that improve their team process and way of work, such as “What went well,” “What could be improved,” and “What still puzzles me.”', 1),
  (0, 22, 'ينص المبدأ 12 من مبادئ أجايل (Agile) على أنه "على فترات منتظمة، يتأمل الفريق في كيفية أن يصبح أكثر فعالية، ثم يضبط سلوكه ويعدّله وفقًا لذلك." وفي الممارسة العملية، هذا هو الاجتماع الاستعادي (Retrospective). لكن ما السبب العملي لإدراج الاجتماعات الاستعادية في فريق أجايل؟', 'The 12th principle of Agile is “At regular intervals, the team reflects on how to become more effective, then tunes and adjusts its behaviour accordingly.” In practice, this is a Retrospective. But what is the practical reason for including Retrospectives in an Agile team?', 'تساعد الاجتماعات الاستعادية (Retrospectives) في أجايل الفريق على التعرف على عمليته وتحسينها بمرور الوقت، من خلال تغذية راجعة منتظمة ومنظمة تُقدَّم وتُستخدم كفريق.', 'Agile retrospectives help the team learn about their process and improve it over time, through regular and structured feedback given and used as a team.', 1),
  (0, 23, 'تُعقد الاجتماعات الاستعادية (Retrospectives) عادةً في نهاية التكرار، لكن يمكن لفريق أجايل أيضاً عقد اجتماعات استعادية في أي وقت آخر. ما الوقت الذي لا يُرجَّح أن يعقد فيه فريق أجايل اجتماعاً استعادياً؟', 'Retrospectives are typically held at the end of an iteration, but an Agile team can also hold retrospectives at any other time. What is NOT a time that an Agile team might hold a retrospective?', 'الغرض من الاجتماع الاستعادي للفريق هو جمع التغذية الراجعة (Feedback) وتحسين عملية الفريق بعد أن تصبح تلك العملية قائمة. فهو يتكرر نحو التحسين. ولا يُعقد عادةً قبل بدء العمل أو العملية، إذ لا يوجد بعدُ ما يمكن جمع تغذية راجعة بشأنه.', 'A team retrospective is there to gather feedback and improve on the team process once that process is in place. It iterates towards improvement. It is typically not held before the work or process has begun, as there is nothing to gather feedback on yet.', 1),
  (0, 24, 'أنت تعمل على قائمة الأعمال المتراكمة (Backlog) مع مالك المنتج وتقدّر بطاقات القصص مع فريق التطوير. وقد عمل بعض أعضاء الفريق على ميزات مماثلة في الماضي. والفريق غير متأكد مما إذا كانت تقديراته دقيقة بما يكفي، لأن كثيراً من أعضائه جدد في المشروع. ماذا ستوصيهم باستخدامه؟', 'You are working through the backlog with the product owner and estimating the story cards with the development team. Some of the team have worked on similar features in the past. The team are unsure if their estimates are accurate enough, as many of the team are new to the project. What will you recommend they use?', 'مع أن معظم أساليب التقدير تفي بالغرض، فإن الأفضل في هذه الحالة هو التقدير التناظري (Analogous Estimating)، باستخدام مثال مماثل من مشروع سابق. وغالباً ما يتم التقدير في أجايل بتجزئة الميزات إلى مهام صغيرة، ثم تقدير تلك المهام (التقدير التصاعدي). وحيثما لا يُجدي ذلك، يسدّ التقدير التناظري الفجوات.', 'While most estimation methods will do, the best one in this case is Analogous estimating, using a similar example from a previous project. Agile estimating is most often done by breaking down the features into small tasks, then estimating on those tasks (bottom-up). Where that doesn’t work, Analogous estimating will fill in the blanks.', 1),
  (0, 25, 'أنت تسلّم الميزات من خلال مشروع أجايل الخاص بك، وراعي المشروع ومالك المنتج راضيان عن التقدم. يثير راعي المشروع قلقاً بشأن البنود المستقبلية وكيف سيبدو تطويرها. ماذا ستعرض عليه؟', 'You are delivering features through your Agile project and the project sponsor and product owner are happy with the progress. Your project sponsor raises a concern about future items and what that development looks like. What will you show them?', 'خارطة طريق المنتج (Product Roadmap) هي عرض مرئي لإصدارات المنتج، مشابه لمخطط جانت (Gantt Chart) أو الجدول الزمني للمشروع لكنه مبني على إصدارات ميزات أجايل. وهي رؤية عالية المستوى تُراجع حسب الحاجة.', 'A product roadmap is a visual display of the product releases, similar to a Gantt Chart or project schedule but based around Agile feature releases. It is a high level view and revised as necessary.', 1),
  (0, 26, 'يقوم فريق أجايل الخاص بك بتقدير بطاقات القصص باستخدام بوكر التخطيط (Planning Poker). وبالنسبة لإحدى الميزات الكبيرة، قدّر بعض أعضاء الفريق ثلاث نقاط، بينما قدّر الآخرون ثماني نقاط. كيف ستوجّه الفريق للوصول إلى تقدير؟', 'Your Agile team is estimating story cards using planning poker. For one of the larger features, some of the team has estimated three points, while the others have estimated eight points. How will you guide the team to come to an estimate?', 'في بوكر التخطيط (Planning Poker)، إذا اختلفت التقديرات، يشارك أصحاب التقديرين الأعلى والأدنى أسبابهم. وبعد المشاركة، يعيد الفريق التقدير. وتتكرر عملية بوكر التخطيط حتى يتحقق توافق الآراء (Consensus) أو حتى يقرر الفريق جمع مزيد من المعلومات.', 'In Planning Poker, if estimates are different, the high and low estimators share their reasons. Once shared, the team estimates again. The poker planning process is repeated until consensus is achieved or until the team decides to gather more information.', 1),
  (0, 27, 'يعمل فريق أجايل على ميزة شديدة التعقيد يصعب على الفريق إيجاد حل لها. وبصفتك قائد أجايل، توصي بسبايك (Spike). ما هو السبايك؟', 'The Agile team is working through a particularly complex feature that is difficult for the team find a solution for. As the Agile lead, you recommend a spike. What is a spike?', 'السبايك (Spike) هو مهمة محددة بإطار زمني لاستكشاف مشكلة أو التحقيق فيها. وهو منفصل عن عمل التطوير ولا يُستخدم إلا إذا كان هناك شيء يحتاج إلى اكتشاف أو تحقيق. ويمكن تنفيذه في أي وقت خلال المشروع.', 'A spike is a time-boxed task to explore or investigate an issue. It is separate from development work and only used if something needs to be figured out or investigated. It can be done at any time during a project.', 1),
  (0, 28, 'أُضيف إلى بيان أجايل (Agile Manifesto) اثنا عشر مبدأً توضيحياً لمساعدة المشاريع والفرق على فهم قيم أجايل. أي مما يلي هو مبدأ توضيحي صحيح؟', 'The Agile manifesto has twelve clarifying principles added to it to help projects and teams understand the Agile values. Which of the below is a correct clarifying principle?', '«سلّم البرمجيات العاملة بشكل متكرر، خلال فترة تتراوح من بضعة أسابيع إلى بضعة أشهر، مع تفضيل الإطار الزمني الأقصر» هو أحد مبادئ أجايل التوضيحية الاثني عشر.', '“Deliver working software frequently, from a couple of weeks to a couple of months, with a preference to the shorter timescale,” is one of the twelve Agile clarifying principles.', 1),
  (0, 29, 'أُضيف إلى بيان أجايل (Agile Manifesto) اثنا عشر مبدأً توضيحياً لمساعدة المشاريع والفرق على فهم قيم أجايل. أي مما يلي هو مبدأ توضيحي صحيح؟', 'The Agile manifesto has twelve clarifying principles added to it to help projects and teams understand the Agile values. Which of the below is a correct clarifying principle?', 'كما ستعرف من مختلف نُهج أجايل، فإن «يجب أن يعمل أصحاب الأعمال والمطورون معاً يومياً طوال المشروع» هو أحد مبادئ أجايل التوضيحية الاثني عشر.', 'As you will know form the various Agile approaches, “Business people and developers must work together daily throughout the project” is one of the twelve Agile clarifying principles.', 1),
  (0, 30, 'أُضيف إلى بيان أجايل (Agile Manifesto) اثنا عشر مبدأً توضيحياً لمساعدة المشاريع والفرق على فهم قيم أجايل. أي مما يلي هو مبدأ توضيحي صحيح؟', 'The Agile manifesto has twelve clarifying principles added to it to help projects and teams understand the Agile values. Which of the below is a correct clarifying principle?', 'يقوم أجايل على بناء المشاريع حول أفراد متحفزين – أي أعضاء الفريق متعدد الوظائف وذوي المهارات على شكل T (T-shaped) – مع منحهم الدعم اللازم من خلال إزالة العوائق وضمان تدفق العمل.', 'Agile is about building projects around motivated individuals – the cross functional and “T-shaped” team members, giving them the support needed by removing blockers and ensuring a flow of work.', 1),
  (0, 31, 'تتوافق مبادئ أجايل التوضيحية الاثنا عشر أيضاً مع أفضل النصائح للمشاريع والقيادة والاتصالات. أي مما يلي هو مبدأ توضيحي صحيح فيما يتعلق باتصالات المشروع؟', 'The twelve Agile clarifying principles also match up with the best advice for projects, leadership and communication. Which of the below is a correct clarifying principle when it comes to project communication?', 'يدرك فريق أجايل أن التواصل عن قرب من حيث الأشخاص والمكان والزمان هو الطريقة الأكثر كفاءة وفعالية – وغالباً ما يتم ذلك في منطقة فريق متواجد في مكان واحد (Co-located) بحيث يتمكن الأعضاء الآخرون من التقاط المعلومات بالأسموزية (Osmosis).', 'An Agile team knows that communicating close in person, place and time is the most efficient and effective way – often in a co-located team area so other members can pick up information by osmosis.', 1),
  (0, 32, 'أُضيف إلى بيان أجايل (Agile Manifesto) اثنا عشر مبدأً توضيحياً لمساعدة المشاريع والفرق على فهم قيم أجايل. أي مما يلي هو مبدأ توضيحي صحيح؟', 'The Agile manifesto has twelve clarifying principles added to it to help projects and teams understand the Agile values. Which of the below is a correct clarifying principle?', 'في فريق أجايل، البرمجيات العاملة هي المقياس الأساسي للتقدم.', 'In an Agile team, working software is the primary measure of progress.', 1),
  (0, 33, 'أنت جديد في مشروع أجايل الخاص بك، والفريق يمر بمرحلة التشكيل (Forming). كيف تساعد الفريق على التحسن مع تقدم المشروع؟', 'You are new to your Agile project, and the team are working through the forming stages. How do you help the team improve as the project progresses?', 'يستخدم أجايل الاجتماعات الاستعادية (Retrospectives) في نهاية كل تكرار مع الفريق بأكمله، لطرح الأسئلة: «ما الذي سار على ما يرام؟» و«ما الذي لم يسر على ما يرام؟» و«ماذا تعلمت؟» و«ما الذي لا يزال يحيّرني؟». وتُحوَّل الدروس المستفادة من هذه الجلسة إلى إجراءات وتُدمج في التكرارات المستقبلية للتحسن بسرعة.', 'Agile uses retrospectives at the end of each iteration with the whole team, to ask “What went well?” “What did not go well?” What did I learn?” and “What still puzzles me?” The lessons from this session are actioned and built back into future iterations to improve quickly.', 1),
  (0, 34, 'أنت مدير مشروع أجايل تعمل على متطلبات المنتج لصالح مالك المنتج وراعي المشروع التنفيذي. يثير راعي المشروع مخاوف من أن فريق التطوير لا يفهم المتطلبات فهماً كاملاً. ماذا ستفعل بعد ذلك؟', 'You are the Agile project manager working through the product requirements for the product owner and executive project sponsor. The project sponsor raises concerns that the development team do not fully understand the requirements. What will you do next?', 'يستخدم أجايل نماذج مرئية سريعة أو نماذج أولية (Prototypes) مثل لوحات القصة المصورة (Storyboards) أو الإطارات السلكية (Wireframes) أو النماذج، للوصول إلى فهم سريع للمتطلبات وتوافق في الآراء من جميع أصحاب المصلحة.', 'Agile uses fast visual mock-ups or prototypes such as storyboards, wireframes, or models, to get a quick understanding of the requirements and consensus from all stakeholders.', 1),
  (0, 35, 'طلب منك سكرم ماستر (Scrum Master) في مشروع أجايل الخاص بك إجمالي زمن الانتظار الكلي (Lead Time) لميزة معينة. فتجمع زمن الدورة (Cycle Time) لجميع البطاقات التي أسهمت في تلك الميزة. ما العاملان الآخران اللذان يجب أن تأخذهما في الاعتبار عند حساب إجمالي زمن الانتظار الكلي؟', 'The scrum master on your Agile project has asked you for the total lead time of a particular feature. You add up the cycle time of all the cards that contributed to that feature. What other two factors must you take into consideration when calculating total lead time?', 'زمن الانتظار الكلي (Lead Time) مفهوم مستمد من لين (Lean) ونظام تويوتا للإنتاج. وكلما كنت تحسب زمن الدورة (Cycle Time) (للبنود الأصغر مثل العمليات أو بطاقات القصص أو تكرار في مشروع أكبر) أو زمن الانتظار الكلي (للبنود الأكبر مثل الميزات أو المشروع نفسه)، يجب أن تأخذ في الاعتبار كلاً من الوقت المضيف للقيمة (الذي يسهم مباشرة في النتيجة التي يحصل عليها العميل) والوقت غير المضيف للقيمة (الذي لا يسهم مباشرة في النتيجة التي يحصل عليها العميل).', 'Lead time is a concept from Lean and the Toyota Production System. Whenever you are calculating Cycle time (smaller items such as processes, story cards, or an iteration in a larger project) or Lead time (larger items such as features or the project itself) you must take into consideration both value-added time (that directly contributes to the customer outcome) and non-value-added time (that does not directly contribute to the customer outcome).', 1),
  (0, 36, 'عند العمل في فريق أجايل، من الشائع استخدام النماذج الأولية (Prototypes) والعروض التوضيحية والمراجعات والإطارات السلكية (Wireframes) ولوحات القصة المصورة (Storyboards) لاستخلاص التغذية الراجعة من العميل أو مالك المنتج. ما فائدة استخدام هذه الأدوات؟', 'When working in an Agile team it is common to use prototypes, demonstrations and reviews, wireframes and storyboards to elicit feedback from the customer or product owner. What is the benefit of using these tools?', 'تُعد النماذج الأولية والإطارات السلكية ولوحات القصة المصورة وسائل مهمة لجمع التغذية الراجعة، وتتيح تلك التغذية الراجعة لجميع أصحاب المصلحة مناقشة المتطلبات وميزات المنتج والاتفاق عليها قبل إنفاق المال على التطوير الفعلي.', 'Prototypes, wireframes and storyboards are important ways to gather feedback, and that feedback allows all stakeholders to discuss and agree on the requirements and product features before money is spent on actual development.', 1),
  (0, 37, 'أنت على وشك إنهاء التكرار الأول في مشروع أجايل الخاص بك، وقد حددت موعداً لاجتماع استعادي (Retrospective) للفريق بأكمله. يسأل أحد أعضاء الفريق عن سبب عقد هذا الاجتماع وما إذا كان حضوره ضرورياً حقاً. بماذا ستخبره؟', 'You are finishing up the first iteration on your Agile project and have set a retrospective meeting for the whole team. One member of the team asks why we have this meeting and if they really need to go. What will you tell them?', 'الاجتماعات الاستعادية هي اجتماعات محددة في نهاية كل سبرنت تطلب التغذية الراجعة بفاعلية من خلال أسئلة معينة: ما الذي سار على ما يرام، وما الذي لم يسر على ما يرام، وما الذي لا يزال يحيّرني؟ وتُدمج الإجراءات الناتجة عن هذه الأسئلة في عمل الفريق في التكرارات المستقبلية.', 'Retrospectives are a set meeting at the end of each sprint that actively ask for feedback with certain questions: What went well, what didn’t go well, what still puzzles me? The actions from these questions are built back into the team in future iterations.', 1),
  (0, 38, 'لقد كنت تنجز زيادات (Increments) صغيرة وقابلة للاستخدام من القيمة ضمن فريق أجايل الخاص بك. وعند رفع التقارير إلى راعي المشروع، يُشار إلى التكرار الأخير على أنه «فشل سريع» (Fast Failure). ماذا يعني هذا؟', 'You have been completing small, usable increments of value as part of your Agile team. When reporting back to the project sponsor of this project, the last iteration is referred to as a “fast failure.” What does this mean?', 'يعمل أجايل وفق مفهوم تسليم زيادات من القيمة. ويعني الفشل السريع أن تلك الميزة أو جهد إثبات المفهوم (Proof-of-Concept) لم ينجح. ومن خلال الفشل السريع وبزيادات صغيرة، يتمكن فريق المشروع من التعلم والتكيف بسرعة وبتكلفة أقل بكثير.', 'Agile operates on the concept of delivering increments of value. Fast failure means that particular feature or proof-of-concept effort was not successful. By failing fast and in small increments, the project team is able to learn and adjust quickly and at a much lower cost.', 1),
  (0, 39, 'قررت المنظمة التي تعمل فيها التحول نحو أسلوب عمل أجايل ونهج دورة حياة المشروع الخاص به. أي مما يلي يصف دورة حياة مشروع أجايل؟', 'The organisation you are working in has decided to move towards an Agile way of work and project lifecycle approach. Which of the below is how you would describe an Agile project lifecycle?', 'دورة حياة مشروع أجايل هي مزيج من دورة الحياة التكرارية (Iterative) (حيث نجمع التغذية الراجعة للتحسين) ودورة الحياة التزايدية (Incremental) (حيث نسلّم ميزات أصغر قابلة للاستخدام وذات قيمة لعميلنا).', 'The Agile project lifecycle is a combination of Iterative (where we gather feedback to improve) and Incremental project lifecycles (where we deliver smaller usable features of value to our customer).', 1),
  (0, 40, 'هناك أربعة نُهج رئيسية لدورة الحياة لإدارة المشروع، مع تنويعات بينها. ما إحدى خصائص نهج دورة الحياة «التكرارية» (Iterative)؟', 'There are four main lifecycle approaches to managing a project, with variations in between. What is one of the characteristics of an "Iterative" lifecycle approach?', 'دورة حياة المشروع التكرارية «تتكرر» نحو النجاح. فهي تستخدم النماذج الأولية والإصدارات غير المطروحة من المنتج لجمع التغذية الراجعة والتحسين قبل إطلاقه.', 'An Iterative project lifecycle “iterates” towards success. It uses prototypes and unreleased versions of the product to gather feedback and improve before releasing it.', 1),
  (0, 41, 'أنت تعمل مع فريقك خلال اجتماع تخطيط السبرنت (Sprint Planning). وقد حدد الفريق أحجام البطاقات ورتّب أولويات قائمة الأعمال المتراكمة (Backlog). ماذا ستفعل بعد ذلك لتحديد مقدار العمل الذي يمكن إنجازه خلال هذا التكرار؟', 'You are working through a sprint planning meeting with your team. The team have sized up the cards and prioritised the backlog. What will you do next to determine how much work can be done during this iteration?', 'السرعة (Velocity) هي مقدار العمل (مقاساً بالنقاط أو الساعات أو البطاقات أو أي وحدة تريدها) الذي ينجزه الفريق في المتوسط خلال سبرنت معين. ومن خلال مقارنة إجمالي نقاط البطاقات التي ترغب في إكمالها بما هو ممكن وفق سرعة الفريق، ستعرف ما هو ممكن ويمكنك التعديل حسب الحاجة.', 'Velocity is the amount of work (measured by points, hours, cards or anything you wish) a team completes on average in a given sprint. By checking the total points for the cards you wish to complete against what is possible via the team velocity, you will know what is possible and can adjust as necessary.', 1),
  (0, 42, 'أنت مدير مشروع أجايل تعمل على الميزة التالية من منتجك. طلب منك مالك المنتج تقديراً للمدة التي قد يستغرقها إكمال الميزات المتبقية. فتلجأ إلى مخطط سرعة (Velocity) الفريق. لماذا؟', 'You are an Agile project manager working on the next feature of your product. The product owner has asked you for an estimate on how long the remainder of the features may take to complete. You look to the team’s velocity chart. Why is this?', 'متوسط السرعة، أو العمل المنجز خلال كل تكرار، هو أفضل مؤشر للتنبؤ بالسرعة المستقبلية، لأن التكرارات السابقة تتضمن عادةً جميع المهام والعقبات التي قد تؤثر في عمل الفريق.', 'The average velocity, or work completed during each iteration, is the best predictor of future velocity, because previous iterations typically include all tasks and pitfalls that may impact their work.', 1),
  (0, 43, 'أنت قائد أجايل أو سكرم ماستر (Scrum Master) لفريق أجايل الخاص بك، والتخطيط للتكرار التالي على وشك أن يبدأ. ماذا ستفعل أولاً؟', 'You are the Agile lead or Scrum Master for your Agile team and planning for the next iteration is about to begin. What will you do first?', 'خلال تخطيط التكرار، ينبغي أن يكون الفريق قد جزّأ الميزات بالفعل إلى بطاقات قصص. والآن حان وقت إعادة ترتيب أولويات البطاقات التي يمكن إنجازها بناءً على القيمة التجارية (Business Value) وسرعة الفريق (ما يمكن إكماله).', 'During iteration planning the team should have already broken down features into story cards. Now is the time to reprioritise the cards that can be done based on the business value and the team velocity (what can be completed).', 1),
  (0, 44, 'أنت في منتصف سبرنت مع فريق أجايل الخاص بك، وتدفع المشروع قدماً من خلال اجتماعات الوقوف اليومية (Daily Stand-up). ما هو اجتماع الوقوف؟', 'You are in the middle of a sprint with your Agile team, and moving the project forward with daily stand-up meetings. What is a stand-up meeting?', 'اجتماع الوقوف اليومي هو اجتماع قصير، يُعقد عادةً حول لوحة كانبان (Kanban Board)، يذكر فيه أعضاء الفريق ما أنجزوه منذ الأمس، وما سيفعلونه اليوم، وأي شيء يعيق تقدمهم.', 'The daily stand-up is a short meeting, usually around the Kanban board, where the team say what they accomplished since yesterday, what they will do today, and anything that is blocking their progress.', 1),
  (0, 45, 'أنت مدير مشروع أجايل تعمل على مشروع برمجيات، وقد حدد فريق التطوير خطراً كبيراً يهدد تسليم ميزة معينة. وهذه الميزة غير مجدولة إلا في وقت متأخر جداً من المشروع. ماذا ستفعل بعد ذلك؟', 'You are the Agile project manager working on a software project, and the development team have identified a major risk for the delivery of a certain feature. That feature is not scheduled until very late in the project. What will you do next?', 'تُعطى مخاطر أجايل الأولوية في وقت مبكر من التطوير، من أجل تقليل تلك المخاطر وإزالتها. ويتم عمل الاستكشاف عادةً من خلال بطاقة سبايك (Spike)، لكن ليس من الضروري أن يقوم به الفريق بأكمله. خصص قدراً معيناً من الوقت له، ثم أعطِ الخطر الأولوية مبكراً حتى تتم معالجته وتعرف ما تتعامل معه.', 'Agile risks are prioritised early in development, to reduce and remove those risks. Discovery work is typically done with a spike card, but does not need to be done by the whole team. Allocate a certain amount of time to it, then prioritise the risk early so it is taken care of and you know what you are dealing with.', 1),
  (0, 46, 'يستخدم فريق مشروعك العامل بأجايل (Agile) إطار سكرم (Scrum) لإدارة العمل والتسليمات في مشروعك. أيٌّ مما يلي ليس من أحداث سكرم أو مخرجاته (Artifacts)؟', 'Your Agile project team is using Scrum to manage the work and deliverables for your project. Which of the below is not one of the Scrum events or artefacts?', 'يعمل سكرم بقائمة أعمال المنتج أو الميزات المتراكمة (Product/Feature Backlog)، وقائمة أعمال السبرنت المتراكمة (Sprint Backlog)، ويسلّم على شكل زيادات (Increments) أو ميزات. ويُوصى عادةً بأن تعمل فرق أجايل في مساحة يتواجد فيها الفريق في مكان واحد لضمان التعاون السريع، إلا أن ذلك ليس من أحداث سكرم أو مخرجاته ولا من سكرم نفسه.', 'Scrum works with a Product or Feature Backlog, a Sprint Backlog, and delivers in increments or features. Agile teams are typically recommended to work in a co-located space to ensure fast collaboration, however this is not one of the events or artefacts or Scrum itself.', 1),
  (0, 47, 'يعمل فريق أجايل (Agile) لديك بإطار سكرم (Scrum) منذ فترة، وأصبح على دراية جيدة بأحداثه وطقوسه. وقد طُلب منك شرح ذلك لأصحاب المصلحة الآخرين داخل المنظمة. أيٌّ مما يلي ليس مثالاً على حدث أو طقس من طقوس سكرم؟', 'Your Agile team has been working with Scrum for some time now and have become quite familiar with its events and ceremonies. You are asked to explain this to other stakeholders within the organisation. What is NOT an example of a Scrum event or ceremony?', 'مجلس مراقبة التغيير (Change Control Board) جزء نموذجي من دورة حياة المشروع التنبؤية أو الشلال (Predictive/Waterfall)، وليس أسلوب عمل خاصاً بأجايل أو سكرم. ويقوم فيه أصحاب المصلحة الرئيسيون بمراجعة أي تغييرات على النطاق أو الجدول الزمني أو التكلفة المحددة مسبقاً، والموافقة عليها أو رفضها بينما يسير المشروع نحو الإنجاز.', 'The Change Control Board is a typical part of a predictive or Waterfall project lifecycle, not an Agile or Scrum way of work. It has key stakeholders review any changes to the pre-assigned scope, schedule or cost, and approve or decline as the project works towards completion.', 1),
  (0, 48, 'سكرم (Scrum) إطار عمل لفريق واحد لإدارة تطوير المنتجات. وهناك أحداث وطقوس وأدوار ومسؤوليات محددة داخل فريق سكرم. أيٌّ مما يلي ليس دوراً أو مسؤولية في فريق سكرم؟', 'Scrum is a single-team framework for managing product development. There are certain events, ceremonies and roles and responsibilities within a Scrum team. Which of the below is NOT a role or responsibility in a Scrum team?', 'المخاطر والجودة مسؤولية الفريق بأكمله في أسلوب عمل أجايل (Agile)، ولذلك لا يتحمل شخص واحد عادةً مسؤوليتها. فمالك المنتج (Product Owner) يضمن تسليم الميزات الصحيحة، وفريق التطوير يضمن إعادة هيكلة الشيفرة (Refactoring) بانتظام، وسكرم ماستر (Scrum Master) يضمن تحسين عملية الفريق بمرور الوقت، ومختبر الجودة يضمن خلو الميزات من العيوب.', 'Risk and Quality are the responsibility of the whole team in an Agile way of work, and so typically a single person is not responsible for it. The product owner ensures the right features are delivered, the development team ensures the code is refactored regularly, the Scrum Master ensures the team process is improved over time, and the Quality tester ensures features are free of defects.', 1),
  (0, 49, 'القيادة الخادمة (Servant Leadership) من الركائز الأساسية لفريق أجايل (Agile)، حيث يُشجَّع على القيادة ومشاركة الفريق والانفتاح. أيٌّ مما يلي ليس من خصائص القائد الخادم؟', 'Servant leadership is one of the key foundations to an Agile team, where leadership and team participation and openness are encouraged. Which of the below is NOT one of the characteristics of a servant leader?', 'تعمل أجايل والقيادة الخادمة (Servant Leadership) على بناء الأمان النفسي والانفتاح والنمو وضمان خلو العمل من العوائق. ويبدأ ذلك بدور سكرم ماستر (Scrum Master) أو مدرّب/قائد أجايل، لكنه يمتد ليشمل الفريق بأكمله.', 'Agile and Servant Leadership work by building towards psychological safety, openness, growth and ensuring work is free from blockers. It starts with the Scrum Master or Agile coach/leader role, but expands to the whole team.', 1),
  (0, 50, 'تعمل مع فريق أجايل (Agile) لديك على تقدير حجم بطاقات القصص ووضعها في التكرارات القادمة. وتلاحظ أن النقاط المخصصة لبطاقات القصص تزداد كبراً مع كل إصدار. لماذا قد يحدث ذلك؟', 'You are working with your Agile team to size the story cards and place them in upcoming iterations. You notice that the points allocated to story cards are getting bigger and bigger with each release. Why might this be happening?', 'تستوعب أجايل تغيّر النطاق، وينبغي أن تصل إلى إيقاع منتظم في السرعة (Velocity)، مما يستبعد الخيارين A وD. والإجابة الأفضل هي الدين التقني (Technical Debt)، حيث قد تُدفع الشيفرة إلى بيئة الإنتاج على عجل دون تبسيطها أو إعادة هيكلتها. ومع كل إصدار لاحق، يتولد مزيد من العمل للبناء على الشيفرة غير المنظمة والالتفاف حولها.', 'Agile accommodates for changing scope, and should find a regular rhythm of velocity, ruling out A and D. The best answer is technical debt, where code may be rushed to production without being simplified or refactored. With each subsequent release it creates more work to build on and work around disorganised code.', 1),
  (0, 51, 'راعي مشروع فريق أجايل (Agile) لديك على دراية جيدة بمصطلحات وأساليب لين (Lean) وأجايل. وقد طلبت منك متوسط زمن الدورة (Cycle Time) ومتوسط زمن الانتظار الكلي (Lead Time) للمشروع حتى الآن. ماذا ستقدم لها؟', 'The project sponsor of your Agile team is quite familiar with Lean and Agile terms and methods. She has asked you for the average Cycle time and average Lead time for the project so far. What will you give her?', 'زمن الدورة (Cycle Time) هو الوقت اللازم للمهام الأقصر، وغالباً ما تكون بطاقات القصص في بيئة أجايل. وتشكّل بطاقات القصص هذه ميزة. أما زمن الانتظار الكلي (Lead Time) فيقيس الوقت اللازم لإنجاز ميزة (عدة بطاقات قصص) من البداية إلى النهاية.', 'Cycle time is the time for shorter tasks – most often story cards in an Agile environment. Those story cards make up a feature. Lead time measures the time to complete a feature (multiple story cards) from beginning to end.', 1),
  (0, 52, 'تراجع سرعة (Velocity) فريق أجايل (Agile) لديك وتلاحظ أنها ازدادت خلال التكرارين الأخيرين. ما السبب المحتمل لذلك؟', 'You are going over the velocity of your Agile team and notice it has increased over the last two iterations. What might be the reason for this?', 'السرعة (Velocity) والإنتاجية (Throughput) مفهومان متشابهان. وعادةً ما تكون السرعة هي العمل الذي أنجزه الفريق بأكمله. والدين التقني (Technical Debt) هو حلول فوضوية أو مرتجلة أو متضخمة قد تعمل في البداية لكنها غالباً ما تبطئ التقدم مستقبلاً. وتنظيف بعض منها عبر "إعادة هيكلة" الشيفرة (Refactoring) يمكن أن يحسّن سرعة الفريق. أما التقدير الأفضل فقد يزيد السرعة أو ينقصها، لكنه يجعلها أكثر استقراراً.', 'Velocity and throughput are similar concepts. Typically velocity is the work completed by the entire team. Technical Debt is messy, hacky or bloated solutions that might work initially but can often slow down future progress. Cleaning some of this up by "Refactoring" the code can improve the team''s velocity. Better estimation might increase or decrease Velocity, but will make it more stable.', 1),
  (0, 53, 'أنت مدير مشروع أجايل (Agile) تعمل مع فريق أجايل لديك وتناقشون العيوب التي أُثيرت في المشروع حتى الآن. وللحصول على رؤية أدق للجهد المبذول لكل بطاقة، تطلب من مختبر الجودة البدء في تتبع زمن دورة العيوب (Defect Cycle Time). عمّ سيقدم تقريره؟', 'You are an Agile project manager working with your Agile team and talking through the defects raised in the project so far. To get a more accurate view of effort per card, you ask the quality tester to begin tracking the defect cycle time. What will they report back on?', 'زمن الدورة (Cycle Time) هو مقياس الوقت الذي تستغرقه زيادة صغيرة، غالباً بطاقة قصة، من البداية إلى النهاية. وبالتالي فإن زمن دورة العيوب هو قياس الوقت الذي استغرقه إصلاح عيب واحد بعد اكتشافه.', 'Cycle time is the measure of time of a smaller increment, often a story card, from start to finish. Therefore, defect cycle time is the measurement of how long it took to fix a single defect once it was discovered.', 1),
  (0, 54, 'تتابع مع مختبر الجودة في فريق أجايل (Agile) لديك، فيخبرك بوجود عدد من العيوب المتسربة (Escaped Defects) في آخر ميزة مكتملة. إلامَ يشير؟', 'You are checking in with the quality tester in your Agile team, and they advise you that there are a number of escaped defects in the most recently completed feature. What are they referring to?', 'تُسمى العيوب التي تتجاوز الاختبار وتصل إلى الإصدار بالعيوب المتسربة (Escaped Defects). وتزداد تكلفة العيوب ومخاطرها كلما اقتربت من بيئة التشغيل الفعلي، مما يجعلها أكثر أنواع العيوب تكلفة في الإصلاح.', 'Defects that make it through testing and into a release are called escaped defects. The cost and risk increases for defects the closer they are to a live environment, making these the most expensive type of defect to fix.', 1),
  (0, 55, 'تؤكد نُهج أجايل (Agile) على القيادة الخادمة (Servant Leadership) لتمكين الفرق. والقيادة الخادمة هي ممارسة القيادة من خلال خدمة الفريق، وفهم احتياجات أعضاء الفريق وتطورهم ومعالجتها لتمكينهم من تحقيق أعلى أداء ممكن. يتعامل القادة الخادمون مع عمل المشروع وفق هذا الترتيب:', 'Agile approaches emphasise Servant Leadership to empower teams. Servant leadership is the practice of leading through service to the team, understanding and addressing the needs and development of the team members to enable the highest performance possible. Servant leaders approach project work in this order:', 'يتعامل القائد الخادم (Servant Leader) مع العمل بدءاً بالغاية أو "السبب" وراء العمل، ثم يعمل على تنمية الأفراد وتطويرهم، وأخيراً يضمن وجود عملية متينة لإنجاز العمل.', 'The Servant Leader approaches work starting with the purpose or “why” behind the work, then works with growing and developing people, and finally ensures a solid process for making the work happen.', 1),
  (0, 56, 'أنت جزء من فريق أجايل (Agile) منذ فترة، وتعمل على جوانب القيادة الخادمة (Servant Leadership) لتحسين نتائج فريقك. أيٌّ مما يلي ليس من خصائص القائد الخادم؟', 'You have been part of an Agile team for some time, working on the aspects of servant leadership to improve the results of your team. What is NOT one of those characteristics of a servant leader?', 'يوجّه القائد الخادم في أجايل الفريق، ويعزز الأمان النفسي والثقة، ويعزز طاقة الآخرين وذكاءهم. ولا يتضمن هذا النهج القيادة التوجيهية/الاستبدادية (Directive Leadership) أو إجبار الآخرين على فعل ما تقوله.', 'The servant leader in Agile coaches the team, promoting psychological safety and trust, and promoting the energy and intelligence of others. The approach does not include directive leadership, or forcing others to do what you say.', 1),
  (0, 57, 'صُممت المبادئ التوضيحية الاثنا عشر في أجايل (Agile) لإضفاء مزيد من الوضوح على القيم الأساسية لبيان أجايل (Agile Manifesto). أيٌّ مما يلي أحد المبادئ التوضيحية الاثني عشر؟', 'The Twelve Clarifying Principles in Agile were designed to give more clarity to the Agile manifesto core values. Which of the following is one of the twelve clarifying principles?', 'تركّز أجايل على التسليم المبكر والمستمر للقيمة، غالباً في بيئة البرمجيات، ولكن أيضاً في أي عمل معرفي مثل التصميم.', 'Agile focuses on early and continuous delivery of value – most often in a software environment but also in any knowledge work, such as design.', 1),
  (0, 58, 'لقد بنيت فريق أجايل (Agile) ذا خبرة وحققتم تسليماً مستمراً لمنظمتكم. وقد انتقل مالك المنتج (Product Owner) الذي كان معك منذ البداية إلى وظيفة أخرى، وينضم إلى الفريق زميل جديد ذو خبرة محدودة جداً. أيٌّ مما يلي لن تخبره به بشأن دور مالك المنتج؟', 'You have built an experienced Agile team and have delivered constantly for your organisation. The product owner who has been with you since the beginning has taken another job, and a new team mate joins the team – one with very little experience. Which of the below will you NOT tell them regarding the Product Owner role?', 'يمثل دور مالك المنتج العميل أو الجهة التي تستفيد من القيمة التي يسلّمها فريق أجايل. ولهذا السبب، غالباً ما يمتلكون معرفة عميقة بذلك المجال ويعرفون ما سيحقق أكبر قيمة، ويكونون قادرين على ترتيب أولويات بنود العمل بكفاءة.', 'The product owner role represents the customer or the area gaining the benefit of the value delivered by the Agile team. Because of this, they often have deep knowledge of that area and know what will bring the most value, and are able to prioritise work items efficiently.', 1),
  (0, 59, 'لقد سلّمت نصف الميزات الموجودة في قائمة الأعمال المتراكمة (Backlog) لمشروع أجايل (Agile) الخاص بك. ولاحظت وجود اختلاف كبير في عدد العيوب على مدار التكرارات الثلاثة الأخيرة، فتطلب من الفريق التحقق من كلٍّ من التباين ذي السبب الشائع (Common Cause) والتباين ذي السبب الخاص (Special Cause). فيمَ سيحققون؟', 'You have delivered half of the features in the backlog for your Agile project. You’ve noticed there is quite a difference in the number of defects over the last three iterations, and you ask the team to investigate both common cause and special cause variation. What will they investigate?', 'يُقسَّم التباين في لين (Lean) إلى تباين ذي سبب شائع، وهو ناجم عن العمليات الاعتيادية، وتباين ذي سبب خاص، وهو ناجم عن عوامل خاصة أو جديدة.', 'Variation in Lean is separated into common cause, which is caused by normal operations, and special cause, which is caused by special or new factors.', 1),
  (0, 60, 'تعمل في فريق أجايل (Agile) جديد وقد راجعت سرعة الفريق (Velocity) على مدار التكرارات الثلاثة الماضية. كان الحد الأقصى لعدد النقاط المنجزة 35، والحد الأدنى 25. ماذا ستفعل بعد ذلك؟', 'You are working in a new Agile team and have reviewed the team velocity over the past three iterations. The maximum number of points completed was 35, and the fewest was 25. What will you do next?', 'تقوم أجايل على التسليم المستمر والمستدام. ودفع الفريق إلى ما يتجاوز حدوده المعروفة ليس جزءاً من ممارسات أجايل. وبمجرد معرفة سرعة الفريق (Velocity)، من الممارسات الجيدة تحديد حد للعمل قيد التنفيذ (WIP) للتكرارات المستقبلية حتى لا يُثقَل كاهل الفريق. ولا يزال بإمكان أعضاء الفريق سحب بطاقات جديدة للعمل عليها إذا أنهوا العمل الحالي، وعندها يمكنك مراجعة سرعة الفريق.', 'Agile works on continuous, sustainable delivery. Pushing the team beyond their known limits is not a part of Agile practice. Once the team Velocity is known it is good practice to set a WIP limit for future iterations so as to not overburden the team. Team members can still pull in new cards to work on if they finish existing work, and at that time you can review the team velocity.', 1),
  (0, 61, 'أنت مالك المنتج (Product Owner) في فريق أجايل (Agile) ولديك قائمة بالميزات في قائمة الأعمال المتراكمة (Backlog) تحتاج إلى تطوير. وقد خُصصت لكل ميزة قيمة بالدولار تمثل العائد على الاستثمار. وترغب في أن تكون قائمة أعمال متراكمة معدَّلة وفق المخاطر (Risk-Adjusted Backlog). ماذا ستفعل بعد ذلك؟', 'You are the product owner in an Agile team and have a list of features in a backlog that need to be developed. Each feature is assigned a dollar value, representing the return on investment. You would like it to be a risk-adjusted backlog. What will you do next?', 'قائمة الأعمال المتراكمة المعدَّلة وفق المخاطر (Risk-Adjusted Backlog) هي قائمة أعمال سبرنت أو إصدار متراكمة تحتوي على مهام الاستجابة للمخاطر القابلة للتنفيذ. وتُرتَّب أولويات هذه المهام مقابل الميزات الاعتيادية الموجودة أيضاً في القائمة، من أجل التعديل وفق المخاطر.', 'The risk-adjusted backlog is a sprint or release backlog containing risk response tasks for actionable risks. These will be prioritised against the normal features, also in the backlog, to adjust for risk.', 1),
  (0, 62, 'أنت مدير مشروع أجايل (Agile) تحلل المخاطر لكل ميزة في قائمة الأعمال المتراكمة (Backlog) من خلال تعيين درجة احتمالية ودرجة أثر لكل خطر، ثم ضربهما لحساب شدة الخطر. كيف سيتعامل فريق أجايل مع البنود ذات المخاطر الأعلى؟', 'You are the Agile project manager analysing the risk for each feature in your backlog by assigning a probability and an impact score to each risk, then multiplying them to calculate risk severity. How will the Agile team handle items with the highest risk?', 'تكون المخاطر في أعلى مستوياتها في بداية المشروع قبل إنجاز البنود. وبإنجاز البنود عالية المخاطر أولاً، فإنك تقلل بشكل كبير تلك المخاطر وتهديد المجهولات في مراحل لاحقة من المشروع.', 'Risk is highest early in the project before items have been completed. By completing the high-risk items first, you are significantly reducing those risks and the threat of unknowns later on in the project.', 1),
  (0, 63, 'يخبرك سكرم ماستر (Scrum Master) بأن أجايل (Agile) تدمج حل المشكلات في عملياتها بعدة طرق، باستخدام أدوات الشفافية والطقوس. أيٌّ مما يلي ليس مصمماً لكشف المشكلات وحلها؟', 'The Scrum master tells you that Agile builds problem solving into its process in a number of ways, using transparency tools and ceremonies. Which of the following is NOT something that is designed to reveal and solve problems?', 'تعمل الاجتماعات الاستعادية (Retrospectives) ومراجعات السبرنت واجتماعات الوقوف اليومية جميعها على كشف المشكلات التي تنشأ أثناء تسليم المنتج وحلها. أما كتابة قصص المستخدم فهي مهمة مفيدة، لكنها ليست مصممة في حد ذاتها لكشف المشكلات.', 'Retrospectives, Sprint reviews and daily stand-ups all serve to reveal and solve problems that arise during product delivery. Writing user stories is a useful task, but is not itself designed for revealing problems.', 1),
  (0, 64, 'نهج الفريق الكامل (Whole Team Approach) في أجايل (Agile) جزء مهم من تكوين الفريق متعدد الوظائف المناسب. وميسّر الفريق (Team Facilitator) عضو رئيسي ضمن الفريق الكامل. أيٌّ مما يلي غير صحيح بشأن دور ميسّر الفريق؟', 'The Whole Team Approach in Agile is an important part of creating the right cross-functional team. The team facilitator is a key member within the whole team. What is NOT correct regarding the Team Facilitator role?', 'يساعد دور ميسّر الفريق (Team Facilitator)، أو سكرم ماستر أو القائد الخادم أو قائد المشروع، على تنمية أعضاء الفريق ليطوروا مهاراتهم القيادية الخاصة، وتحتاج جميع فرق أجايل إلى هذا الدور ضمن فريقها. كما يمكن لأي شخص في الفريق أداؤه إذا لم يكن هناك دور محدد له. ولست بحاجة إلى شهادة جامعية في الأعمال، لكنك بحاجة إلى إزالة العوائق وتيسير حل المشكلات.', 'The Team facilitator role, or Scrum Master, servant leader, project lead, helps grow team members into their own leadership skills and all Agile teams need this on their team. It also can be performed by anyone in the team if there is no specific role for it. You do not need a degree in business, but you do need to remove blockers and facilitate problem solving.', 1),
  (0, 65, 'تعيد ترتيب فريق أجايل (Agile) حالي، وتعلم أن فرق أجايل متعددة الوظائف. أي نوع من أعضاء الفريق ستختار أثناء إعادة ترتيب الفريق؟', 'You are rearranging a current Agile team, and you know that Agile teams are cross-functional. What sort of team members will you select as you rearrange the team?', 'يتكون فريق أجايل من متخصصين معمّمين (Generalizing Specialists)، أو أفراد ذوي مهارات على شكل T لديهم مجال معرفة عميق واحد ونطاق واسع من الخبرة في مجالات أخرى. والفريق بأكمله مسؤول عن المخاطر في فريق أجايل. أما تقليص حجم الفرق فلا ينطبق إلا على الفرق الناضجة التي تؤدي بشكل جيد ويمكنها تقليل الوقت والجهد.', 'An Agile team is made up of generalising specialists, or “T-shaped” people with one deep knowledge area and a wide range or experience in other areas. The whole team is responsible for Risk in an Agile team. Shrinking Teams is only applicable for mature teams who are performing well and can reduce time and effort.', 1),
  (0, 66, 'تساعد المنظمة على تشكيل فريق أجايل (Agile) جديد وتتأكد من أنهم يأخذون نهج الفريق الكامل (Whole Team Approach) في الاعتبار. أيٌّ مما يلي غير صحيح بشأن نهج الفريق الكامل؟', 'You are helping the organisation set up a new Agile team and making sure they consider the Whole Team Approach. What is NOT correct regarding the Whole Team Approach?', 'يضمن نهج الفريق الكامل أن يكون أعضاء الفريق متعددي المهارات فعلاً، وأن يمتلكوا تخصصاً عميقاً واحداً على الأقل.', 'The whole team approach ensures team members ARE multi-skilled, and have at least one deep specialty.', 1),
  (0, 67, 'تواجه صعوبة في اختيار أعضاء فريق أجايل (Agile) الجديد في منظمة جديدة. أيٌّ مما يلي غير صحيح بشأن عضو الفريق متعدد الوظائف في نهج الفريق الكامل (Whole Team Approach)؟', 'You are having trouble selecting team members for your new Agile team in a new organisation. What is NOT true about the cross functional team member in the Whole Team Approach?', 'تستخدم فرق أجايل الإدارة المرئية (Visual Management) مهما بلغت براعتها. فأساليب مثل كانبان (Kanban) واجتماعات الوقوف والاجتماعات الاستعادية (Retrospectives) ومخططات الإنجاز التنازلي (Burndown Charts) تُستخدم لتعزيز العمل الجماعي الأفضل، بغض النظر عن المهارة.', 'Agile teams will use visual management no matter how good they are. Methods like Kanban, Stan-ups, Retrospectives, Burn-down charts are used to increase better team working, regardless of skill.', 1),
  (0, 68, 'هناك ثلاثة أنواع رئيسية من الأدوار في فريق أجايل (Agile). ويضم فريق أجايل ممثلين لمالك المنتج (Product Owner)، وأعضاء الفريق متعددي الوظائف، و:', 'There are three main types of role in an Agile team. The Agile team includes representatives for the Product Owner, cross functional team members, and:', 'ميسّر الفريق (Team Facilitator)، ويُعرف أيضاً بسكرم ماستر (Scrum Master) أو مدرّب الفريق أو مدير التكرار أو مدير المشروع أو القائد الخادم وأسماء أخرى كثيرة. ويتمثل دوره في المساعدة على إثارة العوائق وإزالتها للفريق، وضمان تدفق نشط للعمل، وحل المشكلات مع الفريق عند الحاجة.', 'The Team Facilitator, also known as the Scrum Master, Team Coach, Iteration Manager, Project Manager, Servant Leader and many other names. Their role is to help raise and remove blockers for the team, ensure an active flow of work, and problem solve with the team when needed.', 1),
  (0, 69, 'تعمل خلال التكرار مع فريق أجايل (Agile) لديك، وتواجه صعوبة في إنجاز إحدى بطاقات القصص في السبرنت. فهي تعتمد على إنجاز شيء آخر، والشخص المعني غائب. ماذا ستفعل بعد ذلك؟', 'You are working through the iteration with your Agile team, and are having trouble completing one of the story cards in the sprint. It is dependant on something else being done and the contact is away. What will you do next?', 'يتم حل المشكلات مع فريق أجايل. وتُثار العوائق في أقرب وقت ممكن، على الأقل خلال اجتماع الوقوف اليومي، حتى يتكاتف الفريق حول المشكلة، ويحصل على المساعدة من أي خبراء لازمين، ويمضي قدماً.', 'Problem solving is done with the Agile team. Blockers are raised as soon as possible – at least during a daily stand-up, so the team can swarm around the problem, get help from any experts needed, and move on.', 1),
  (0, 70, 'مالك المنتج (Product Owner) الذي يمثّل جهة الأعمال في مشروع أجايل الخاص بك معتاد على أسلوب قيادة أقرب إلى الأسلوب الديكتاتوري. أنت توضح له أن القيادة الخادمة (Servant Leadership) تُستخدم في أجايل لضمان بيئة آمنة ومنفتحة. لماذا يُعد هذا مهماً لتطوير المنتج؟', 'The product owner representing the business on your Agile project is used to a more dictator-style of leadership. You explain that servant leadership is used in Agile to ensure a safe and open environment. Why is this important to product development?', 'الأمان النفسي هو أحد أهم مقوّمات الفريق عالي الأداء، وهو يعني امتلاك الأمان اللازم لإظهار الضعف، والاعتراف بالمشكلات، وطلب المساعدة، والتحسّن. ويبدأ ذلك من القائد، وتسهم القيادة الخادمة (Servant Leadership) في تحقيقه.', 'Psychological safety is one of the most important parts of a high-functioning team, which means having the safety to be vulnerable, admit problems, ask for help and improve. It starts with the leader, and servant leadership contributes to this.', 1),
  (0, 71, 'تُعد التغذية الراجعة (Feedback) بأشكالها المتعددة أحد أهم مقوّمات نجاح تسليم المنتج في أجايل. أيٌّ مما يلي يُعد أسلوباً من أساليب أجايل لجمع التغذية الراجعة واستخدامها من أجل التحسين؟', 'Feedback in many different forms is one of the most important parts of a successful Agile product delivery. Which of the below is an Agile method for gathering and using feedback to improve?', 'إن عرض الزيادة (Increment) القابلة للاستخدام التي طُوِّرت خلال التكرار على العميل أو مالك المنتج يضمن جمع التغذية الراجعة بسرعة أكبر بدلاً من جمعها في نهاية المشروع فقط. كما تُعد الاجتماعات الاستعادية (Retrospectives) أسلوباً آخر للحصول على التغذية الراجعة بشأن عملية عمل الفريق.', 'Demonstrating the usable increment developed during an iteration to the customer or product owner ensures feedback is gathered more quickly than only at the end of a project. Retrospectives are another method for feedback on the team process.', 1),
  (0, 72, 'أنت تعمل في مشروع أجايل حيث يضغط ممثل جهة الأعمال للمنتج من أجل تسليم المزيد والمزيد من الميزات في كل تكرار (Iteration). وأنت تعلم أن ما يطلبونه غير ممكن استناداً إلى السرعة (Velocity) الحالية لفريقك. ماذا ستفعل بعد ذلك؟', 'You are working on an Agile project where the product business representative is pushing for more and more features to be delivered in each iteration. You know what they are asking is not possible, based on your team’s current velocity. What will you do next?', 'يخدم فريق أجايل العميل في نهاية المطاف، وفي كثير من الحالات يكون العميل هو مالك جهة الأعمال أو ممثلها. وإذا لم يكن هذا الشخص هو مالك المنتج (Product Owner) أيضاً (أو لم يكن على دراية بطريقة العمل هذه)، فعليك أن تعرض عليه سرعة الفريق (Velocity) مقارنةً بعدد النقاط المخصصة حالياً، وأن تدعوه إلى ترتيب أولويات الميزات التي يريدها لاحقاً. وهذا يمنحه التحكم في القيمة المسلَّمة دون إثقال كاهل الفريق.', 'An Agile team ultimately serves the customer, and in many cases the customer is the business owner or representative. If they are not also the product owner (or familiar with that way of work), you should show them the team velocity versus how many points are currently allotted, and invite them to prioritise the features they want next. This gives them control over the value delivered while not overburdening the team.', 1),
  (0, 73, 'أنت في المراحل الأولى من مشروع جديد، حيث ترغب المنظمة في استخدام نهج أجايل لإدارة أعمال المشروع. وتسألك المديرة التنفيذية كيف سيجعل الفريق الجودة مسؤولية الجميع، ويستفيد من مجموعات المهارات المتنوعة داخل الفريق، ويزيل الاعتماد على المدخلات الخارجية. ما أسلوب أجايل الذي تصفه؟', 'You are in the beginning stages of a new project, where the organisation would like to use an Agile approach to managing the project work. The executive manager asks you how the team will make quality everyone’s responsibility, leverage the various skill sets within the team, and remove reliance on external inputs. What Agile method is she describing?', 'يهدف نهج الفريق الكامل (Whole Team Approach) إلى ضم جميع الأشخاص اللازمين إلى فريق المشروع، ويُفضَّل أن يكون ذلك في مكان واحد. ويشمل أعضاء فريق متعدد الوظائف (Cross-functional Team) يتخصصون في مهارة واحدة ويتقنون بدرجة كافية نطاقاً واسعاً من المهارات الأخرى.', 'The whole team approach aims to bring all necessary people into the project team, ideally in a co-located space. It involves cross-functional team members who specialise in one skill and are fluent enough in a wide range of other skills.', 1),
  (0, 74, 'أنت تعمل في مشروع أجايل منذ فترة، وقد تعطّل عملك بسبب الحاجة إلى خبرة موجودة في فريق آخر. وتحتاج إلى التغلب على الانعزال التنظيمي (Organizational Silos). ماذا ستفعل؟', 'You have been working on an Agile project for some time and have been blocked by the need for expertise in another team. You need to overcome organisational silos. What will you do?', 'هذا يصف نهج الفريق الكامل (Whole Team Approach)، حيث يتم ضم جميع أعضاء الفريق اللازمين ومهاراتهم إلى فريق المشروع.', 'This is describing the Whole Team Approach, where all the necessary team members and their skills are brought into the project team.', 1),
  (0, 75, 'تتوافق مبادئ أجايل التوضيحية الاثنا عشر أيضاً مع أفضل النصائح لسير العمل وإنجاز الأمور. أيٌّ مما يلي يُعد مبدأً توضيحياً صحيحاً فيما يتعلق بسير عمل المشروع؟', 'The twelve Agile clarifying principles also match up with the best advice for workflow and getting things done. Which of the below is a correct clarifying principle when it comes to project workflow?', 'يعزز أجايل التطوير المستدام، حيث لا يُثقل كاهل الفريق ويكون قادراً على العمل بوتيرة ثابتة إلى أجل غير مسمى. احذر من التبديل المتكرر بين المهام أو الضغط لإنجاز قدر كبير جداً من العمل خلال كل تكرار (Iteration)، فهذا سيؤدي إلى إرهاق الأفراد ويبطئ تقدمك في نهاية المطاف.', 'Agile promotes sustainable development, where the team is not overburdened and is able to work at a constant pace indefinitely. Be wary of often switching tasks or pushing for too much work during each iteration – this will burn out individuals and ultimately slow down your progress.', 1),
  (0, 76, 'تتوافق مبادئ أجايل التوضيحية الاثنا عشر أيضاً مع أفضل النصائح بشأن الجودة في المشروع. أيٌّ مما يلي يُعد مبدأً توضيحياً صحيحاً من مبادئ أجايل فيما يتعلق بجودة المشروع؟', 'The twelve Agile clarifying principles also match up with the best advice for quality in a project. Which of the below is a correct Agile clarifying principle when it comes to project quality?', 'على الرغم من أن بعض هذه الإجابات تتوافق مع مبادئ أجايل بشكل عام، فإن "الاهتمام المستمر بالتميز التقني والتصميم الجيد يعزز الجودة" هو المبدأ التوضيحي الوحيد من بين هذه القائمة.', 'While some of these answers match up with the Agile principles in general, only “Continuous Attention to technical excellence and good design enhances quality” is a clarifying principle from this list.', 1),
  (0, 77, 'تتوافق مبادئ أجايل التوضيحية الاثنا عشر أيضاً مع أفضل النصائح للحفاظ على البساطة في المشروع. أيٌّ مما يلي يُعد مبدأً توضيحياً صحيحاً من مبادئ أجايل؟', 'The twelve Agile clarifying principles also match up with the best advice for keeping things simple in a project. Which of the below is a correct Agile clarifying principle?', 'الإجابة الصحيحة هنا هي "البساطة – فن تعظيم كمية العمل غير المنجَز – أمر أساسي"، لكونها مبدأً توضيحياً من مبادئ أجايل.', 'The correct answer here is “Simplicity – the art of maximising the amount of work not done – is essential” being an Agile clarifying principle.', 1),
  (0, 78, 'أنت تُجري الاجتماع الاستعادي (Retrospective) مع فريقك في نهاية السبرنت، حيث أثار الفريق مشكلة تُبطئ عملهم. ويوجّه سكرم ماستر (Scrum Master) الفريق لتنفيذ تمرين يُسمى الأسباب الخمسة (Five Whys). ما الغرض من ذلك؟', 'You are going through a retrospective with your team at the end of the sprint, where the team have raised an issue that is slowing down their work. The scrum master guides the team to go through an exercise called the Five Whys. What is the purpose of this?', 'الأسباب الخمسة (Five Whys) هي تقنية لحل المشكلات مستمدة من لين (Lean) أو نظام تويوتا للإنتاج، تطرح السؤال "لماذا" وقعت المشكلة. ومع كل إجابة، يسأل الفريق "لماذا" مرة أخرى، حتى يصلوا إلى السبب الحقيقي للمشكلة.', 'The Five Whys is a problem solving technique from Lean or the Toyota Production System that asks “why” a problem occurred. For each answer, the team asks “why” again, until they get to the real cause of the issue.', 1),
  (0, 79, 'طلب سكرم ماستر (Scrum Master) في فريق أجايل من الفريق إجراء تقييم ذاتي للفريق. ما محور تركيز هذا التقييم؟', 'The Scrum Master in the Agile team has asked the team to do a team self-assessment. What is the focus of this of this assessment?', 'يُستخدم التقييم الذاتي للفريق لقياس أداء أعضاء الفريق معاً، حيث تساعد النتائج في تحديد ما يعمل بشكل جيد وأين يمكن إجراء التحسينات. ثم يجتمع الفريق لحل المشكلات وإيجاد التحسينات والاحتفاء بما يعمل بشكل جيد.', 'The team self-assessment is used to gauge the team members performance together, with the results helping to identify what is working well and where improvements can be made. The team then meets to problem solve improvements and to celebrate what is working well.', 1),
  (0, 80, 'أنت تعمل في فريق أجايل، ويرغب ممثل جهة الأعمال في الحصول على فكرة عن المخاطر المرتبطة بميزة معينة. ماذا ستفعل بعد ذلك؟', 'You are working in an Agile team and the business representative would like to get an idea of the risk associated with a particular feature. What will you do next?', 'ينظر التشريح المسبق (Pre-mortem) في أسباب الفشل قبل وقوعها، وهو طريقة ممتازة للعصف الذهني حول المخاطر المتعلقة ببطاقة أو ميزة. وعادةً ما يكتب أعضاء الفريق أسبابهم ثم يناقشونها بأسلوب الأدوار المتعاقبة (Round-robin)، لأن بعض الأشخاص قد يتوصلون إلى الفكرة نفسها.', 'A pre-mortem looks at reasons for failure before they happen, and is a great way to brainstorm risks for a card or feature. Typically, team members write their reasons down then discuss in a round-robin style, as some people may come up with the same idea.', 1),
  (0, 81, 'أنت قائد فريق أجايل وتُجري اجتماعاً استعادياً (Retrospective) للفريق عندما تُثار مشكلة واجهها الفريق. ماذا ستفعل بعد ذلك؟', 'You are the Agile team leader and are working through a team retrospective when an issue experienced by the team is raised. What will you do next?', 'عندما تُثار مشكلة، فإن أفضل إجراء هو الوصول إلى السبب الجذري للمشكلة. ومن بين البنود المعروضة، يُعد تحليل عظم السمكة (Fishbone) أو تحليل إيشيكاوا (Ishikawa) أفضل أداة لتحليل السبب الجذري (Root Cause Analysis).', 'When an issue is raised the best course of action is to get to the root cause of the issue. Of the items presented, fishbone or Ishikawa analysis is the best tool for root cause analysis.', 1),
  (0, 82, 'أُضيف إلى بيان أجايل (Agile Manifesto) اثنا عشر مبدأً توضيحياً لمساعدة المشاريع والفرق على فهم قيم أجايل. وهي أيضاً أفضل ممارسة لتحسين الفريق بمرور الوقت. أيٌّ مما يلي يُعد مبدأً توضيحياً صحيحاً؟', 'The Agile manifesto has twelve clarifying principles added to it to help projects and teams understand the Agile values. They are also a best practice on improving the team over time. Which of the below is a correct clarifying principle?', 'المبدأ التوضيحي الصحيح من مبادئ أجايل هو: "على فترات منتظمة، يتأمل الفريق في كيفية أن يصبح أكثر فعالية، ثم يضبط سلوكه ويعدّله وفقاً لذلك"، وهو ما يتحول عملياً إلى الاجتماع الاستعادي (Retrospective) للفريق.', 'The correct Agile Clarifying Principle is: “At regular intervals, the team reflects on how to become more effective, then tunes and adjusts its behaviour accordingly,” which becomes the team Retrospective, in practice.', 1),
  (0, 83, 'أُضيف إلى بيان أجايل (Agile Manifesto) اثنا عشر مبدأً توضيحياً لمساعدة المشاريع والفرق على فهم قيم أجايل. أيٌّ مما يلي ليس مبدأً توضيحياً من مبادئ أجايل؟', 'The Agile manifesto has twelve clarifying principles added to it to help projects and teams understand the Agile values. Which of the below is NOT an Agile clarifying principle?', 'كل هذه مبادئ توضيحية صحيحة من مبادئ أجايل، باستثناء الإجابة B: "ضمان الالتزام بالأطر الزمنية للتسليم بأي ثمن".', 'Each of these are correct Agile clarifying principles, except answer B, “Ensure delivery timeframes are met at all costs.”', 1),
  (0, 84, 'أنت مالك المنتج (Product Owner) في فريق أجايل، وتعمل مع المطورين لإنشاء بطاقات القصص (Story Cards) لوضعها في قائمة أعمال المنتج المتراكمة. وفقاً للعناصر الثلاثة (3 C''s) لإنشاء قصة المستخدم، ماذا ستفعل أولاً؟', 'You are the product owner in an Agile team, working with the developers to create Story Cards to place in the product backlog. In the three C’s of user story creation, what will you do first?', 'تشمل العناصر الثلاثة (3 C''s) لإنشاء قصة المستخدم (User Story): إنشاء البطاقة (Card)، والمحادثة (Conversation) مع مالك المنتج والمطورين لشرح كيفية استخدام البرمجيات أو التصميم، والتأكيد (Confirmation) على معايير القبول وتعريف الإنجاز (DoD).', 'The three C’s of User Story Creation include: Creating the card, Conversation with the Product owner and developers to explain how the software or design will be used, and Confirming the acceptance criteria and the definition of done.', 1),
  (0, 85, 'أنت تعمل على قائمة أعمال المنتج المتراكمة (Product Backlog) مع فريق مشروع أجايل الخاص بك، وتنشئ قصص المستخدم (User Stories) لترتيب أولوياتها. أيٌّ مما يلي هو أفضل إجابة عمّا ينبغي أن تتضمنه بطاقة قصة المستخدم؟', 'You are working on the product backlog with your Agile project team, and creating user stories to be prioritised. Which of the below is the best answer for what should go into a user story card?', 'ينبغي أن تتضمن بطاقات القصص في أجايل المتطلب، ودرجة أهميته الحرجة، وتفاصيل الاختبار، ومعايير قبول (Acceptance Criteria) واضحة.', 'Agile story cards should have the requirement, its criticality, test details and clear acceptance criteria.', 1),
  (0, 86, 'أنت مدير مشروع أجايل وقد بدأت في إنشاء قصص المستخدم (User Stories) مع فريق مشروع أجايل الخاص بك لإدراجها في قائمة أعمال المنتج المتراكمة. وقد أنشأت البطاقة، وأضفت المتطلبات ودرجة الأهمية الحرجة ومعايير القبول. ماذا ستفعل بعد ذلك؟', 'You are an Agile project manager and have begun creating user stories with your Agile project team to go into the product backlog. You have created the card, added requirements, criticality and acceptance criteria. What will you do next?', 'العناصر الثلاثة (3 C''s) لإنشاء قصة المستخدم هي: البطاقة (Card)، والمحادثة (Conversation)، والتأكيد (Confirmation). فبمجرد إنشاء بطاقة قصة المستخدم، أجرِ محادثة مع المطورين والمختبرين لضمان الفهم، والتحقق من وجود أي ثغرات، وتقدير الجهد المطلوب. وأخيراً، أكّد معايير القبول (Acceptance Criteria). ويمكنك بعد ذلك وضعها في قائمة الأعمال المتراكمة (Backlog) لترتيب أولويتها في سبرنت قادم.', 'The three C’s on user story creation are: Card, Conversation and Confirmation. Once the user story card is created, have a conversation with developers and testers to ensure understanding, check for any gaps, and estimate the effort required. Finally, confirm the acceptance criteria. You can then place it in the backlog for prioritisation in an upcoming sprint.', 1),
  (0, 87, 'أنت تعمل في مشروع بصفتك مدير مشروع أجايل. ويرغب المدير التنفيذي الذي سيمتلك المنتج الذي تسلّمه في التركيز بشكل أساسي على عمليات وأدوات محددة لإدارة المشروع. ماذا ستوصيه به بدلاً من ذلك؟', 'You are working on a project as an Agile Project Manager. The executive manager who will own the product you are delivering would like to focus primarily on set processes and tools to manage the project. What will you recommend to them instead?', 'يوصي بيان أجايل (Agile Manifesto) بالتركيز على الأفراد والتفاعلات أكثر من العمليات والأدوات. فالمشاريع يديرها أشخاص، والمنتجات يطوّرها أشخاص ليستخدمها أشخاص، وتفاعلاتنا هي التي تصنع نجاح المشروع أو فشله.', 'The Agile manifesto recommends focusing on Individuals and Interactions over processes and tools. Projects are run by people, products are developed by people for people to use, and our interactions either make or break a project.', 1),
  (0, 88, 'شكّلت الإدارة التنفيذية في منظمتك فريقاً جديداً، وفرضت عليه استخدام أجايل في تطوير منتجه. ومع تقدم المشروع، يسود ارتباك بشأن نطاق المنتج وكيف يبدو تعريف الإنجاز (Definition of Done). بصفتك مدير مشروع أجايل، ماذا ستوصي به الفريق التنفيذي؟', 'The executive management in your organisation has assembled a new team, and dictated that they will use Agile for their product development. As the project progresses, there is confusion about the product scope and what the definition of done looks like. As an Agile Project Manager, what will you recommend to the executive team?', 'يشجع أجايل الفرق ذاتية التنظيم (Self-organizing Teams)، التي يشكّلها الأشخاص الذين وضعوا المتطلبات وكانت لديهم النتيجة المرجوة في المقام الأول. وهذا يمنح مستوى أعلى من الملكية والخبرة بالمنتج، وهو ما لا يمكن شراؤه في كثير من الأحيان.', 'Agile encourages self-organizing teams, formed by the people who created the requirements and had the desired outcome in the first place. This gives a higher level of ownership and product expertise, that often cannot be bought.', 1),
  (0, 89, 'أنت تدير مشروع أجايل وتجتمع مع الفريق لعقد اجتماع تخطيط السبرنت (Sprint Planning) القادم. ماذا ستفعل بعد ذلك؟', 'You are running an Agile project and meet with the team for the next sprint planning meeting. What will you do next?', 'ينبغي لمالك المنتج (Product Owner) أن يشارك البنود المحدّثة في قائمة أعمال المنتج المتراكمة (Product Backlog) مع الفريق وأن يضمن فهماً مشتركاً قبل المضي قدماً.', 'The product owner should share the updated items in the product backlog with the team and ensure a shared understanding before moving forward.', 1),
  (0, 90, 'أنت مدير مشروع تعمل في مشروع أجايل، وتريد من فريقك تعظيم القيمة التي يقدمونها للعميل. ما الذي يمكنك التخلص منه من أجل تعظيم قيمة المشروع؟', 'You are a project manager working on an Agile project, and want your team to maximise the value they bring to the customer. What can you eliminate in order to maximise project value?', 'هناك طرق عديدة لتقليل الخطوات "المهدرة" في عملية عمل فريق أجايل. فيمكننا إيقاف إدخال الميزات غير الضرورية، وتقليل العمل قيد التنفيذ (WIP)، وتقليل التأخيرات وعمليات التسليم بين الأطراف، والعمليات الزائدة، والتبديل بين المهام، والانتظار، والعيوب، وغير ذلك.', 'There are many ways to reduce "wasteful" steps in the process of an agile team. We can stop the introduction of unnecessary features, reduce work in progress, reduce delays and hand-offs, extra processes, task switching, waiting, defects and more.', 1),
  (0, 91, 'أنت تعمل في مشروع وقد انتقل الفريق مؤخراً إلى طريقة عمل أجايل. وأحد أعضاء الفريق مرتبك بشأن سكرم (Scrum) وما يحدث بعد مراجعة السبرنت (Sprint Review). ماذا ستخبره بما يحدث بعد ذلك؟', 'You are working on a project and the team have recently moved to an Agile way of work. One of the team members is confused about Scrum and what happens after the sprint review. What will you tell them happens next?', 'يُعقد الاجتماع الاستعادي للسبرنت (Sprint Retrospective) مع الفريق الكامل، بعد مراجعة السبرنت ولكن قبل اجتماع تخطيط السبرنت. ونستخدمه لجمع الدروس المستفادة والبحث عن فرص التحسين، ويكون لكل فرد صوت لتقديم التغذية الراجعة وتنفيذ التحسينات قبل السبرنت التالي.', 'A sprint retrospective is held with the Whole Team, after a sprint review but before the sprint planning meeting. We use it to gather lessons learned and look for opportunities for improvement, and everyone has a voice for feedback and to implement improvements before the next sprint.', 1),
  (0, 92, 'أنت تعمل في فريق أجايل وتُعدّ ميثاق فريق أجايل (Team Charter). وتعمل مع فريق أجايل لضمان أن يجيب ميثاق الفريق عن هذه الأسئلة الأربعة: لماذا ننفذ هذا المشروع؟ مَن المستفيد وكيف؟', 'You are working in an Agile team and preparing the Agile team charter. You work with the Agile team to ensure the team charter answers these four questions: Why are we doing this project? Who benefits and how?', 'يغطي ميثاق فريق أجايل (Team Charter) عادةً: لماذا ننفذ المشروع، ومَن المستفيد وكيف، وكيف يبدو الإنجاز، وكيف سنعمل معاً. دليل ممارسة أجايل (Agile Practice Guide) (2017)، الفصل الخامس، ص 49', 'An Agile team charter typically covers Why we are doing the project, who benefits and how, what does done look like, and how are we going to work together. The Agile Practice Guide (2017), Chapter Five, p49', 1),
  (0, 93, 'أنت تعمل مع مدير مشروع أجايل جديد، وتوضح له أن أجايل (Agile) يفضّل القياسات القائمة على القيمة بدلاً من القياسات التنبؤية في المشروع. ما هو مثال على القياسات القائمة على القيمة؟', 'You are working with a new Agile project manager and explain that Agile favours value-based measurements instead of predictive measurements on a project. What is an example of value based measurements?', 'يعمل أجايل بالقيمة المسلَّمة بوصفها قياسه الأساسي. أما جميع الخيارات الأخرى فهي قياسات تنبؤية مستمدة من منهجية إدارة المشاريع التقليدية.', 'Agile works with value delivered as its primary measurement. All the other options are predictive measurements from a traditional project management methodology.', 1),
  (0, 94, 'أنت تقود جلسة توجيه (Coaching) مع فريق مشروعك حول أطر عمل أجايل (Agile) ولين (Lean) الإضافية التي أسهمت في أسلوب العمل بأجايل. ما أطر العمل التي ستشاركها مع الفريق؟', 'You are a leading a coaching session with your project team on the additional Agile and Lean frameworks that have contributed to the Agile way of work. What frameworks will you share with the team?', 'تشمل أطر عمل أجايل ولين: إطار أجايل الموسّع (Scaled Agile Framework - SAFe)، وسكرم واسع النطاق (Large Scale Scrum - LeSS)، وسكرم السكرمات (Scrum of Scrums)، وطريقة تطوير الأنظمة الديناميكية (DSDM)، إلى جانب الأطر الأكثر شيوعاً مثل كانبان والبرمجة القصوى (XP) وسكرم. دليل ممارسة أجايل (2017)، ص110', 'Agile and lean frameworks include Scaled Agile Framework (SAFe), Large Scale Scrum (LeSS), Scrum of Scrums, Dynamic Systems Development Method, along with the more common Kanban, eXtreme programming and Scrum. The Agile Practice Guide (2017), p110', 1),
  (0, 95, 'أنت تعمل في مشروع بدور سكرم ماستر (Scrum Master)، وقد حددت اجتماعاً مع الفريق ومالك المنتج (Product Owner) لتنقيح قائمة أعمال المنتج المتراكمة (Product Backlog). ماذا ينبغي على الفريق أن يفعل في هذا الاجتماع؟', 'You are working on a project in the role of Scrum Master, and have set a meeting with the team and the product owner to refine the product backlog. What should the team do in this meeting?', 'يقوم مالك المنتج بتعديل أولوية بنود قائمة أعمال المنتج المتراكمة. أما الفريق فهو المسؤول عن تفصيل بنود العمل الخاصة به ثم تقدير الجهد اللازم لها. وفي كل مرة يقوم الفريق بتنقيح تقديراته بمستوى أعلى من التفصيل.', 'The Product Owner adjusts the priority of product backlog items. The team is responsible for elaborating on and then estimating the effort for their work items. Each time the team refines their estimates with a higher level of detail.', 1),
  (0, 96, 'أنت تعمل مع فريق يرغب في التحول إلى أجايل (Agile). يسألك المدير الوظيفي عن الفرق بين كانبان (Kanban) وسكرم (Scrum). بماذا ستجيبه؟', 'You are working with a team who would like to become Agile. The functional manager asks you what the difference between Kanban and Scrum is. What will you tell them?', 'الفرق الرئيسي بين سكرم وكانبان هو أن فرق كانبان تستخدم نظام السحب (Pull System). وهذا يعني أنه عند اكتمال بند من بنود العمل، يُحفَّز أحد أعضاء الفريق على “سحب” البند التالي في قائمة الانتظار إلى اللوحة للعمل عليه. وتعمل فرق كانبان انطلاقاً من لوحة كانبان التي تعرض كل مهمة، ولديها حد لمقدار العمل قيد التنفيذ (WIP) المسموح به.', 'The main difference between Scrum and Kanban is that Kanban teams employ a pull system. This means when an item of work is completed, it triggers someone to “pull” the next item in the queue onto the board to work on. Kanban teams work off a Kanban board that displays each task, and have a limit to how much work in progress (WIP) can be in place.', 1),
  (0, 97, 'أنت تعمل في مشروع جديد مع فريق تطوير منتج يعمل بأجايل (Agile)، وقد شكّل الفريق نفسه ذاتياً واختار سكرم ماستر (Scrum Master) يُدعى جيريمي. يحدد جيريمي على الفور اجتماعاً مع الفريق لشرح ميثاق الفريق (Team Charter) وبلورته. ما الذي جعل جيريمي خياراً جيداً لدور سكرم ماستر؟', 'You are working on a new project with an Agile product development team, who have self-formed and chosen a Scrum Master called Jeremy. Jeremy immediately sets a meeting with the team to explain and flesh out their Team Charter. What has made Jeremy a good choice for Scrum Master?', 'يُظهر جيريمي سمات القيادة الخادمة (Servant Leadership) من خلال إشراك الفريق في قرارات الفريق، بدءاً بميثاق الفريق والقواعد الأساسية حتى يعرف الجميع موقفهم. ومن خلال توضيح أسباب قراراته، فهو سكرم ماستر مناسب وسيكون أقل تركيزاً على القيادة والسيطرة.', 'Jeremy shows the traits of servant leadership by engaging the team in team decisions, starting with the Team Charter and ground rules so everyone knows where they stand. By communicating the reasons for his decisions, he is a suitable Scrum Master and will be less focused on command and control.', 1),
  (0, 98, 'أنت تدير مشروعاً بصفتك مدير مشروع أجايل (Agile)، ويسألك ممثل الأعمال عن المنتج الذي تقوم بتسليمه عن عدد العيوب التي تم اكتشافها في أحدث جولة من الاختبارات. أنت لا تعرف الإجابة. ماذا ينبغي عليك أن تفعل؟', 'You are managing a project as an Agile project manager and a business representative for the product you are delivering asks you how many defects were found in the latest round of testing. You don’t know the answer. What should you do?', 'من المكونات الأساسية لأجايل الإدارة المرئية (Visual Management) والشفافية. ويشكّل جزءاً من ذلك مختلف عناصر لوحة عرض المعلومات (Information Radiator) الخاصة بالمشروع (وغالباً ما تكون مادية، لكنها قد تكون قائمة على التقنية). وتشمل أموراً مثل سرعة الفريق (Velocity)، ولوحة كانبان، وقائمة أعمال المنتج المتراكمة، ومخطط الإنجاز التنازلي (Burndown Chart)، وأحدث نتائج الاختبارات والمشكلات، ونتائج الاجتماعات الاستعادية (Retrospectives).', 'A core component of Agile is Visual Management and transparency. Part of this are the various parts of the project information radiator (often physical, but can be tech-driven). This includes things such as the team velocity, Kanban board, the product backlog, the burndown chart, the latest test results and issues, and results of retrospectives.', 1),
  (0, 99, 'أنت تعمل في شركة تنتقل من منهجية الشلال (Waterfall) إلى أجايل (Agile). تذكر لمدير وحدة الأعمال أن الفريق سيكون أفضل استعداداً للاستجابة للتغيير وتلبية احتياجات العميل. لماذا ذلك؟', 'You are working in a company that is moving from a Waterfall methodology to Agile. You mention to the business unit manager that the team will be better prepared to respond to change and meet the customer needs. Why is this?', 'يُعد العمل مع شركاء الأعمال أو مع شخص يمثل العميل بشكل شبه يومي جزءاً أساسياً من أجايل. يستمع الفريق إلى ما ترغب جهة الأعمال في أن تكون عليه النتائج، كما أن الاجتماع وجهاً لوجه يحقق إجابات أسرع من قراءة المستندات أو رسائل البريد الإلكتروني أو حتى عقد المكالمات الجماعية.', 'Working with business partners or someone who represents the customer almost daily is a key part of Agile. The team hears what the business would like the results to be, and meeting face to-face gets faster answers than reading documents, e-mails, or even having conference calls.', 1),
  (0, 100, 'في دورات حياة أجايل (Agile)، يحدث نوعان من التخطيط: تخطيط الإصدار (Release Planning) وتخطيط التكرار (Iteration Planning). في تخطيط الإصدار، يحدد ممثلو الأعمال قصص المستخدم (User Stories) الخاصة بالإصدار ويرتبون أولوياتها بالتعاون مع الفريق، مع تنقيح قصص المستخدم الأكبر إلى مجموعة من القصص الأصغر. ما الوصف غير الصحيح فيما يلي بشأن تخطيط التكرار وإعداد قائمة الأعمال المتراكمة (Backlog)؟', 'For Agile life-cycles, two kinds of planning occur, release planning and iteration planning. In release planning, business representatives establish and prioritize the user stories for the release, in collaboration with the team, refining larger user stories into a collection of smaller stories. What is the INCORRECT description below regarding iteration planning and backlog preparation?', 'الإجابات A وC وD صحيحة في وصف إعداد قائمة الأعمال المتراكمة لتخطيط التكرار. دليل ممارسة أجايل (2017)، ص53، 5.2.3', 'Answers A, C and D are correct in describing Backlog Preparation for Iteration Planning. The Agile Practice Guide (2017), p53, 5.2.3', 1),
  (0, 101, 'يتيح التطوير المعتمد على السلوك (Behaviour-Driven Development - BDD) للمطور التركيز على اختبار الشفرة البرمجية بناءً على السلوك المتوقع للبرمجية، وهو طريقة لكتابة قصص المستخدم (User Stories). ما الوصف الصحيح لمعايير القبول (Acceptance Criteria) في BDD؟', 'Behaviour-driven development (BDD) allows a developer to focus on testing the code based on the expected behaviour of the software and is a method of writing user stories. What is the correct description regarding BDD acceptance-based criteria?', '“بافتراض، عندما، عندئذٍ” (Given, When, Then) هي الطريقة التي يُستخدم بها BDD، لا سيما عند صياغة بطاقات قصص المستخدم للتكرار الخاص بك. فهي تبرز أنه “بافتراض” (Given) وجود حالة معينة، “عندما” (When) يحدث شيء ما، “عندئذٍ” (Then) نريد أن يحدث هذا الأمر.', 'Given, When, Then is the way BDD is used, particularly when outlining user Story Cards for your iteration. It highlights “Given” a certain situation, “When” something happens, “Then” we want this to happen.', 1),
  (0, 102, 'ميثاق الفريق (Team Charter) هو أيضاً “عقد اجتماعي”. أي مما يلي لا يُعد عادةً جزءاً من ميثاق فريق أجايل (Agile)؟', 'A Team Charter is also a “social contract”. Which of the below is NOT usually a part of an Agile Team Charter?', 'يركز ميثاق فريق أجايل على الرؤية (“لماذا”) وعلى أسلوب عمل الفريق. أما مؤشر أداء الجدول الزمني (SPI) ومؤشر أداء التكلفة (CPI) فهما من مقاييس إدارة القيمة المكتسبة (Earned Value Management) في منهجية المشاريع التنبؤية، وليسا جزءاً من ميثاق فريق أجايل.', 'The Agile Team Charter focuses on the vision (the “Why”) and the team way of work. SPI and CPI are earned value management metrics from a predictive project methodology, and not part of an Agile Team Charter.', 1),
  (0, 103, 'أنت تعمل مع فريق حديث العهد بأجايل (Agile) ويستخدم سكرم (Scrum) لإدارة المشروع. ممثل الأعمال في حيرة بشأن الفرق بين مراجعة السبرنت (Sprint Review) والاجتماع الاستعادي للسبرنت (Sprint Retrospective). بماذا ستجيبه؟', 'You are working with a team that is new to Agile and are using Scrum to manage the project. The business representative is confused about the difference between a sprint review and a sprint retrospective. What will you tell them?', 'مراجعات السبرنت مخصصة للعروض التوضيحية للمنتج. أما الاجتماعات الاستعادية للسبرنت فمخصصة للدروس المستفادة، حيث نسأل: “ما الذي سار بشكل جيد، وما الذي لم يسر بشكل جيد، وماذا تعلمت؟”', 'Sprint Reviews are for product demonstrations. Sprint Retrospectives are for lessons learned, where we ask “What went well, what didn’t go well, what did I learn?”', 1),
  (0, 104, 'أنت تعمل في مشروع أجايل (Agile) بصفتك عضواً في الفريق، وتبدأ في جمع متطلبات المنتج. ما السؤال الأول العام الذي ينبغي عليك طرحه واستخدامه دليلاً لعملك؟', 'You are working on an Agile project as a team member, and begin gathering the product requirements. What is the overall first question that you should ask and use as a guide for your work?', 'تتمحور مشاريع أجايل حول تسليم القيمة التجارية (Business Value)، والعمل عن كثب مع العملاء وممثلي الأعمال لضمان أن تكون القيمة صحيحة دائماً. كما يجب أيضاً مراعاة مخاطر الأعمال وأثر عدم تنفيذ المشروع.', 'Agile projects centre around delivering business value, and working closely with the customers and business representatives to ensure that the value is always correct. Business risk and the impact of not undertaking the project must also be considered.', 1),
  (0, 105, 'حدد فريق أجايل (Agile) الذي تعمل مديراً لمشروعه عدة ميزات رئيسية لتسليمها إلى العميل. كيف ينبغي على الفريق التعامل مع أفكار الميزات هذه؟', 'The Agile team for which you are the project manager has determined several key features to deliver to the customer. How should the team handle these feature ideas?', 'أجايل هو مزيج من التسليم التزايدي (Incremental Delivery) والتطوير التكراري (Iterative Development). وهذا يعني أن القيمة التجارية تُحسَّن وتُرتَّب أولوياتها بشكل مستمر وتكراري، مع تسليمها في الوقت نفسه على شكل زيادات (Increments) يمكن للعميل رؤيتها والإحساس بها ولمسها. وينبغي أن تكون الميزات مكتملة ومختبَرة، كما أن الجودة مسؤولية الجميع.', 'Agile is a combination of Incremental delivery and Iterative development. That means business value is continuously and iteratively improved and prioritised, while also being delivered in increments that the customer can see, feel and touch. The features should be complete, tested, and quality is everyone’s responsibility.', 1),
  (0, 106, 'أنت تعمل في مشروع أجايل (Agile)، وقد أنهى فريق المشروع للتو تكراراً (Iteration). اكتملت جميع مهام التكرار، وأنت مستعد للانتقال إلى التكرار التالي، لكنك غير متأكد مما ينبغي على الفريق العمل عليه. ماذا ستفعل بعد ذلك؟', 'You are working on an Agile project and the project team have just finished an iteration. All tasks for the iteration have been completed, and you are ready to move to the next iteration, but are not sure what the team should work on. What will you do next?', 'يمثل مالك المنتج (Product Owner) العميل الذي تقوم بتسليم القيمة التجارية إليه. ويعمل الفريق على قائمة البنود ذات القيمة القابلة للتحديد والتي رتّب العميل أولوياتها.', 'The product owner represents the customer, who you are delivering business value to. The team works through the list of items that have identifiable value and have been prioritized by the customer.', 1),
  (0, 107, 'أثناء الاجتماع مع العملاء أو مالكي الأعمال، أدخلوا عدة وظائف جديدة إلى قائمة أعمال المنتج المتراكمة (Product Backlog). لا يمكن تغيير الموعد النهائي للمنتج. ماذا ستفعل بعد ذلك؟', 'While meeting with the customers or business owners, they introduce several pieces of new functionality into the product backlog list. The deadline for the product cannot be changed. What will you do next?', 'يمكن لمشروع أجايل قبول التغييرات حتى في مرحلة متأخرة من التطوير. ولكن بينما غالباً ما تكون القيود المتنافسة المتمثلة في التكلفة والجودة والجدول الزمني ثابتة، فإن النطاق في أجايل يمكن أن يتغير. وهذا يعني أن بعض الميزات قد تحتاج إلى الاستبعاد، مع إعطاء الأولوية لميزات أخرى. كما أن وتيرة العمل المستدامة مطلوبة أيضاً - فيجب على مديري المشاريع ألا يُرهقوا فريق المشروع بالعمل الزائد لزيادة وتيرة عمل المشروع.', 'An Agile project can accept changes even late in development. But while the competing constraints of cost, quality and schedule are often fixed, in Agile the scope can vary. This means some features may need to drop off, as others become prioritised. A maintainable pace of work is required too - project managers must not overwork the project team to increase the pace of the project work.', 1),
  (0, 108, 'هناك ممارسات أساسية معينة مشتركة بين جميع أطر عمل أجايل (Agile) المختلفة، وتُستخدم داخل أي فريق يصف نفسه بأنه فريق أجايل. أي مما يلي ليس ممارسة أساسية من ممارسات أجايل؟', 'There are certain core practices that are common amongst all the various Agile frameworks, and used within any team that calls themselves Agile. Which of the below is NOT a core Agile practice?', 'أسلوب القيادة المفضل في فريق أجايل هو القيادة الخادمة (Servant Leadership). فالقيادة الاستبدادية (Autocratic Leadership) عادةً ما تكون شأناً يخص شخصاً واحداً، في حين تبني القيادة الخادمة الأمان النفسي للفريق بأكمله للمشاركة والإسهام. أما جميع البنود الأخرى المذكورة فهي ممارسات أساسية في أجايل.', 'The preferred style of leadership in an Agile team is Servant Leadership. Autocratic leadership typically is a one person affair, while servant leadership builds psychological safety for the whole team to engage and contribute. All other items listed are Agile core practices.', 1),
  (0, 109, 'غالباً ما تكون المواصفات الضعيفة سبباً رئيسياً لفشل المشروع. في تطوير أجايل (Agile)، تُكتب قصص المستخدم (User Stories) بالاشتراك مع المطورين والمختبِرين وممثلي الأعمال، مع مراجعات متكررة لضمان صحتها. أي مما يلي غير صحيح بشأن الإنشاء التعاوني لقصص المستخدم؟', 'Poor specifications are often a major reason for project failure. In Agile development, user stories are written with the developers, testers, and business representatives, with frequent reviews to ensure they are right. Which of the following is NOT correct regarding Collaborative User Story Creation?', 'في حين أنه من الشائع أن يتفق المطورون والمختبِرون وممثل الأعمال على معايير بطاقة القصة، فإنها لا تُعتمد من قِبل راعي المشروع (Project Sponsor) مباشرة. فمالك المنتج (Product Owner)، الذي يمثل جهة الأعمال و/أو العميل، يقوم بتنقيح قائمة أعمال الميزات المتراكمة حتى يكونوا على علم دائم بأن القيمة التجارية يتم تسليمها.', 'While it is common for the developers, testers and business representative to agree on the story card criteria, it is not signed off by the project sponsor directly. The product owner, representing the business and/or the customer, refines the feature backlog of work so they always know that business value is being delivered.', 1),
  (0, 110, 'في التكامل المستمر (Continuous Integration): تُجمع إدارة التهيئة، والترجمة البرمجية، وبناء البرمجيات، والنشر، والاختبار في عملية واحدة مؤتمتة وقابلة للتكرار. العيوب في الشفرة البرمجية:', 'In Continuous Integration: configuration management, compilation, software build, deployment, and testing are wrapped into a single, automated, repeatable process. Defects in code are:', 'يدمج التكامل المستمر الشفرة البرمجية في بيئة اختبار باستخدام عملية مؤتمتة، تشمل اختبارات انحدار مؤتمتة لضمان عدم تعطل أي شيء. ويتيح ذلك للفريق اكتشاف العيوب في الشفرة البرمجية وإصلاحها بسرعة أكبر. أما التطوير المعتمد على الاختبار (TDD) فيكتب الاختبار أولاً (والذي يفشل في البداية)، ثم الشفرة البرمجية لضمان نجاح الاختبار.', 'Continuous Integration merges code to a test environment using an automated process, including automated regression tests to ensure nothing is broken. This allows the team to find and fix defects in the code more quickly. Test Driven Development writes a test first (which fails at first), then the code to ensure the test passes.', 1),
  (0, 111, 'لأجايل (Agile) ممارسات أساسية معينة تُستخدم داخل أي فريق يعمل بأسلوب أجايل. أي مما يلي ليس ممارسة أساسية من ممارسات أجايل؟', 'Agile has certain core practices that are used within any team working in an Agile way. Which of the following is NOT a core practice of Agile?', 'في حين أن رفع التقارير إلى المديرين التنفيذيين له مكانه عند إدارة المشروع، فإنه في أجايل يُفضَّل أن يتم ذلك من خلال إشراكهم في ممارسات أجايل الأساسية الأخرى، مثل العروض التوضيحية أو مراجعات المنتج، وعرض مخطط الإنجاز التنازلي (Burndown Chart) للمنتج في منطقة الفريق، وقائمة الأعمال المتراكمة (Backlog). أما جميع البنود الأخرى فهي ممارسات أساسية في أجايل.', 'While reporting to executives has its place when running a project, in Agile it would rather be done by including them in other Agile core practices, such as demonstrations or reviews of the product, showing the product burndown chart in the team area, and the backlog of work. All other items are Agile core practices.', 1),
  (0, 112, 'أنت تعمل في مشروع بصفتك مدير مشروع أجايل (Agile). تنظر في قائمة أعمال المنتج المتراكمة (Product Backlog) وتتأكد من إمكانية جدولة عدة ميزات، أو منتجات تمثل الحد الأدنى من المنتج القابل للتطبيق (MVPs)، للتسليم على مدار مدة المشروع. لماذا تُعد هذه فكرة جيدة؟', 'You are working on a project as an Agile project manager. You look at the product backlog and ensure several features, or minimum viable products (MVPs) can be scheduled for delivery throughout the duration of the project. Why is this a good idea?', 'منتجات الحد الأدنى من المنتج القابل للتطبيق (MVPs) هي ميزات قابلة للاستخدام بحد ذاتها تُسلَّم بشكل تزايدي. ويتيح ذلك الحصول على القيمة التجارية بسرعة أكبر، مع جمع التغذية الراجعة حول استخدام هذه الميزات.', 'Minimum Viable Products are usable features in their own right that are delivered incrementally. This allows for business value to be gained more quickly, while gathering feedback on the use of these features.', 1),
  (0, 113, 'أنت تعمل في مشروع برمجي معقد، لكنك تلاحظ أن الفريق يستخدم سبورة بيضاء ويكتب المهام على بطاقات أو ملاحظات لاصقة. يبدو ممثل الأعمال منزعجاً من استخدام هذه الأدوات منخفضة التقنية في مشروع تقني رفيع المستوى كهذا. بماذا ستجيبه؟', 'You are working on a complex software project but see that the team uses a whiteboard, and writes tasks on cards or sticky notes. The business representative seems put off by the use of these low-tech tools on such a high profile technology project. What will you tell them?', 'الإدارة المرئية (Visual Management) هي مبدأ من مبادئ لين (Lean) تم استعارته في أجايل، حيث نجعل المعلومات الرئيسية متاحة قدر الإمكان. وغالباً ما توجد في منطقة الفريق وغالباً ما تكون مادية، وهذا يعني أن أي شخص يمكنه المرور عبر المنطقة ورؤية ما يحتاج إليه بنظرة سريعة. وكانبان مثال على أداة منخفضة التقنية / عالية التفاعل.', 'Visual Management is a Lean principle borrowed into Agile, where we make key pieces of information as accessible as possible. Often found in the team area and often physical, it means anyone can walk through the area and see what they need at a glance. Kanban is an example of a low-tech / high touch tool.', 1),
  (0, 114, 'تمارس فرق أجايل (Agile) التحقق والمصادقة بشكل متكرر أثناء كل تكرار وفي نهايته من خلال العروض التوضيحية والمراجعات (مثل مراجعة السبرنت). أي مما يلي ليس من فوائد مراجعات السبرنت (Sprint Reviews)؟', 'Agile teams practice frequent verification and validation during and at the end of each iteration through demonstrations and reviews (such as the Sprint Review). Which of the following is NOT a benefit of Sprint Reviews?', 'العمل من أجل الانشغال فقط لا يضيف قيمة إلى المشروع، وليس من فوائد أجايل.', 'Busy-work does not add value to the project, and is not a benefit of Agile.', 1),
  (0, 115, 'أنت مدير مشروع أجايل (Agile) في مشروع برمجي يحتاج إلى التسليم بسرعة. وترغب في تقصير الوقت اللازم لتحديد العيوب وحلّها فور ظهورها. فما الذي ستطبّقه مع الفريق؟', 'You are an Agile project manager on a software project that needs to be delivered quickly. You would like to shorten the time for identifying and resolving defects as they arise. What will you implement with the team?', 'يهدف التكامل المستمر (Continuous Integration) إلى دمج الشيفرة البرمجية والحصول على بناء عامل مرة واحدة يومياً، ثم تنفيذ الاختبارات الآلية بسرعة لمعرفة ما إذا كان هناك أي شيء قد تعطّل. ويضمن هذا الفحص المتكرر مرور وقت أقل قبل تحديد المشكلة.', 'Continuous integration aims to merge code and have a working build once a day, then executes automated tests quickly to see if anything is broken. This frequent checking ensures less time passes before a problem is identified.', 1),
  (0, 116, 'أنت تعمل مع فريق أجايل (Agile) الخاص بك، وهم في حيرة بشأن الوقت الأنسب لتحديد معايير اختبار القبول (Acceptance Test Criteria) للميزة أو بطاقة القصة. فما الوقت الذي ستخبرهم به؟', 'You are working with your agile team, and they are confused about when the best time is to determine the acceptance test criteria for the feature or story card. What time will you tell them?', 'تُصمَّم اختبارات القبول ومعاييرها قبل تطوير التسليم وأثناء مرحلة التفصيل، وغالباً ما يكون ذلك في صيغة سيناريو "بافتراض أن، عندما، عندئذٍ" (Given, When, Then) أو سيناريو "بصفتي"، "أريد"، "حتى أتمكن من" (As a, I want, So I can).', 'Acceptance tests and criteria are designed before the development of a deliverable, and during elaboration, often in a “Given, When, then” scenario or an “As a,” “I want,” “So I can,” scenario.', 1),
  (0, 117, 'يجمع التكامل المستمر (Continuous Integration) بين بناء البرمجيات ونشرها واختبارها في عملية واحدة آلية وقابلة للتكرار. وهذا يدمج جميع التغييرات التي أُجريت على البرمجيات و:', 'Continuous Integration wraps software build, deployment, and testing into a single, automated, repeatable process. This merges all changes made to the software and:', 'صُمّم التكامل المستمر (Continuous Integration) لدمج جميع التغييرات التي أُجريت على البرمجيات واختبارها آلياً، واكتشاف أي عيوب أو مشكلات بشكل يومي.', 'Continuous integration is designed to merge all changes made to the software and test them automatically, discovering any defects or issues on a daily basis.', 1),
  (0, 118, 'كريستال (Crystal) هو أحد أُطر العمل الأصلية التي أسهمت في أجايل (Agile). وقد صُمّم ليكون قابلاً للتوسّع، ويدرك أن كل مشروع قد يتطلب مجموعة من الممارسات المخصّصة قليلاً بناءً على الحجم والتعقيد. وتشمل قيمه الأساسية:', 'Crystal is one of the original frameworks that contributed to Agile. It is designed to scale and realises that each project may require a slightly tailored set of practices based on size and complexity. Its core values include:', 'تشمل القيم الأساسية لكريستال (Crystal) الأشخاص والتفاعل والمجتمع - بالطريقة نفسها التي يقوم بها أجايل (Agile) على تقديم الأفراد والتفاعلات على العمليات والأدوات - وفهم تأثير الأمور على طريقة العمل وإنجاز المهام.', 'Crystal’s core values include People, Interaction and Community - in the same way as Agile is based around iterations over processes and tools - and understanding the impact things have on way of work and getting things done.', 1),
  (0, 119, 'صُمّم كريستال (Crystal) ليكون قابلاً للتوسّع، ويدرك أن كل مشروع قد يتطلب مجموعة من الممارسات المخصّصة قليلاً بناءً على الحجم والتعقيد. فما بعض الطرق التي يتوسّع بها كريستال؟', 'Crystal is designed to scale and realises that each project may require a slightly tailored set of practices based on size and complexity. What are some of the ways that Crystal scales?', 'تستند تصنيفات كريستال الشفاف (Crystal Clear) والأصفر والبرتقالي والأحمر إلى عوامل مثل عدد الأشخاص المشاركين (من 0 إلى 8، وصولاً إلى 100 أو أكثر)، والأموال المعنية، ومستوى الارتياح العام في المشروع.', 'Crystal Clear, Yellow, Orange and Red are based on factors such as people involved (0 to 8, all the way up to 100 or more), money involved and the general comfort level of the project.', 1),
  (0, 120, 'أنت تعمل في مشروع أجايل (Agile) مع فريقك، وتجتمعون يومياً في اجتماع الوقوف اليومي (Daily Stand-up). ما الذي لا يُعدّ من أسباب استخدام فرق أجايل لاجتماعات الوقوف اليومية؟', 'You are working through an Agile project with your team, meeting daily in a daily stand-up. What is NOT one of the reasons Agile teams use daily stand-ups?', 'تُستخدم اجتماعات الوقوف اليومي للالتزام المصغّر تجاه بعضكم البعض، وكشف العوائق، وضمان تدفق العمل بحرية عبر الفريق. ومع أن الجميع (بمن فيهم أي مسؤول تنفيذي) مرحّب بهم للانضمام إلى اجتماعات الوقوف، فإنها ليست مخصصة لرفع التقارير إلى الفريق التنفيذي.', 'Stand-ups are used to micro-commit to each other, uncover blockers, and ensure work flows freely through the team. While everyone (including an executive) is welcome to join the stand-ups, they are not specifically for reporting to an executive team.', 1),
  (0, 121, 'أنت مدير مشروع في مشروع أجايل (Agile) قطع نصف الطريق. وقد بدأ راعي المشروع (Project Sponsor) يُثير مخاوف من أن المشروع لن يُنجز في الوقت المخصص له. فما الذي ستفعله لجمع المعلومات اللازمة للرد على راعي المشروع؟', 'You are the project manager on an Agile project that is half way through. The project sponsor is starting to raise concerns that the project will not be completed in the allotted time. What will you do to gather the information necessary to answer the project sponsor?', 'تشمل مؤشرات الأداء الرئيسية في أجايل سرعة الفريق (Velocity) (معدل التقدم) والعمل المتبقي. ويمكن عرض هذه المؤشرات بصرياً أيضاً، كما في مخطط الإنجاز التنازلي (Burndown Chart). وستمنحك مراجعة مؤشرات الأداء الرئيسية هذه الإجابة الأكثر موثوقية.', 'Agile Key Performance Indicators include team velocity (rate of progress) and remaining work. These can be shown visually as well, such as on a burndown chart. Reviewing these KPIs will give you the most reliable answer.', 1),
  (0, 122, 'أنت تحضر اجتماع انطلاق المشروع (Kick-off Meeting) مع فريق أجايل (Agile) ومالكي الأعمال. ويوصي سكرم ماستر (Scrum Master) باستخدام أسلوب MoSCoW للمساعدة في تحديد أولويات العمل مع مالكي المنتج / الأعمال. فكيف يحدد أسلوب MoSCoW أولويات قائمة أعمال المنتج المتراكمة؟', 'You are attending the kick-off meeting with the Agile team and the business owners. The Scrum Master recommends using MoSCoW to help prioritise the work with the product / business owners. How does MoSCoW prioritise the product backlog?', 'يصنّف أسلوب MoSCoW لتحديد الأولويات المهام إلى: يجب أن يتوفر (Must have)، وينبغي أن يتوفر (Should have)، ويمكن أن يتوفر (Could have)، ولن يتوفر (Will not have) (أو يُستحسن أن يتوفر). ومن تقنيات تحديد الأولويات الأخرى: التصويت المتعدد بالنقاط، ونقود المونوبولي، وتحليل كانو (Kano)، وقبضة الخمسة (Fist of Five).', 'The MoSCoW method of prioritization labels tasks as must have, should have, could have, and will not have (or would like to have). Other prioritisation techniques are multi-voting with dots, monopoly money, Kano analysis, and fist of five.', 1),
  (0, 123, 'تستخدم فرق أجايل (Agile) أساليب مختلفة لإدارة العمل قيد التنفيذ (WIP). ويعتقد راعي الأعمال أن إزالة حدود العمل قيد التنفيذ ستساعد الفريق على تولّي مزيد من العمل وتسليم منتجه بشكل أسرع. فما الذي ستخبره به؟', 'Agile teams use different methods to manage work in progress (WIP). The business sponsor believes that removing the limits to work in progress will help the team take on more work and get their product delivered faster. What will you tell them?', 'في أجايل (Agile)، يُتولّى العمل بناءً على سرعة الفريق (Velocity) أو معدل العمل. وتُظهر لوحة كانبان (Kanban Board) العمل قيد التنفيذ ومن يعمل على ماذا. وتتيح لك معرفة السرعة ضمان تولّي قدر كافٍ من العمل، دون إفراط. وقد أثبتت الأبحاث أن تعدد المهام أو التبديل بينها يقلل فعلياً من الفعالية ريثما يستعيد الفريق وتيرته من جديد.', 'In Agile, work is taken on based on the team velocity or rate of work. The Kanban board shows the WIP and who is working on what. Knowing the velocity allows you to ensure enough work is taken on, but not too much. Research has proven that multitasking or switching tasks actually reduces effectiveness as the team gets up to speed again.', 1),
  (0, 124, 'أنت تعمل مديراً لمشروع أجايل (Agile) ضمن فريق يضم العديد من أصحاب المصلحة (Stakeholders) الذين لم يسبق لهم العمل في مشروع أجايل. ويأتي إليك بعض أصحاب المصلحة هؤلاء بمخاوف مشروعة بشأن أساليب أجايل المستخدمة. وبصفتك قائداً خادماً (Servant Leader) أو مدرّباً للمشروع، ما الذي ستفعله لجعلهم أكثر ارتياحاً للعملية؟', 'You working as an Agile project manager in a team with many stakeholders who have not worked on an Agile project before. Some of these stakeholders come to you with valid concerns about the Agile methods being used. As a servant leader or project coach, what will you do to make them more comfortable with the process?', 'يُشرك القائد الخادم (Servant Leader) الفريق في القرارات، ويُنمّي الفريق من خلال التثقيف والتوجيه (Coaching).', 'A servant leader includes the team in decisions, and grows the team through education and coaching.', 1),
  (0, 125, 'أنت تعمل في مشروع أجايل (Agile) مع أصحاب مصلحة (Stakeholders) حريصين على معرفة: لماذا من المهم جداً دمج نقاط تواصل متعددة معهم قبل التكرارات (Iterations) وأثناءها وبعدها؟', 'You are working on an Agile project with stakeholders who are keen to know: Why is it so important to incorporate multiple touchpoints with them before, during, and after iterations?', 'تهدف نقاط التواصل المتكررة في أجايل (Agile) إلى ضمان مراجعة الميزات وتلبيتها لتوقعات أصحاب المصلحة، ومعالجة المخاطر. كما تتيح طرح التغييرات مبكراً. فالجودة مسؤولية الجميع في فريق أجايل.', 'Frequent touch points in Agile are there to ensure the features are reviewed and meet stakeholders’ expectations, and risks are addressed. It allows changes to be raised early. Quality is everyone’s responsibility on an Agile team.', 1),
  (0, 126, 'تستخدم الفرق اجتماعات الوقوف اليومي (Daily Stand-ups) للالتزام المصغّر تجاه بعضها البعض، وكشف العوائق وإزالتها، وضمان تدفق العمل بسلاسة عبر الفريق. ما العبارة غير الصحيحة بشأن اجتماعات الوقوف؟', 'Teams use daily stand-ups to micro-commit to each other, uncover and remove blockers, and ensure work flows smoothly through the team. What is NOT true about stand-ups?', 'من "الأنماط المضادة" (Anti-patterns) الشائعة استخدام اجتماعات الوقوف كاجتماع حالة، بدلاً من استخدامها لكشف العوائق ودفع العمل قُدماً. واجتماعات الوقوف محددة بإطار زمني مدته 15 دقيقة، ويستعرض الفريق خلالها لوحة كانبان (Kanban Board)، ويمكن لأي فرد في الفريق تيسيرها. دليل ممارسة أجايل (Agile Practice Guide) (2017)، ص 53، "اجتماعات الوقوف اليومية".', 'A common "anti-pattern" is when Standups are used as a status meeting, instead of being used to uncover blockers and progress work. Stand-ups are time-boxed to 15 minutes, the team walks through the Kanban board, and anyone in the team can facilitate. Agile Practice Guide (2017), p53, "Daily Standups".', 1),
  (0, 127, 'تُستكمل الميزات (Features) في مشروع أجايل (Agile) عادةً في شكل قصص مستخدم (User Stories) متعددة. وعند اكتمال ميزة ما، يعرض الفريق دورياً المنتج العامل على العميل و/أو ممثل الأعمال و/أو مالك المنتج. وهذه العروض التوضيحية أو المراجعات:', 'Features are completed in an Agile project, usually in the form of multiple user stories. When a feature is complete, the team periodically demonstrates the working product to the customer, business representative and/or the product owner. These demonstrations or reviews:', 'تحدث "مراجعات السبرنت" (Sprint Reviews) في أجايل، أو العروض التوضيحية للميزات، في نهاية التكرار (Iteration) أو عند اكتمال عدد كافٍ من البطاقات أو الميزات لتشكّل مجموعة يمكن استعراضها.', 'Agile “sprint reviews”, or feature demonstrations, occur at the end of an iteration or when enough cards or features have been completed into a set that can be showcased.', 1),
  (0, 128, 'أنت تعمل مع المطورين في فريق أجايل (Agile) يستخدمون نهج التطوير المعتمد على الاختبار (TDD). ويسألونك عمّا إذا كان ينبغي عليهم العمل وفق ما يُسمى "أحمر - أخضر - إعادة هيكلة" (Red-Green-Refactor). فإلى ماذا يشيرون؟', 'You are working with the developers in an Agile team, who are using the test-driven development approach. They ask you whether they should operate using something called Red-Green-refactor. What are they referring to?', 'تُعدّ عملية كتابة اختبار يفشل في البداية، ثم إضافة الشيفرة البرمجية حتى ينجح الاختبار، ثم إعادة هيكلة الشيفرة، جزءاً من التطوير المعتمد على الاختبار (TDD). وأسلوب أحمر - أخضر - إعادة هيكلة (Red-Green-Refactor) يعادل: الفشل، ثم النجاح، ثم تبسيط الشيفرة.', 'The process of writing a test that initially fails, adding code until the test passes, then refactoring the code is part of test Driven Development. (TDD). Red-Green-Refactor is the same as fail, pass, and streamline the code.', 1),
  (0, 129, 'أنت مدير مشروع أجايل (Agile) تعمل مع مالك المنتج (Product Owner) في فريق أجايل. وقد تم تحديد عدة تسليمات رئيسية وإدراجها في قائمة أعمال المنتج المتراكمة (Product Backlog). فما الذي سيفعله فريق أجايل بعد ذلك؟', 'You are an Agile project manager working with the Product Owner of the Agile team. There are several key deliverables that have been identified and listed in the product backlog. What will the Agile team do next?', 'يطوّر أجايل (Agile) ويسلّم على شكل ميزات أو زيادات (Increments). ويعني ذلك تحديد الأولويات لكل زيادة، والتطوير والاختبار لكل زيادة. وعلى الرغم من رغبتنا في التسليم بسرعة، يظل اختبار الجودة مهماً، فالجودة مسؤولية الجميع.', 'Agile develops and delivers in features or increments. This means prioritising for each increment, developing and testing for each increment. Even though we want to deliver quickly, quality testing is still important and quality is everyone’s responsibility.', 1),
  (0, 130, 'عمل فريق حديث العهد بأجايل (Agile) عن كثب مع مالك المنتج (Product Owner) وحدّد الميزات الأعلى قيمة في المشروع. ما أحد أسباب تجزئة تلك الميزات إلى زيادات (Increments) وتسليمها في أقرب وقت ممكن؟', 'A team new to Agile has worked closely with the product owner and has identified the highest value features of the project. What is one reason to break those features down into increments and deliver them as soon as possible?', 'كلما طال الوقت الذي يستغرقه تسليم ميزة ما، ازدادت مخاطر ألا تعود الميزة توفر القيمة التي كان يُقصد منها توفيرها. ويحدد التسليم المدفوع بالقيمة (Value-Driven Delivery) أولويات الميزات حسب القيمة الأعلى ويسلّمها بسرعة لتحقيق أقصى فائدة للعميل.', 'The longer a feature takes to deliver, the higher the risk is that the feature will no longer provide the value it was intended to provide. Value driven delivery prioritises features by highest value and delivers them quickly for maximum customer benefit.', 1),
  (0, 131, 'أنت مدير مشروع أجايل (Agile) تعمل عن كثب مع سكرم ماستر (Scrum Master) وفريق أجايل. ويذكر سكرم ماستر أن أجايل يتعامل مع المخاطر بشكل مختلف مقارنةً بالمشروع التقليدي. ويحدد اجتماعاً معك ومع الفريق لمناقشة مخاطر أجايل. فما الذي ستفعله بعد ذلك؟', 'You are an Agile project manager working closely with the Scrum Master and Agile team. The Scrum Master mentions that Agile works differently with risk compared to a traditional project. He sets a meeting with you and the team to talk through Agile risks. What will you do next?', 'يسلّم فريق أجايل (Agile) على شكل زيادات (Increments) ويكرّر نحو التحسين. ومن خلال إعطاء الأولوية للميزات عالية المخاطر أولاً، تقل المخاطر المستقبلية للمشروع.', 'An Agile team delivers in increments and iterates toward improvement. By prioritising high-risk features first, future risks for the project are reduced.', 1),
  (0, 132, 'أنت مدير مشروع في مشروع أجايل (Agile) يتطلب طرفاً ثالثاً خارجياً لتطوير برمجيات لإحدى ميزاتك. وقد عملت مع فريق المشروع لجمع المتطلبات وقائمة الأعمال المتراكمة (Backlog) لميزات المنتج. وتبدأ العمل مع قسم المشتريات لديك على عقد مع المورّد. فما الذي ستفعله بعد ذلك؟', 'You are a project manager on an Agile project that requires an external third party to develop software for one of your features. You have worked with the project team to gather the requirements and backlog of product features. You begin working with your procurement department on a contract for the vendor. What will you do next?', 'يتعامل أجايل (Agile) مع نطاق وتكلفة متغيرين نظراً لاكتمال المنتج بشكل تزايدي، لكن مع جدول زمني وجودة ثابتين في المقام الأول. وبما أنك تعمل مع قسم المشتريات، فستحتاج إلى ضمان عقد يستوعب المتطلبات والنطاق المتغيرين.', 'Agile works with changing scope and cost as the product is completed incrementally, but primarily a fixed schedule and quality. As you are working with the procurement department, you will need to ensure a contract that accommodates changing requirements and scope.', 1),
  (0, 133, 'تتسم مشاريع أجايل (Agile) بتكرارات (Iterations) قصيرة تمكّن فريق المشروع من تلقّي تغذية راجعة مبكرة ومستمرة بشأن جودة المنتج طوال دورة حياة التطوير. ومن خلال الحصول على تغذية راجعة متكررة من العميل مع تقدم المشروع، يمكن لفرق أجايل دمج معظم التغييرات الجديدة في المنتج وفي عملية التطوير. ما الذي لا يُعدّ من فوائد هذا النهج؟', 'Agile projects have short iterations enabling the project team to receive early and continuous feedback on product quality throughout the development lifecycle. By getting frequent customer feedback as the project progresses, Agile teams can incorporate most new changes into the product and the development process. What is NOT one of the benefits of this approach?', 'تعمل أساليب أجايل (Agile) مع ميزات متعددة، وتصدرها على شكل زيادات (Increments) حتى يتمكن العميل من استخدامها وتقديم تغذية راجعة. أما الاكتفاء بإصدار واحد فهو نهج الشلال (Waterfall).', 'Agile methods work with multiple features, releasing them in increments so the customer can use them and provide feedback. Having a single release is a waterfall approach.', 1),
  (0, 134, 'أنت مدير مشروع أجايل (Agile) مكلّف بتطوير الجزء الخاص بك من المنظمة ليتحول إلى أجايل. ما الذي لن تفعله عند إجراء هذا التغيير؟', 'You are an Agile project manager tasked with evolving your part of the organisation into Agile. What is NOT something you would do, when making this change?', 'أجايل (Agile) نهج تزايدي. فاستخدام قائمة أعمال متراكمة (Backlog) بأساليب أجايل التي ترغب الفرق في استخدامها، والتعامل معها كتجربة، واستخدام لوحة كانبان (Kanban Board) لتتبع التقدم، كلها أمور يمكنك القيام بها لاستخدام أجايل عند تطبيق أجايل.', 'Agile is an incremental approach. Using a backlog of Agile methods the teams would like to use, treating them as an experiment, and using a Kanban board to track progress are all things you can do to use Agile when implementing Agile.', 1),
  (0, 135, 'أنت مدير مشروع أجايل (Agile) تعمل مع راعي المشروع (Project Sponsor) في المراحل الأولى من مشروع أجايل. ويذكر راعي المشروع أنه يرغب في المساعدة في إعداد ميثاق المشروع (Project Charter). فتخبره بأنك ستُعدّ أيضاً ميثاق الفريق (Team Charter) لفريق أجايل الخاص بك، وسيشمل راعي المشروع. فماذا يعني ذلك؟', 'You are an Agile project manager working with the project sponsor in the beginning stages of an Agile project. The project sponsor mentions that they would like help creating the Project Charter. You tell them you will also do a Team Charter for your Agile team, that will include the project sponsor. What does this mean?', 'يُعدّ مدير مشروع أجايل ميثاقاً لكل من المشروع والفريق. فميثاق المشروع (Project Charter) يركّز على دراسة الجدوى (Business Case)، والغرض من المشروع، والمتطلبات عالية المستوى، وأصحاب المصلحة، والمخاطر. أما ميثاق الفريق (Team Charter) فيركّز على الاتفاقيات المتعلقة بكيفية عمل الفريق، ويُعدّ بصورة جماعية من قِبل الفريق.', 'An Agile project manager charters both the project and the team. A project charter focuses on the business case, project purpose, high level requirements, stakeholders and risks. A Team Charter focuses on the agreements in how the team will operate, and is created as a team.', 1),
  (0, 136, 'أنت تعمل مع الفريق على ميثاق الفريق (Team Charter)، وقد حددتم رؤية المشروع ورسالته وأوقات الاجتماعات المتفق عليها وسلوك الفريق المقبول. فما الذي ستفعله بعد ذلك؟', 'You are working with the team on the team charter and have outlined the project vision, mission, agreed meeting times and accepted team behaviour. What will you do next?', 'يُعدّ تعريف "الإنجاز" (Definition of Done) جزءاً مهماً من ميثاق الفريق (Team Charter)، لضمان أن يعرف الفريق متى تكتمل المهمة، ومتى يمكنهم سحب المهام التالية، وحتى يتفق الجميع على ما يبدو عليه النجاح. وقد يشمل ذلك تحديد البطاقة وتفصيلها وتطويرها واختبارها ومراجعتها ثم إصدارها. وقد يُشمل راعي المشروع في ميثاق الفريق، لكنه لا يحتاج إلى اعتماده، فهو اتفاق بين أعضاء الفريق.', 'The definition of “done” is an important part of the Team Charter, to ensure the team knows when a task is completed, when they can pull the next tasks, and so everyone agrees what success looks like. This could involve a card being defined, elaborated, developed, tested, reviewed and then released. The project sponsor may be included in the team charter, but does not need to sign off on it – it is an agreement amongst the team.', 1),
  (0, 137, 'أنت تعمل في مشروع أجايل (Agile)، وتجمع المتطلبات من أصحاب المصلحة (Stakeholders) في جهة الأعمال مع مالك المنتج (Product Owner). وأثناء النقاش، يبدو أن لدى الأشخاص المختلفين فهماً مختلفاً لما ستبدو عليه الميزة. فما الذي ستفعله بعد ذلك؟', 'You are working on an Agile project, gathering requirements from the business stakeholders with the Product Owner. During the discussion, different people seem to have different understandings of what the feature will look like. What will you do next?', 'إن الوصول إلى توافق الآراء (Consensus) بشأن محتوى وتدفق جزء من البرمجيات من خلال إعداد إطار شبكي (Wireframe) أو لوحة قصصية (Storyboard) سيؤكد أن الجميع لديهم فهم كامل لما سيكون عليه المخرج.', 'Gaining consensus regarding the content and flow of a piece of software by developing a wireframe or storyboard will confirm everyone has a complete understanding of what the output is.', 1),
  (0, 138, 'أنت تعمل مديراً للمشروع مع فريق مشروع أجايل (Agile). ويجلس أحد أصحاب المصلحة (Stakeholders) الرئيسيين المعنيين بمتطلبات مشروعك في طابق آخر، ويفضّل التواصل عبر البريد الإلكتروني فقط. فما الذي ستفعله بعد ذلك؟', 'You are working as a project manager with an Agile project team. A key stakeholder for the requirements of your project sits on another floor, and prefers to communicate by email only. What will you do next?', 'يهدف فريق مشروع أجايل (Agile) إلى العمل في مساحة يتواجد فيها أعضاؤه في مكان واحد (Co-located)، حيث يمكن للأفكار والمعلومات أن تتدفق بحرية. ويوفر التواصل وجهاً لوجه أفضل فرصة لطرح الأسئلة، والحصول على تغذية راجعة فورية، وفهم لغة الجسد من أجل تأكيد الاتفاق أو توضيح سوء الفهم. كما توجد لوحات كانبان (Kanban Boards) والأدوات المرئية الأخرى في منطقة عمل الفريق.', 'An Agile project team aims to work in a co-located space, where ideas and information can flow freely. Face-to-face communication provides the best opportunity to ask questions, get immediate feedback, and understand body language in order to acknowledge agreement or clarify misunderstandings. Kanban boards and other visual tools are also in the team area.', 1),
  (0, 139, 'بصفتك مدير مشروع أجايل (Agile)، فإنك تدرك الحاجة إلى العمل بانفتاح وشفافية مع فريقك وأصحاب المصلحة (Stakeholders). كيف ستشجع تبادل المعرفة طوال المشروع؟', 'As an Agile project manager, you understand the need to operate with openness and transparency with your team and stakeholders. How will you encourage knowledge sharing throughout the project?', 'يجعل فريق أجايل معلومات المشروع مرئية ومتاحة للجميع. وتوفر لوحة عرض المعلومات (Information Radiator) رؤية شفافة لمعلومات المشروع الرئيسية مثل قائمة أعمال المنتج المتراكمة (Product Backlog)، وقائمة أعمال السبرنت المتراكمة (Sprint Backlog)، ولوحة كانبان (Kanban Board)، وحتى ميثاق الفريق أو المخاطر الرئيسية. ويُشجَّع جميع أصحاب المصلحة على الاطلاع عليها في أي وقت. دليل ممارسة أجايل (2017)، ص 152، "لوحة عرض المعلومات (Information Radiator)".', 'An Agile team makes project information visible and accessible to all. An Information Radiator has a transparent view of key project information such as the Product Backlog, Sprint Backlog, Kanban Board, even the team charter or key risks. All stakeholders are encouraged to view it at any time. Agile Practice Guide (2017), p152, "Information Radiator."', 1),
  (0, 140, 'أنت تختبر المنتج الذي يسلّمه فريق أجايل على شكل زيادات (Increments). وتلاحظ أنه لم تُمرَّر أي عيوب إلى المستخدم النهائي. كما تلاحظ أن الفريق يعمل وفق منهجية البرمجة القصوى (XP). ما ممارسات XP التي أدت إلى هذه النتيجة؟', 'You are testing the product being delivered by an Agile team in increments. You notice that there have been no defects passed on to the end user. You also notice they are working with an eXtreme Programming (or XP) methodology for the team. What are the XP practices that led to this result?', 'تعمل البرمجة القصوى (XP) بالتكامل المستمر (Continuous Integration) – أي نشر قاعدة شفرة برمجية واحدة يومياً وتشغيل اختبارات الانحدار الآلية للتحقق مما إذا كان هناك شيء معطّل. وبهذه الطريقة يتم اكتشاف العيوب بسرعة. كما أن إعادة الهيكلة (Refactoring) المنتظمة، أو تبسيط الشفرة البرمجية وتنظيفها، تضمن أيضاً سهولة العمل بها وسهولة اكتشاف العيوب وإصلاحها.', 'eXtreme Programming works with Continuous Integration – deploying a single code base on a daily basis and running automated regression tests to see if anything is broken. In this way defects are picked up quickly. Regular refactoring, or simplifying and cleaning the code also ensures it is easier to work with and easier to pick up and fix defects.', 1),
  (0, 141, 'أنت مدير مشروع أجايل، تعمل مع مدرّب أجايل (Agile Coach) وتخطط للسبرنت (Sprint) التالي مع الفريق. ينصحك مدرّب أجايل بتضمين بعض "الفائض" (Slack) في السبرنت. ماذا يعني ذلك؟', 'You are an Agile project manager, working with an Agile coach and planning the next sprint with the team. The Agile coach advises you to build in some “slack” for the sprint. What does this mean?', 'تضمين الفائض (Slack) هو طريقة لإتاحة بعض المجال في النقاط المخصصة لسبرنت الفريق. ويقوم مدير مشروع أجايل أو المدرّب أو الميسّر أو القائد بذلك عن طريق إضافة بطاقات لإعادة هيكلة الشفرة البرمجية (Refactoring)، ثم تحديد سرعة الفريق (Velocity) بناءً على ذلك. وتضمن إعادة الهيكلة المنتظمة أن تكون الشفرة البرمجية نظيفة وصحيحة، ويمكن استبدال بطاقة إعادة الهيكلة إذا طرأت حالة طارئة. وبهذه الطريقة، يكون ذلك "فائضاً" أو هامشاً مرناً مدمجاً في السبرنت.', 'Building in slack is a way of giving some room in the allocated points for a team Sprint. The Agile project manager, coach, facilitator or lead does this by adding in cards for refactoring the code, then basing the team’s velocity off that. Refactoring regularly ensures the code is clean and correct, and the refactoring card can be replaced if an emergency comes up. In this way, it is “slack”, or lee-way built into the sprint.', 1),
  (0, 142, 'يخطط الفريق لسبرنته (Sprint) الأول القادم في مشروع أجايل. وقد عمل الفريق مع مالك المنتج (Product Owner) الذي جمع قائمة أعمال متراكمة (Backlog) من الميزات مرتبة حسب الأولوية. بصفتك مدير مشروع أجايل، ما الذي يجب عليك فعله لضمان قدرتك على تخطيط السبرنتات المستقبلية بشكل صحيح؟', 'The team are planning their first upcoming sprint on an Agile project. They have worked with the product owner who has gathered a backlog of features in prioritised order. As an Agile project manager, what must you do to ensure you can plan future sprints correctly?', 'يعتمد سبرنت أجايل على سرعة الفريق (Velocity). وسرعة الفريق هي مقدار النقاط (أو البطاقات، أو الميزات، أو أي وحدة تختارها) التي يستطيع الفريق إكمالها في المتوسط خلال سبرنت اعتيادي. وستحتاج إلى إكمال سبرنت واحد على الأقل للحصول على فكرة عن السرعة.', 'An Agile sprint is based on the team’s velocity. The team’s velocity is the amount of points (or cards, or features, or whatever you choose) the team is able to complete on average during a regular sprint. You will need to complete at least one sprint to get an idea of velocity.', 1),
  (0, 143, 'أنت مدير مشروع أجايل، ومنظمتك تنتقل من نهج الشلال (Waterfall) إلى أسلوب عمل أجايل. بعد قراءة بيان أجايل (Agile Manifesto)، يذكر المدير الوظيفي (Functional Manager) الذي تعمل معه عبارة "الأفراد والتفاعلات أهم من العمليات والأدوات" ويسألك كيف ستحقق ذلك. بماذا تجيبه؟', 'You are an Agile project manager and your organization is moving away from waterfall to an Agile way of work. After reading the Agile manifesto, the functional manager you are working with mentions “individuals and interactions over processes and tools” and asks how you will do it. What do you tell them?', 'تستند العديد من ممارسات أجايل إلى نهج تعاوني يتيح اتخاذ قرارات سريعة وتحمّل مسؤولية العمل. وإحدى طرق تحقيق ذلك هي التواجد في مكان واحد (Co-location) للفريق، ومن الطرق الأخرى اجتماع الوقوف اليومي (Daily Stand-up)، وتخطيط الفريق للتكرار (Iteration) التالي، والاجتماعات الاستعادية (Retrospectives) لتحسين أسلوب العمل في المستقبل.', 'Many Agile practices are based on a collaborative approach, which enables fast decisions and ownership of the work. One way to do this is co-locate the team, but others are the daily stand-up, team planning of the next iteration, and retrospectives to improve the way of work moving forward.', 1),
  (0, 144, 'أنت مدير وظيفي ذو خبرة طُلب منك قيادة فريق مشروع أجايل. ويسمي مديرك التنفيذي هذا الدور "مدرّب المشروع" أو دور سكرم ماستر (Scrum Master). وأنت تعلم أن قيادة أجايل قد تختلف عما اعتدت عليه. ما نوع أسلوب القيادة الذي ستتبناه؟', 'You are an experienced functional manager who has been asked to lead an Agile project team. Your executive manager is calling it the “project coach” or scrum master role. You know that Agile leadership might be different to what you are used to. What sort of leadership style will you embody?', 'قائد أجايل هو في المقام الأول قائد خادم (Servant Leader)، أي مدرّب للمشروع. وينصبّ التركيز على إزالة العوائق أمام الفريق، ومساعدته على حل المشكلات، وتنمية مهاراته عند الحاجة.', 'An Agile leader is primarily a servant leader, a project coach. The focus is on removing blockers for the team, helping them problem solve and growing their skills where needed.', 1),
  (0, 145, 'تعمل مدير مشروع أجايل في فريق مشروع جديد. كثير من أعضاء فريق المشروع محبطون، ولا يحضرون الاجتماعات والمراسم التي حددتها. ماذا ستفعل بعد ذلك؟', 'You are working as an Agile project manager in a new project team. Many project team members are despondent, and do not show up for the meetings and ceremonies you have set. What will you do next?', 'يركز قائد أجايل على توجيه الفريق (Coaching)، وإزالة العوائق، وضمان التفاعل. وتساعد مراسم أجايل الرئيسية مثل اجتماعات الوقوف (Stand-ups)، ومراجعات السبرنت (Sprint Reviews)، والاجتماعات الاستعادية (Retrospectives) على دعم العمل وتحسينه والحصول على الإجابات التي يحتاجها الأفراد.', 'An Agile leader focuses on coaching the team, removing blockers and ensuring interaction. The key Agile ceremonies such as stand-ups, sprint reviews and retrospectives help support and improve the work and get the answers people need.', 1),
  (0, 146, 'أنت مدير مشروع ذو خبرة اعتدت على أسلوب القيادة التوجيهية حيث يفعل الناس ما تقوله بالضبط. والآن تعمل في فريق أجايل، حيث هذا الأسلوب من القيادة غير مقبول. ما الشيء الواحد الذي يمكنك تغييره للانتقال إلى أسلوب أقرب إلى القيادة الخادمة (Servant Leadership)؟', 'You are an experienced project manager who is used to a directive leadership style where people do exactly what you say. Now you are working in an Agile team, where that style of leadership is not accepted. What is one thing you can change to move to a more servant leadership style?', 'تهدف أساليب أجايل إلى تمكين الفريق (Empowerment)، مما يعني أنهم بحاجة إلى أن يكونوا صانعي قرار فعّالين. وغالباً ما تُتخذ القرارات إما بالاتفاق الجماعي، حيث يوافق الفريق على القرار أو النهج، أو بالقرار المشترك، حيث يحل الفريق المشكلة ويتشارك المدخلات ويصل إلى القرارات معاً.', 'Agile methods aim to empower the team, which means they need to be effective decision makers. Decisions are often made by either collective agreement, where the team agrees with the decision or approach, or a shared decision, where the team problem solve, share input, and arrive at decisions together.', 1),
  (0, 147, 'تعمل على متطلبات التكرار (Iteration) التالي ويحتاج الفريق إلى اتخاذ قرار. يقترح مالك المنتج (Product Owner) استخدام رفع الأيدي للإشارة إلى ما إذا كان أعضاء الفريق مؤيدين للقرار أو معارضين له. بصفتك مدير مشروع أجايل، تعترض على هذا النهج. لماذا؟', 'You are working on the requirements for the next iteration and a decision needs to be made by the team. The product owner suggests using a show of hands to indicate whether team members are for or against the decision. As the Agile project manager, you object to this approach. Why?', 'بمجرد التصويت بـ"مؤيد" أو "معارض"، لن يكون هناك نقاش قد يُفضي إلى قرار أفضل أو بديل للمسألة. وبجعل الأصوات مرئية، يصبح أعضاء الفريق أكثر عرضة للتأثر بقرارات الآخرين، خاصة إذا كانوا يتبعون لهم إدارياً خارج بيئة المشروع.', 'With just a “for” or “against” vote, there will be no discussion that might produce a better or alternative decision for the issue. By making the votes visible, team members are more easily influenced by others’ decisions, especially if they report to them outside of the project environment.', 1),
  (0, 148, 'يتواصل معك أحد التنفيذيين في منظمتك بشأن العمل في فريق أجايل. وقد سمع عن التطوير المعتمد على الميزات (FDD) ويرغب في تجربته على سبيل "الاختبار والتعلم" في فريقك. ماذا يقصد بذلك؟', 'An executive in your organisation approaches you about working in an Agile team. They have heard about Feature Driven Development and would like to try it as a “test and learn” in your team. What do they mean by this?', 'يبدأ التطوير المعتمد على الميزات (FDD) في أجايل بنموذج شامل للميزات، ثم يخطط ويصمم ويبني وفقاً لتلك الميزات. وبمجرد اكتمال ميزة ما، يمكن أن تبدأ العملية من جديد، مع الاستفادة من أي تعلّم من الميزة السابقة.', 'Agile Feature Driven Development starts with an overall feature model, then plans, designs and builds by those features. Once a feature is complete, the process can begin again, complete with any learning from the previous feature.', 1),
  (0, 149, 'في كانبان (Kanban) أو أجايل "القائم على التدفق"، تتبع التكرارات عدد بطاقات القصص ضمن حد العمل قيد التنفيذ (WIP)، المعروض على اللوحة المرئية أو الافتراضية. ويسحب الفريق البطاقات من عمود قائمة الأعمال المتراكمة (Backlog) على لوحة كانبان بناءً على طاقته الاستيعابية. وتوفر بطاقات القصص هذه زيادة (Increment) من القيمة وهي:', 'For Kanban or "Flow based" Agile, iterations follow the number of story cards in the Work in Progress limit, shown on the visual or virtual board. The team pulls cards from the backlog column on the Kanban board based on their capacity. These story cards provide an increment of value and are:', 'مفتاح كانبان هو جعل التقدم مرئياً. ويحسّن التقدم بطبيعته مشاركة الفريق (فلا أحد يحب أن يكون عالقاً، والعوائق واضحة ليراها الأفراد ويساعدوا في حلها).', 'The key to Kanban is making progress visible. Progress naturally improves team engagement (no one likes being stuck, and blockers are clear for people to see and assist with).', 1),
  (0, 150, 'انضممت للتو إلى فريق أجايل ويحتاج الفريق إلى اتخاذ قرار بشأن متطلبات المنتج. يطلب سكرم ماستر (Scrum Master) من الفريق إظهار مدى ثقتهم في القرار برفع أصابع يد واحدة (من قبضة مغلقة إلى خمسة أصابع). ماذا يعني أن يرفع أحد أعضاء الفريق أقل من ثلاثة أصابع؟', 'You have just come on board an Agile team and a decision needs to be made about product requirements. The scrum master asks the team to show their confidence in the decision by holding up their fingers on one hand (a closed fist through to five fingers). What does it mean if a team member holds up fewer than three?', 'عند التصويت في فريق أجايل باستخدام قبضة الخمسة (Fist of Five)، فإن الأعضاء الذين يصوّتون بثلاثة أصابع أو أقل لديهم قلق أو اعتراض على القرار ويرغبون في الحصول على فرصة لمناقشته بشكل أكبر.', 'When voting in an Agile team using the Fist of Five, members who vote with three or fewer fingers have a concern or conflict with the decision and would like an opportunity to discuss it further.', 1),
  (0, 151, 'أنت في بداية تكرار (Iteration) جديد وعلى وشك التخطيط وتحديد ما سيتم العمل عليه في السبرنت (Sprint) القادم. وتقرر دعوة جميع أصحاب المصلحة في المشروع إلى اجتماع التخطيط لتحديد ما سيتم العمل عليه لاحقاً. لماذا من المهم إشراك جميع أصحاب المصلحة في اتخاذ القرار؟', 'You are at the beginning of a new iteration and about to plan and decide what gets worked on in the upcoming sprint. You decide to invite all project stakeholders to the planning meeting to decide what to work on next. Why is it important that all stakeholders are involved in decision-making?', 'إعطاء ملكية القرارات للفريق وأصحاب المصلحة هو إحدى طرق كسب تأييدهم. فإذا شارك أصحاب المصلحة في اتخاذ القرار، سيكونون أكثر التزاماً بأي قرار يُتخذ وبالمشروع.', 'Giving ownership of decisions to the team and stakeholders is one way to gain their buy-in. If stakeholders are involved in decision-making, they will be more committed to any decision made and to the project.', 1),
  (0, 152, 'أنت في منطقة عمل فريق أجايل وتلاحظ أنها تختلف عن مناطق المشاريع الأخرى التي عملت فيها. يخبرك مدير المشروع بأن هناك طرقاً معينة لضمان بقاء أصحاب المصلحة (Stakeholders) منخرطين. عمّ يتحدث؟', 'You are in an Agile team area and notice it is different to other project areas you have worked on. The project manager tells you there are certain ways to ensure that stakeholders stay engaged. What is he talking about?', 'يساعد التقدم المرئي في الحفاظ على انخراط الفريق، ويتم تيسيره من خلال استخدام لوحة عرض المعلومات (Information Radiator) – بحيث تكون لوحة كانبان (Kanban Board)، ومخطط الإنجاز التنازلي (Burndown Chart)، وقائمة أعمال المنتج المتراكمة (Product Backlog) مرئية بوضوح للجميع.', 'Visible progress helps maintain team engagement, and is facilitated through the use of the information radiator – Kanban board, burndown chart, product backlog being clearly visible to all.', 1),
  (0, 153, 'تم تحديدك كصاحب مصلحة (Stakeholder) في فريق تطوير برمجيات يعمل بأجايل. وعند انضمامك إلى اجتماع الوقوف (Stand-up) الخاص بالفريق، تتفاجأ بأن الفريق يضم ثمانية أشخاص فقط وليس أكثر – فالتسليم في نهاية المطاف كبير جداً. لماذا الفريق صغير بهذا الحجم؟', 'You have been identified as a stakeholder on an Agile software development team. As you join the team stand-up, you are surprised that there are only eight people on the team and not more – after all the deliverable is quite large. Why is the team so small?', 'توصي أساليب أجايل بفريق من 12 عضواً أو أقل، وعادةً ما يتراوح بين 3 و9 أعضاء. وهذا يحافظ على قلة قنوات الاتصال ويضمن انتقال المعلومات بسرعة ليتمكن الفريق من أداء عمله.', 'Agile methods recommend a team of 12 or fewer, typically between 3 and 9. This keeps the communication channels small and ensures information travels quickly for the team to do their work.', 1),
  (0, 154, 'بصفتك قائد مشروع أجايل، قمت بعناية بتكوين فريق أجايل من أشخاص ذوي مهارات على شكل "T"، أو متخصصين معمّمين (Generalizing Specialists). ماذا يعني ذلك؟', 'As the lead on an Agile project, you have carefully cultivated an Agile team of “T” shaped people, or generalising specialists. What does this mean?', 'المتخصص المعمّم هو شخص لديه مجال معرفة أو مهارة واحدة عميقة، ومجموعة واسعة من الاهتمامات أو المهارات العامة. ويتكون فريق أجايل بشكل مثالي من متخصصين معمّمين يستطيعون القيام بأكثر من شيء واحد، مع إتقان دورهم الأساسي.', 'A generalising specialist is a person that has one deep knowledge area or skill, and a wide range of general interests or skills. An Agile team is ideally made up of generalising specialists who can do more than one thing, but does their core role well.', 1),
  (0, 155, 'في عام 2001، اتفقت مجموعة من الأفراد الذين يمثلون منهجيات تطوير البرمجيات الخفيفة الأكثر استخداماً على مجموعة مشتركة من القيم والمبادئ أصبحت تُعرف باسم بيان أجايل (Agile Manifesto). وفي ذلك البيان، قدّروا:', 'In 2001, a group of individuals representing the most widely used lightweight software development methodologies agreed on a common set of values and principles which became known as the Agile Manifesto. In that manifesto they valued:', 'يتكون بيان أجايل من أربع قيم أساسية، إحداها تقدّر الأفراد والتفاعلات أهم من العمليات والأدوات.', 'The Agile manifesto is made up of four core values, one of which values Individuals and interactions over processes and tools.', 1),
  (0, 156, 'تخطط للتكرار (Iteration) التالي في فريق أجايل الخاص بك، بصفتك قائد أجايل. سيختار الفريق قصص المستخدم (User Stories) من قائمة أعمال الإصدار المتراكمة المرتبة حسب الأولوية، ويفصّل قصص المستخدم، ويقدّر العمل اللازم لكل قصة مستخدم. ويعتمد عدد القصص المختارة على:', 'You are planning the next iteration in your Agile team, as the Agile lead. The team is going to select user stories from the prioritized release backlog, elaborate the user stories, and estimate the work needed for each user story. The number of stories selected is based on:', 'سرعة فريق أجايل (Velocity) هي مقدار العمل الذي يكمله (في المتوسط) في تكرار معين. ويمكن قياسها بالنقاط، أو البطاقات، أو الميزات، أو القصص، أو مقاسات القمصان (T-Shirt Sizing)، أو أي طريقة أخرى تناسبك. غير أن عدد النقاط في السبرنت يعتمد على متوسط سرعة النقاط من التكرارات السابقة.', 'An Agile team’s velocity is the amount of work they complete (on average) in a given iteration. This can be measured in points, cards, features, stories, T-Shirt sizings or any other method that works for you. The number of points in a sprint, however, is based on the average velocity of points from previous iterations.', 1),
  (0, 157, 'يقف فريقك حول لوحة عليها بطاقات. ويجيب كل شخص عن هذه الأسئلة بالتناوب: "ما الذي أكملته منذ المرة السابقة؟ ما الذي أخطط لإكماله بين الآن والمرة القادمة؟ هل هناك ما يعيقني؟" ما الذي يقوم به فريقك؟', 'Your team is standing around a board with cards on it. Each person is answering these questions in a round-robin fashion: “What did I complete since last time? What am I planning to complete between now and next time? Is anything blocking me?” What is it your team is doing?', 'خلال اجتماع الوقوف اليومي (Daily Stand-up) في فريق أجايل، يسأل الفريق بالتناوب: "ما الذي أكملته منذ المرة السابقة؟ ما الذي أخطط لإكماله بين الآن والمرة القادمة؟ هل هناك ما يعيقني؟" وغالباً ما يتحدثون أيضاً عن البطاقات قيد التنفيذ على لوحة كانبان (Kanban Board).', 'During the daily stand-up in an Agile team, the team asks in a round-robin fashion: “What did I complete since last time? What am I planning to complete between now and next time? Is anything blocking me?” They also often talk to the cards in-flight on the Kanban board.', 1),
  (0, 158, 'هناك دورات حياة متعددة للمشروع يمكنك الاختيار من بينها، اعتماداً على نوع المشروع والبيئة والتسليم وأصحاب المصلحة. وأنت تعمل في مشروع يتطلب تسليم ميزات من منتج شامل بشكل منتظم. ما نوع دورة حياة المشروع التي ستختار العمل بها؟', 'There are multiple project life-cycles you can choose from, depending on the type of project, environment, deliverable and stakeholders. You are working on a project that requires features of an overall product to be delivered on a regular basis. What sort of project lifecycle will you choose to work with?', 'في حين أن الدورات الأخرى قد تستوفي معيار تسليم الميزات بانتظام، فإن دورة حياة المشروع التزايدية (Incremental Life Cycle) تحديداً تسلّم الميزات على شكل "زيادات" (Increments) من القيمة على مدى دورة حياة المشروع.', 'While others may meet the criteria of regularly delivered features, an Incremental Project Lifecycle specifically delivers features in “increments” of value over the lifecycle of a project.', 1),
  (0, 159, 'يعمل قائد فريق أجايل الخاص بك مع الفريق من خلال القيادة الخادمة (Servant Leadership)، وقد بنى بيئة آمنة للاختلاف في الرأي. كيف مكّن ذلك الفريق من المضي قدماً دون عقبات؟', 'Your Agile team leader works through servant leadership to the team, and has built a safe environment for disagreement. How has this empowered the team to move forward without obstacles?', 'يُشجَّع النقاش البنّاء والاختلاف في الرأي لضمان اكتشاف المخاطر والأفكار البديلة. ولا يمكن الحفاظ على ذلك إلا في فريق يتمتع بمستوى عالٍ من الأمان النفسي.', 'Constructive discussion and disagreement is encouraged to ensure risks and alternative ideas are found. This is only maintainable in a team with high psychological safety.', 1),
  (0, 160, 'تعمل في مشروع أجايل بصفتك مدير مشروع وتقوم بتخطيط السبرنت (Sprint Planning). وتخطط العمل المقرر إكماله قريباً بالتفصيل، بينما يُخطط العمل طويل الأجل على مستوى عالٍ. ماذا يُسمى هذا؟', 'You are working on an agile project as a project manager and performing sprint planning. You are planning the work in detail to be completed soon, and long term work is planned at a high level. What is this called?', 'التخطيط بالموجة المتدحرجة (Rolling Wave Planning) هو نوع من التطوير التدريجي (Progressive Elaboration) حيث يُخطط العمل في المدى القريب بالتفصيل، بينما يُخطط العمل البعيد في المستقبل على مستوى عالٍ.', 'Rolling Wave Planning is a type of progressive elaboration where work in the near term is planned in detail, while the work far in the future is planned at a high level.', 1),
  (0, 161, 'أنت مدير مشروع أجايل (Agile) جديد في منظمتك. تطرح الأسئلة على فريقك لاستخلاص احتياجاتهم ومساعدتهم على حل المشكلات عند ظهورها. ما الدور الذي تؤديه في فريق أجايل؟', 'You are the project manager of a new Agile project for your organization. You ask questions of your team to elicit their needs and help them problem solve issues as they arise. What role are you filling in the Agile team?', 'يمكن أن يُطلق على قائد المشروع مسميات كثيرة في أجايل، لكنه يتمحور عادةً حول القيادة الخادمة (Servant Leadership) ودور مدرّب المشروع الذي يساعد على تنمية الفريق وإزالة العوائق التي تعترض عمله.', 'The project lead can be called many things in Agile but usually centres around servant leadership and a project coach role, who helps grow the team and remove blockers to their work.', 1),
  (0, 162, 'أنت مدير مشروع أجايل (Agile) تقود مشروع برمجيات جديداً. خلال الاجتماع الاستعادي (Retrospective) الأخير كان هناك قدر ضئيل جداً من المشاركة والتغذية الراجعة، ويبدو أن الفريق يفقد اهتمامه بالعمل. ماذا ستفعل لتحسين الوضع؟', 'You are an Agile project manager leading a new software project. During the last retrospective there was very little engagement and feedback, and the team seem to be losing interest in the work. What will you do to improve the situation?', 'إذا لم يُسفر الاجتماع الاستعادي (Retrospective) السابق عن معلومات، فإن عقد اجتماع آخر يعني فعل الشيء نفسه مع توقع نتيجة مختلفة. إن التعرف على نقاط قوة كل عضو في الفريق ومساعدته على أداء المزيد من ذلك النوع من العمل يعزز المشاركة، وكذلك مواءمة أهدافهم مع أهداف المشروع. وعندما تتوافق هذه الأمور يعمل الناس بطبيعتهم بجدية أكبر ويهتمون أكثر.', 'If a previous Retrospective did not elicit information, holding another one would be doing the same thing but expecting a different result. Finding out each team member’s strengths and helping them do more of that work helps engagement, as does aligning their goals to those of the project. When these things are aligned people naturally work harder and care more.', 1),
  (0, 163, 'أنت تعمل مديراً للمشروع في فريق ينتقل إلى أسلوب عمل أجايل (Agile). كنت في السابق تتواصل مع الفريق من خلال اجتماع أسبوعي واحد، مع البريد الإلكتروني كوسيلة الاتصال الأساسية. ما التغييرات التي ستجريها في فريق أجايل الجديد؟', 'You are working as a project manager in a team that is moving to an Agile way of work. You have previously engaged the team in a single weekly meeting, with email as the primary communication. What changes will you make in the new Agile team?', 'يركز أجايل (Agile) على الأفراد والتفاعلات، وعلى التواجد في مكان واحد (Co-location) لاكتساب المعلومات من خلال التواصل الأسموزي (Osmotic Communication)، مع كون المناقشات وجهاً لوجه هي أسلوب الاتصال الموصى به.', 'Agile focuses on individuals and interaction, co-locating the team to gain information by osmosis, with face-to-face discussions being the recommended method of communication.', 1),
  (0, 164, 'تعني كلمة كانبان (Kanban) باللغة اليابانية "إشارة مرئية" أو بطاقة. وهي شكل من أشكال الإدارة المرئية مأخوذ من التصنيع وفق منهجية لين (Lean Manufacturing)، وتُستخدم لمراقبة …', 'Kanban translates to “visual sign” or card, in Japanese. It is a form of visual management taken from Lean Manufacturing, for monitoring …', 'كانبان (Kanban) إطار عمل مستمد من نظام تويوتا للإنتاج، ويُستخدم في تطوير البرمجيات والعمل المعرفي. وهو يركز على لوحة كانبان (Kanban Board) التي تعرض العمل الحالي قيد التنفيذ وتحدّ منه.', 'Kanban is a framework from the Toyota Production System, utilised in software development and knowledge work. It focuses on the Kanban board, which shows and limits current work in progress.', 1),
  (0, 165, 'أنت تعمل مع فريق أجايل (Agile) يستخدم كانبان (Kanban) لإدارة تدفق العمل عبر الفريق. يذكر سكرم ماستر (Scrum Master) أو قائد أجايل مفهوم "السحب" (Pull) الذي يساعدهم على إدارة العمل. ماذا يعني ذلك؟', 'You are working with an Agile team who use Kanban to manage the flow of work through the team. The Scrum Master or Agile lead mentions the concept of “pull”, which helps them manage the work. What does this mean?', 'تتيح كانبان (Kanban) لأعضاء الفريق سحب عمل جديد إلى لوحة كانبان عندما يكونون جاهزين، وتحدّ من كمية العمل على تلك اللوحة، وتشجع على التدفق الأمثل للعمل.', 'Kanban allows team members to pull new work onto the Kanban board when they are ready, limits the amount of work on that board, and encourages an optimal flow of work.', 1),
  (0, 166, 'أنت تستعرض الميزة التالية مع مالك المنتج (Product Owner) في فريق أجايل (Agile). وهو جديد على أجايل، وغير متأكد مما تعنيه كانبان (Kanban) حقاً. يسرد لك بعض الأمور للتحقق منها. أيٌّ مما يلي ليس من الخصائص الأساسية لكانبان؟', 'You are walking through the next feature with the product owner in an Agile team. He is new to Agile, and unsure of what Kanban really is. He lists a few things for you to check. Which of the below is NOT one of the core properties of Kanban?', 'كانبان (Kanban) أسلوب مستعار من نظام تويوتا للإنتاج، أو لين (Lean). وهو يركز على الحد من العمل قيد التنفيذ حتى يكون العمل مركّزاً، وضمان وجود حلقات التغذية الراجعة، وجعل العمل مرئياً حتى تتضح نقاط الاختناق.', 'Kanban is a method borrowed from the Toyota Production System, or Lean. It focuses on limiting the work in progress so work is focusses, ensuring feedback loops are in place, and making the work visible so blockages are clear.', 1),
  (0, 167, 'أنت تعمل في مشروع أجايل (Agile) بصفتك مدير مشروع أجايل. وقد كنت تعمل باستخدام كانبان (Kanban) لمراقبة العمل وإبقائه مرئياً للجميع. ما الذي لا يُعدّ مبدأً محدِّداً لكانبان؟', 'You are working on an Agile project as an Agile project manager. You have been working using Kanban to monitor the work and keep it visible for all to see. What is NOT a defining principle of Kanban?', 'تشجع كانبان (Kanban)، شأنها شأن أجايل نفسه، على مشاركة الفريق بدلاً من القيادة التوجيهية. فهي تُبقي العمل مرئياً لتوضيح العوائق، حتى يتمكن الجميع من المساعدة في إزالتها والحفاظ على تدفق العمل عبر الفريق.', 'Kanban, like Agile itself, encourages team participation over directive leadership. It keeps the work visible to make blockers clear, so everyone can assist in removing them and keeping work flowing through the team.', 1),
  (0, 168, 'في عام 2001، اتفقت مجموعة من الأفراد، يمثلون منهجيات تطوير البرمجيات الخفيفة الأكثر استخداماً، على مجموعة مشتركة من القيم والمبادئ أصبحت تُعرف باسم بيان أجايل (Agile Manifesto). أيٌّ مما يلي يُعدّ إحدى القيم الأساسية لبيان أجايل؟', 'In 2001, a group of individuals, representing the most widely used lightweight software development methodologies, agreed on a common set of values and principles which became known as the Agile Manifesto. Which of the following is one of the Agile Manifesto''s core values?', 'يركز بيان أجايل (Agile Manifesto) على أربع عبارات للقيم الأساسية، إحداها "البرمجيات العاملة أهم من التوثيق الشامل".', 'The Agile Manifesto focuses on four core value statements, one of which is “Working software over comprehensive documentation”.', 1),
  (0, 169, 'أنت تعمل في مشروع أجايل (Agile) وطُلب منك إنشاء وثيقة تسرد مبادئ الفريق واتفاقياته وإرشاداته بشأن السلوك المقبول من أعضاء الفريق. ما الذي تعمل عليه؟', 'You are working on an Agile project and have been asked to create a document that lists team principles, agreements, and guidelines about the acceptable behaviour by team members. What are you working on?', 'ميثاق الفريق (Team Charter) هو وثيقة تسرد مبادئ الفريق واتفاقياته وتعليماته وإرشاداته بشأن السلوك المقبول من أعضاء فريق المشروع.', 'The Team Charter is a document that lists team principles, agreements, instructions and guidelines about the acceptable behaviour by project team members.', 1);
INSERT INTO new_choices (exam_no, question_index, position, text_ar, text_en, is_correct) VALUES
  (0, 0, 0, 'يستطيع الفريق الاجتماع بوتيرة أكبر عندما يكون متواجدًا في مكان واحد.', 'The team is able to meet more frequently when co-located.', false),
  (0, 0, 1, 'يصبح من الأسهل تسليم العمل إلى شخص ما إذا كان يتوافق مع نقاط قوته.', 'It is easier to hand off work to someone if it meets their strengths.', false),
  (0, 0, 2, 'إنه عملية مكتوبة تُتاح لجميع أعضاء الفريق من أجل الشفافية.', 'It is a written process made available to everyone in the team for transparency.', false),
  (0, 0, 3, 'سيسمع الفريق عرضًا المحادثات والمعلومات المتداولة في المساحة المشتركة، مما سيساعدهم على حل المشكلات المستقبلية.', 'The team will overhear conversations and information in the common area that will help them solve future problems.', true),
  (0, 1, 0, 'استخدام برامج المراسلة الجماعية، واجتماعات الوقوف اليومية عبر المؤتمرات الهاتفية، ولوحة كانبان إلكترونية وقائمة أعمال متراكمة إلكترونية.', 'Utilise group messaging software, daily teleconference stand-ups, an electronic Kanban and backlog.', true),
  (0, 1, 1, 'الطلب من المنظمة نقل الفريق لضمان وجود الجميع في المكان نفسه.', 'Ask the organisation to re-locate the team to ensure everyone is in the same place.', false),
  (0, 1, 2, 'توظيف أعضاء فريق جدد أو إيجادهم من داخل المنظمة ممن يوجدون في المكان نفسه حتى تتمكن من جمع الفريق في مكان واحد.', 'Hire or find new team members from within the organisation who are in the same place so you can co-locate.', false),
  (0, 1, 3, 'إلغاء جميع الاجتماعات حتى يتمكن الأفراد من التركيز على عملهم دون تشتيت.', 'Remove all meetings so people can focus on their work without distraction.', false),
  (0, 2, 0, 'إنشاء لوحة للفريق تتضمن خلفياتهم وصورهم.', 'Have a team board with their backgrounds and pictures.', false),
  (0, 2, 1, 'تبديل الأدوار بين أعضاء الفريق حتى يتعرف كل عضو على طبيعة عمل الآخرين.', 'Swap roles throughout the team so each member gets a feel for what others do.', false),
  (0, 2, 2, 'تشكيل أزواج من أعضاء الفريق للعمل على المهام، وتدوير الأزواج مع كل ميزة.', 'Pair up team members to work on tasks, and rotate the pairs for each feature.', true),
  (0, 2, 3, 'إقامة غداء تعليمي افتراضي يشارك فيه أعضاء الفريق شيئًا عن أنفسهم.', 'Have a virtual lunch and learn where team members share something about themselves.', false),
  (0, 3, 0, 'يوضح عدد أعضاء الفريق الذين ينضمون إلى المشروع ويغادرونه.', 'It shows how many team members are moving on and off the project.', false),
  (0, 3, 1, 'يوضح المهام المتبقية مقارنةً بما كان مخططًا له في تكرار معين.', 'It shows the remaining tasks versus what was planned for a given iteration.', true),
  (0, 3, 2, 'يوضح الاختبارات الآلية التي تُجرى كجزء من التكامل المستمر.', 'It shows the automated tests run as part of continuous integration.', false),
  (0, 3, 3, 'يوضح العائد على الاستثمار للميزات المسلّمة.', 'It shows the return on investment for the delivered features.', false),
  (0, 4, 0, 'عدد النقاط أو المهام أو الميزات التي يكملها الفريق في كل تكرار معين.', 'The number of points, tasks or features completed by the team in each given iteration.', true),
  (0, 4, 1, 'عدد أعضاء الفريق العاملين في مشروع أجايل على مدى حياة المشروع.', 'The number of team members working on the Agile project over the life of the project.', false),
  (0, 4, 2, 'مدى سرعة إكمال كل عضو في الفريق لعمله كل يوم.', 'How fast each team member completes their work each day.', false),
  (0, 4, 3, 'السرعة التي تُستهلك بها ميزانية المشروع.', 'The speed with which the project budget is being used up.', false),
  (0, 5, 0, 'تفاوض المطورين أهم من التعاون على الميزات.', 'Developer negotiation over feature collaboration.', false),
  (0, 5, 1, 'تفاعل مالك المنتج أهم من تفويض سكرم ماستر.', 'Product owner interaction over Scrum Master delegation.', false),
  (0, 5, 2, 'التعاون مع العميل أهم من التفاوض على العقد.', 'Customer collaboration over contract negotiation.', true),
  (0, 5, 3, 'إنجاز الأشياء بشكل صحيح أهم من إنجاز الأشياء الصحيحة.', 'Getting things right over getting the right things.', false),
  (0, 6, 0, 'نهج دورة حياة مشروع تنبؤية.', 'A Predictive project lifecycle approach.', false),
  (0, 6, 1, 'نهج دورة حياة مشروع أجايل', 'An Agile project lifecycle approach', false),
  (0, 6, 2, 'نهج دورة حياة مشروع تزايدية', 'An Incremental project lifecycle approach', false),
  (0, 6, 3, 'نهج دورة حياة مشروع تكرارية', 'An Iterative project lifecycle approach', true),
  (0, 7, 0, 'يتيح التخطيط التكيفي لراعي المشروع التكيف مع خطة المشروع بمرور الوقت.', 'Adaptive planning allows the project sponsor to adapt to the project plan over time.', false),
  (0, 7, 1, 'يتيح التخطيط التكيفي للفريق تسليم ميزات قابلة للاستخدام مع إعادة ترتيب أولويات الأجزاء التالية باستمرار بناءً على القيمة التجارية.', 'Adaptive planning allows the team to deliver usable features while continually reprioritising next pieces based on business value.', true),
  (0, 7, 2, 'يضمن التخطيط التكيفي قدرة المستخدمين على التكيف مع المنتج الذي يسلّمه فريق المشروع.', 'Adaptive planning ensures that the users can adapt to the product delivered by the project team.', false),
  (0, 7, 3, 'يصبح التخطيط التكيفي مستقرًا بعد اكتمال النموذج الأولي.', 'Adaptive planning is stable after the prototype is complete.', false),
  (0, 8, 0, 'تحليل قيمة كل ميزة مع مالك المنتج، مقابل الجهد والمخاطر لكل بند مع فريق أجايل.', 'Analyse the value of each feature with the product owner, versus the effort and risk of each item with the Agile team.', true),
  (0, 8, 1, 'التركيز على المهام الأقصر أولاً حتى تتمكن من تسليم القيمة بسرعة.', 'Focus on the shortest tasks first so you can deliver value quickly.', false),
  (0, 8, 2, 'اختيار تسليم المشروع بأكمله في النهاية حتى يتمكن راعي المشروع من رؤيته كاملاً.', 'Choose to deliver the entire project at the end so the project sponsor can see it all together.', false),
  (0, 8, 3, 'عن طريق سؤال العملاء عما يريدون تسليمه أولاً.', 'By asking the customers what they want delivered first.', false),
  (0, 9, 0, 'التقدير التناظري (Analogous Estimating)، باستخدام الجهد الفعلي لميزة مماثلة في مشروع مختلف.', 'Analogous estimating, using actual effort from a similar feature on a different project.', true),
  (0, 9, 1, 'تحديد الحجم بمقاسات القمصان (T-shirt Sizing)، باستخدام مقاسات عامة: صغير أو متوسط أو كبير لاستيعاب التباين.', 'T-shirt sizing, using broad Small, Medium or Large sizes to accommodate variation.', false),
  (0, 9, 2, 'تقدير النقاط الثلاث (Three-point Estimating)، حيث يقدم الفريق متوسط التقدير المتفائل والمتشائم والأكثر احتمالاً.', 'Three point estimating, where the team gives the average of an optimistic, pessimistic and most likely estimate.', false),
  (0, 9, 3, 'ينبغي أن يقوم مالك المنتج بتقدير بطاقات القصص لأنه من يحصل على فائدة الميزات المسلّمة.', 'The product owner should estimate the story cards as they are getting the benefit of the delivered features.', false),
  (0, 10, 0, 'تجزئة الميزة إلى مهام أو قصص مستخدم، ثم تقدير المدة التي يستغرقها إكمال تلك المهام مع فريق التطوير.', 'Break down the feature into tasks or user stories, then estimate how long those tasks will take to complete with the dev team.', true),
  (0, 10, 1, 'أخذ إجمالي عدد الأفراد في الفريق، مضروبًا في ساعات العمل، مقسومًا على عدد الميزات في قائمة الأعمال المتراكمة.', 'Take the total number of people in the team, multiplied by the hours worked, divided by the number of features in the backlog.', false),
  (0, 10, 2, 'سؤال راعي المشروع عن عدد التكرارات الممولة للمشروع، ثم التخطيط لإكمال الميزات بحلول نهاية تلك المدة.', 'Ask the sponsor how many iterations the project is funded for, then plan to complete the features by the end of that time.', false),
  (0, 10, 3, 'إيجاد ميزة مماثلة سلّمها جزء آخر من المنظمة، واستخدامها كتقدير.', 'Find a similar feature delivered by another part of the organisation, and use that as your estimate.', false),
  (0, 11, 0, 'جزء من الوظائف صغير بما يكفي لإكماله في مدة من يوم واحد إلى 3 أيام.', 'A piece of functionality small enough to be completed in one to three days.', true),
  (0, 11, 1, 'وصف لمجموعة من الميزات من وجهة نظر العميل.', 'A description of a group of features from the viewpoint of the customer.', false),
  (0, 11, 2, 'قصة عن المستخدم النهائي حتى يفهم الفريق الميزة فهمًا كاملاً.', 'A story about the end-user so the team understands the feature completely.', false),
  (0, 11, 3, 'قائمة أعمال متراكمة مرتبة حسب الأولوية يمكن للفريق اختيار الميزات منها.', 'A prioritised backlog that the team can choose features from.', false),
  (0, 12, 0, 'يكرر الفريق العمل حول فكرة واحدة للتأكد من صحة تلك الفكرة.', 'The team iterates around one idea to make sure that idea is right.', false),
  (0, 12, 1, 'أنت تحسّن المنتج أو النتيجة من خلال نماذج أولية متعاقبة أو إثباتات للمفهوم.', 'You are improving the product or result through successive prototypes or proofs of concept.', true),
  (0, 12, 2, 'يقول راعي المشروع إن دورة حياة المشروع تكرارية.', 'The project sponsor says that the project lifecycle is iterative.', false),
  (0, 12, 3, 'أنت تستخدم سبرنتات أو تكرارات أجايل لإدارة عملك.', 'You are using Agile sprints or iterations to manage your work.', false),
  (0, 13, 0, 'التطوير بأكبر قدر ممكن لمعرفة ما يحقق أفضل نتيجة.', 'Developing as much as possible to see what gets the best result.', false),
  (0, 13, 1, 'إيجاد مالك المنتج أهم من إيجاد فريق التطوير.', 'Finding a product owner over finding a development team.', false),
  (0, 13, 2, 'أعضاء الفريق متعددو الوظائف أهم من دعم الإدارة التنفيذية.', 'Cross functional team members over executive buy-in.', false),
  (0, 13, 3, 'الاستجابة للتغيير أهم من اتباع خطة.', 'Responding to change over following a plan.', true),
  (0, 14, 0, 'دورتا الحياة التكرارية والتنبؤية.', 'Iterative and Predictive lifecycles.', false),
  (0, 14, 1, 'دورتا الحياة التزايدية والتنبؤية.', 'Incremental and Predictive lifecycles.', false),
  (0, 14, 2, 'دورتا الحياة التكرارية والتزايدية.', 'Iterative and Incremental lifecycles.', true),
  (0, 14, 3, 'دورتا الحياة التنبؤية وأجايل.', 'Predictive and Agile lifecycles.', false),
  (0, 15, 0, 'الاختبار على جميع المستويات، حيث يطبق الفريق الاختبار الشامل من البداية إلى النهاية واختبار الوحدات (لقصة أو ميزة فردية). وتفضّل فرق أجايل الاختبارات الآلية.', 'Test at all levels, where the team applies end-to-end testing and unit testing (of an individual story or feature). Agile teams prefer automated tests.', false),
  (0, 15, 1, 'التطوير المعتمد على الاختبار (TDD)، حيث يكتب الفريق اختبارات آلية قبل كتابة كود المنتج للمساعدة في حماية المنتج من الأخطاء.', 'Test-Driven Development, where the team writes automated tests before writing the product code to help mistake-proof the product.', false),
  (0, 15, 2, 'السبايك (Spike)، وهو بحث أو تجارب محددة بإطار زمني ومفيدة للتقدير، أو تحديد معايير القبول، أو تعلّم عنصر تقني أو وظيفي حاسم.', 'Spikes, which are time-boxed research or experiments and useful for estimation, acceptance criteria definition, or learning some critical technical or functional element.', false),
  (0, 15, 3, 'خطة إدارة المشروع، حيث يُخطَّط المشروع بالتفصيل مسبقًا لتجنب سوء الفهم من جانب أصحاب المصلحة في المشروع.', 'Project management plan, where the project is planned is detail up front to avoid misunderstanding by project stakeholders.', true),
  (0, 16, 0, 'تنقيح قائمة الأعمال المتراكمة لضمان العمل على البنود المهمة فقط.', 'Refine the backlog to ensure only important items are being worked on.', false),
  (0, 16, 1, 'إنشاء خطة إدارة الجدول الزمني لضمان معرفة موعد تسليم كل بند.', 'Create the schedule management plan to ensure you know when each item can be delivered.', false),
  (0, 16, 2, 'ترتيب البنود حسب أولوية الأعمال، ووضعها في تكرار، وإكمال البنود ثم إزالتها من قائمة الأعمال المتراكمة.', 'Sort the items by business priority, place them in an iteration, complete the items then remove them from the backlog.', true),
  (0, 16, 3, 'نقل البنود إلى مصفوفة تتبع المتطلبات حتى تتمكن من الإبلاغ عن تقدمها.', 'Move the items into the requirements traceability matrix so you can report on their progress.', false),
  (0, 17, 0, 'تطوير البطاقات فور إضافتها لضمان أقصى قيمة.', 'Developing the cards as soon as they are added to ensure maximum value.', false),
  (0, 17, 1, 'إزالة البطاقات التي لا يكون إكمالها منطقيًا من قائمة الأعمال المتراكمة.', 'Removing cards from the backlog that do not make sense to complete.', false),
  (0, 17, 2, 'تقدير العمل اللازم لكل بطاقة حتى يتمكن مالك المنتج من ترتيب الأولويات بناءً على القيمة والجهد.', 'Estimating the work needed for each card so the product owner can prioritise based on value and effort.', true),
  (0, 17, 3, 'حضور اجتماعات الوقوف اليومية للإبلاغ عما أُنجز بالأمس وما سيُنجز اليوم.', 'Coming to daily stand-ups to report on what was done yesterday and what will be done today.', false),
  (0, 18, 0, 'الطلب منهم التقدير على مستوى التكرار الكامل لإتاحة بعض المجال للتباين.', 'Ask them to estimate by whole iteration to give a little room for variation.', false),
  (0, 18, 1, 'تقدير البطاقات بأيام كاملة بدلاً من الجهد لكل بطاقة.', 'Estimate the cards in full days instead of effort per card.', false),
  (0, 18, 2, 'استخدام التقديرات المقارنة أو تحديد الحجم النسبي مثل مقاسات القمصان (T-shirt Sizing) أو نقاط القصة (Story Points).', 'Use comparative estimates or relative sizing such as T-shirt sizing or story points.', true),
  (0, 18, 3, 'ترتيب أولويات قائمة الأعمال المتراكمة بناءً على قيمة العميل.', 'Prioritise the backlog based on customer value.', false),
  (0, 19, 0, 'يراجع مالك المنتج قائمة الأعمال المتراكمة لتحديد حجم بطاقات القصص.', 'The Product Owner works through the backlog to size the story cards.', false),
  (0, 19, 1, 'يعمل فريق أجايل معًا لتحديد حجم بطاقات القصص، معتمدًا في الغالب على معلومات من المطورين والمختبرين.', 'The Agile team work together to size the story cards, relying mostly on information from the developers and testers.', true),
  (0, 19, 2, 'يقوم قائد فريق أجايل أو سكرم ماستر بتحديد حجم بطاقات القصص نيابةً عن الفريق.', 'The Agile team leader or scrum master works to size the story cards for the team.', false),
  (0, 19, 3, 'يحدد العميل حجم بطاقات القصص لضمان أقصى قيمة.', 'The customer sizes the story cards to ensure maximum value.', false),
  (0, 20, 0, 'لم يُدرج الفريق أيام الإجازات المرضية في التقدير.', 'The team have not included sick days in the estimate.', false),
  (0, 20, 1, 'لم يُدرج الفريق الاختبار أو إعادة الهيكلة في التقدير.', 'The team have not included testing or refactoring in the estimate.', true),
  (0, 20, 2, 'لم يُدرج الفريق الوقت اللازم لدمج الكود من أجل التكامل المستمر.', 'The team have not included time to merge the code for continuous integration.', false),
  (0, 20, 3, 'لم يُدرج الفريق الوقت الذي يستغرقه اجتماع الوقوف اليومي.', 'The team have not included the time it takes for the daily stand-up.', false),
  (0, 21, 0, 'مناقشة ما كان ناجحًا، وما يمكن تحسينه، ودمج ذلك في التكرارات المستقبلية.', 'Discuss what was successful, what could be improved, and incorporate those into future iterations.', true),
  (0, 21, 1, 'مناقشة ما أعجب الفريق في العمل مع بعضهم البعض.', 'Discuss what the team liked about working with each other.', false),
  (0, 21, 2, 'مناقشة ما حدث من أخطاء، والتأكد من أن الفريق يعرف من يقع عليه اللوم.', 'Discuss what went wrong, and make sure the team knows who is to blame.', false),
  (0, 21, 3, 'مناقشة صلاحية الميزات التي يجري تطويرها.', 'Discuss the validity of the features being developed.', false),
  (0, 22, 0, 'يقلل وقت التواصل بين راعي المشروع والمطورين.', 'It reduces the communication time between the project sponsor and the developers.', false),
  (0, 22, 1, 'يضمن إصدار الميزات في الموعد المحدد وضمن الميزانية.', 'It ensures features are released on schedule and on budget.', false),
  (0, 22, 2, 'يساعد الفريق على التعرف على عمليته وتحسينها بمرور الوقت.', 'It helps the team learn about and improve their process over time.', true),
  (0, 22, 3, 'يُبقي الفريق مركزًا على الميزة الرئيسية لتسليم أكبر قدر من القيمة التجارية.', 'It keeps the team focused on the main feature to deliver the most business value.', false),
  (0, 23, 0, 'عندما ينجز الفريق شيئاً جديداً أو يسلّمه.', 'When the team completes or ships something new.', false),
  (0, 23, 1, 'عندما تمضي أكثر من بضعة أسابيع منذ الاجتماع الاستعادي السابق.', 'When more than a few weeks have passed since the previous retrospective.', false),
  (0, 23, 2, 'عندما يبدو الفريق متعثراً ولا يتدفق العمل المنجز.', 'When the team appears to be stuck and completed work is not flowing.', false),
  (0, 23, 3, 'عندما لم تُنشأ قائمة الميزات المتراكمة بعد ولم يبدأ العمل.', 'When the feature backlog has not been created and work is yet to begin.', true),
  (0, 24, 0, 'التقدير التناظري، باستخدام الجهد الفعلي لميزة مماثلة من مشروع مختلف.', 'Analogous estimating, using actual effort from a similar feature on a different project.', true),
  (0, 24, 1, 'التحجيم بمقاسات القمصان، باستخدام مقاسات عامة مثل صغير أو متوسط أو كبير لاستيعاب التباين.', 'T-shirt sizing, using broad Small, Medium or Large sizes to accommodate variation.', false),
  (0, 24, 2, 'تقدير النقاط الثلاث، حيث يعطي الفريق متوسط التقدير المتفائل والمتشائم والأكثر ترجيحاً.', 'Three point estimating, where the team gives the average of an optimistic, pessimistic and most likely estimate.', false),
  (0, 24, 3, 'ينبغي أن يقدّر مالك المنتج بطاقات القصص لأنه هو من يحصل على منفعة الميزات المسلَّمة.', 'The product owner should estimate the story cards as they are getting the benefit of the delivered features.', false),
  (0, 25, 0, 'خطة إدارة المشروع، التي حددت تسليم المشروع بالكامل.', 'The Project Management Plan, that has outlined the project delivery in full.', false),
  (0, 25, 1, 'قائمة أعمال المنتج المتراكمة، التي تحتوي على قائمة الميزات التي سيسلّمها الفريق.', 'The product backlog, that has the list of features the team will deliver.', false),
  (0, 25, 2, 'خارطة طريق المنتج، التي تعرض الميزات المستقبلية المخططة وتواريخها التقريبية، على نحو مشابه لمخطط جانت.', 'The product roadmap, that shows planned future features and their approximate dates, similarly to a Gantt Chart.', true),
  (0, 25, 3, 'مخطط سرعة الفريق، الذي يوضح مقدار ما ينجزه الفريق في كل تكرار.', 'The team velocity chart, that shows how much the team completes each iteration.', false),
  (0, 26, 0, 'تطلب منهم حساب متوسط النقاط وإسناد تلك القيمة إلى البطاقة.', 'Ask them to average out the points and assign that value to the card.', false),
  (0, 26, 1, 'تغيّر أسلوب التقدير لاستيعاب قرار الفريق.', 'Change the method of estimating to accommodate the team decision.', false),
  (0, 26, 2, 'تغيّر الميزة لتسهيل تقديرها.', 'Change the feature to make it easier to estimate on.', false),
  (0, 26, 3, 'تطلب من أصحاب التقديرين الأعلى والأدنى مناقشة أسبابهم، ومن الفريق إعادة التقدير حتى يتم التوصل إلى توافق في الآراء أو تتضح الحاجة إلى مزيد من المعلومات.', 'Ask the high and low estimates to discuss their reasons, and the team to estimate again until a consensus is reached or more information is needed.', true),
  (0, 27, 0, 'نقل الميزة إلى تكرار آخر.', 'A shifting of the feature into another iteration.', false),
  (0, 27, 1, 'مهمة محددة بإطار زمني لاستكشاف مشكلة أو التحقيق فيها.', 'A time-boxed task to explore or investigate an issue.', true),
  (0, 27, 2, 'اجتماع قصير في بداية اليوم لمناقشة المهام قيد التنفيذ.', 'A short meeting at the beginning of the day to discuss tasks in progress.', false),
  (0, 27, 3, 'عرض توضيحي للميزة أمام مالك المنتج.', 'A demonstration of the feature to the product owner.', false),
  (0, 28, 0, 'خصّص نهج المشروع ليناسب المشروع والفريق.', 'Tailor the project approach to suit the project and the team.', false),
  (0, 28, 1, 'اضمن دعم الإدارة التنفيذية من خلال رفع التقارير بشكل متكرر إلى مديريك.', 'Ensure executive buy-in by reporting frequently to your managers.', false),
  (0, 28, 2, 'سلّم البرمجيات العاملة بشكل متكرر، خلال فترة تتراوح من بضعة أسابيع إلى بضعة أشهر، مع تفضيل الإطار الزمني الأقصر.', 'Deliver working software frequently, from a couple of weeks to a couple of months, with a preference to the shorter timescale.', true),
  (0, 28, 3, 'اضمن التخطيط الكامل لمنتجك وأصدره بعد اختباره بدقة.', 'Ensure complete planning for your product and release once tested thoroughly.', false),
  (0, 29, 0, 'ينبغي أن يملي أصحاب الأعمال على فريق التطوير ما يجب فعله وكيفية فعله.', 'Business people should dictate to the development team what to do and how to do it.', false),
  (0, 29, 1, 'يمكن للمطورين كتابة الشفرة البرمجية وإصدار المنتجات وفق جدول زمني يناسبهم، لتحقيق الاستقلالية الكاملة.', 'Developers can code and release products at a schedule that suits them, for complete autonomy.', false),
  (0, 29, 2, 'يجب ألا يعمل أصحاب الأعمال والمطورون معاً، لكن يمكنهم الدردشة حول عملهم أثناء الغداء.', 'Business people and developers mustn''t work together, but they can chat about their work over lunch.', false),
  (0, 29, 3, 'يجب أن يعمل أصحاب الأعمال والمطورون معاً يومياً طوال المشروع.', 'Business people and developers must work together daily throughout the project.', true),
  (0, 30, 0, 'ابنِ المشاريع حول فكرة محورية، ثم اعقد جلسات عصف ذهني بشكل متكرر لإنجاز العمل.', 'Build projects around a core idea, then brainstorm frequently to get the job done.', false),
  (0, 30, 1, 'اعثر على الدعم التنفيذي المناسب واضمن أن يخبروك بمتطلبات المنتج.', 'Find the right executive support and ensure they tell you the product requirements.', false),
  (0, 30, 2, 'سلّم بشكل متكرر سواء تم اختبار البند أم لا، لأن الجودة مسؤولية الجميع.', 'Deliver frequently whether an item has been tested or not, as quality is everyone’s responsibility.', false),
  (0, 30, 3, 'ابنِ المشاريع حول أفراد متحفزين. وامنحهم البيئة والدعم الذي يحتاجون إليه، وثق بهم لإنجاز العمل.', 'Build projects around motivated individuals. Give them the environment and support they need and trust them to get the job done.', true),
  (0, 31, 0, 'إن أكثر الطرق كفاءةً وفعاليةً لنقل المعلومات إلى فريق التطوير وداخله هي المحادثة وجهاً لوجه.', 'The most efficient and effective method of conveying information to and within a development team is face to face conversation.', true),
  (0, 31, 1, 'يتم الاتصال دائماً كتابةً لضمان وجود دليل دائم على حدوث الاتصال.', 'Communication is always done in writing to ensure you have ongoing proof the communication occurred.', false),
  (0, 31, 2, 'تضمن فرق أجايل الاتصال التنازلي فقط بحيث يوجّه المسؤول التنفيذي ميزات المنتج والعمل.', 'Agile teams ensure downward communication only so the executive in charge directs the product features and work.', false),
  (0, 31, 3, 'عند الاتصال، احرص على استخدام أشكال متنوعة مثل الهاتف والكتابة والمحادثة وجهاً لوجه، واضمن التنوع.', 'When communicating ensure to use various forms such as telephone, writing, face-to-face, and ensure variety.', false),
  (0, 32, 0, 'حضور اجتماعات النقابة هو أفضل مقياس لسعادة الفريق.', 'Union attendance is the best measure of team happiness.', false),
  (0, 32, 1, 'البرمجيات العاملة هي المقياس الأساسي للتقدم.', 'Working software is the primary measure of progress.', true),
  (0, 32, 2, 'اكتشاف المخاطر هو السبيل الوحيد لتجنب الفشل.', 'Finding risks is the only way to avoid failure.', false),
  (0, 32, 3, 'تعلّم أشياء جديدة يحافظ على اندماج الفريق.', 'Learning new things keeps a team engaged.', false),
  (0, 33, 0, 'تضمن أن يعقد الفريق اجتماع ما بعد انتهاء المشروع (Post-mortem) ويوثّق الدروس المستفادة في نهاية المشروع.', 'Ensure the team holds a project post-mortem and captures the lessons learned at the end of the project.', false),
  (0, 33, 1, 'تعقد اجتماعاً استعادياً مع الفريق بأكمله في نهاية كل تكرار وتدمج تلك الدروس المستفادة في كل تكرار جديد.', 'Hold a retrospective with the whole team at the end of each iteration and build those lessons learned into each new iteration.', true),
  (0, 33, 2, 'تطلب من مالك المنتج أن يبيّن للفريق أين يمكنه التحسن لتسليم الميزات التي يريدها.', 'Ask the product owner to show the team where they can improve to deliver the features they want.', false),
  (0, 33, 3, 'تتناوب المهام والأدوار بين أعضاء الفريق خلال كل تكرار جديد.', 'Rotate tasks and roles amongst the team during each new iteration.', false),
  (0, 34, 0, 'تعرض عليهم خطة إدارة المشروع، التي ستتضمن بيان النطاق مدرجاً في خط أساس النطاق.', 'Show them the project management plan, which will have the scope statement listed in the scope baseline.', false),
  (0, 34, 1, 'تطلب من الفريق إنشاء نموذج أولي عالي المستوى للمتطلبات، ثم مناقشته ومراجعته مع جميع أصحاب المصلحة.', 'Ask the team to create a high-level prototype of the requirements, then discuss and review with all stakeholders.', true),
  (0, 34, 2, 'تعرض عليهم الجدول الزمني للمشروع، الذي يحدد كل ميزة وتواريخ تسليمها.', 'Show them the project schedule, outlining each feature and their delivery dates.', false),
  (0, 34, 3, 'تعقد اجتماعاً استعادياً مع الفريق لجمع التغذية الراجعة والتحسين.', 'Hold a retrospective with the team to gather feedback and improve.', false),
  (0, 35, 0, 'وقت اختبار الشفرة البرمجية ووقت دمج الشفرة البرمجية.', 'Time for testing the code and time for merging the code.', false),
  (0, 35, 1, 'أوقات الاجتماعات وأوقات الغداء', 'Meeting times and lunch times', false),
  (0, 35, 2, 'الوقت المضيف للقيمة والوقت غير المضيف للقيمة', 'Value-added time and non-value added time', true),
  (0, 35, 3, 'الاختبار والتوثيق', 'Testing and documenting', false),
  (0, 36, 0, 'حتى لا يضطر فريق التطوير إلى إنشاء المنتج الحقيقي.', 'So the development team don’t have to create the real thing.', false),
  (0, 36, 1, 'حتى يتمكن الفريق من الاجتماع وعقد اجتماع آخر.', 'So the team can get together and have another meeting.', false),
  (0, 36, 2, 'تتيح للمستخدمين إنشاء النماذج الجديدة التي سيحتاجها النظام الجديد.', 'It allows users to create new forms that will be required for the new system.', false),
  (0, 36, 3, 'تتيح لمالك المنتج مناقشة المتطلبات والاتفاق عليها مع أصحاب المصلحة لديه.', 'It allows the product owner to discuss and agree on requirements with their stakeholders.', true),
  (0, 37, 0, 'يساعد الفريق على ترتيب أولويات ميزات المنتج للتكرار التالي.', 'It helps the team prioritise product features for the next iteration.', false),
  (0, 37, 1, 'يتيح للفريق إلقاء اللوم على الآخرين عندما تسوء الأمور.', 'It allows the team to blame others when things go wrong.', false),
  (0, 37, 2, 'إنه فرصة للفريق بأكمله للنظر في أسلوب عمله وتحسينه.', 'It’s an opportunity for the whole team to look at their way of work and improve.', true),
  (0, 37, 3, 'يعرض جزءاً من المنتج حتى يتمكن الجميع من رؤية ما تم تسليمه.', 'It showcases a part of the product so everyone can see what was delivered.', false),
  (0, 38, 0, 'لم يُكمل التكرار جميع بطاقات القصص في الوقت المخصص.', 'The iteration did not complete all the story cards in the allotted time.', false),
  (0, 38, 1, 'عثر فريق المشروع على خطأ برمجي في الشفرة قبل التسليم.', 'The project team found a bug in the code before delivery.', false),
  (0, 38, 2, 'لم يحقق إثبات المفهوم الخاص بذلك التكرار النتيجة المقصودة.', 'The proof-of-concept for that iteration did not have the intended outcome.', true),
  (0, 38, 3, 'لم يتم تنقيح قائمة أعمال المنتج المتراكمة في الوقت المناسب لبدء التكرار التالي.', 'The product backlog was not groomed in time to start the next iteration.', false),
  (0, 39, 0, 'تكرارية وتزايدية معاً، لتنقيح بنود العمل والتسليم بشكل متكرر.', 'Both iterative and incremental, to refine work items and deliver frequently.', true),
  (0, 39, 1, 'تكرارية وتنبؤية معاً، لتنقيح بنود العمل والتسليم دفعة واحدة.', 'Both iterative and predictive, to refine work items and deliver in one go.', false),
  (0, 39, 2, 'سريعة وجامحة معاً، مصممة لتحقيق أكبر عائد مقابل ما تدفعه.', 'Both fast and furious, designed to deliver the most bang for your buck.', false),
  (0, 39, 3, 'تنبؤية وتزايدية معاً، للتخطيط بعناية وتسليم ميزات أصغر.', 'Both predictive and incremental, to plan carefully and deliver smaller features.', false),
  (0, 40, 0, 'لا يحتاج إلى تغذية راجعة للعمل قيد التنفيذ من أجل تقليل ذلك العمل قيد التنفيذ.', 'It does not need feedback for work in progress to reduce that work in progress.', false),
  (0, 40, 1, 'يتيح التغذية الراجعة للعمل غير المكتمل من أجل تحسين ذلك العمل وتعديله.', 'It allows feedback for unfinished work to improve and modify that work.', true),
  (0, 40, 2, 'يركز على التسليم، لا على التغذية الراجعة.', 'It focuses on delivery, not feedback.', false),
  (0, 40, 3, 'يخطط المشروع مسبقاً ويسلّم دفعة واحدة.', 'It plans the project up front and delivers in one go.', false),
  (0, 41, 0, 'تحصي قصص المستخدم التي يريد مالك المنتج إكمالها بحلول نهاية التكرار.', 'Count up the user stories that the product owner wants completed by the end of the iteration.', false),
  (0, 41, 1, 'تقارن سرعة الفريق بعدد نقاط بطاقات القصص التي تريد إكمالها.', 'Check the team’s velocity against the number of points for the story cards you want to complete.', true),
  (0, 41, 2, 'تطلب من سكرم ماستر توزيع العمل على كل عضو في الفريق بأكثر الطرق إنصافاً.', 'Ask the Scrum Master to allocate work to each team member in the fairest manner possible.', false),
  (0, 41, 3, 'تنظر إلى الفرق الأخرى وما أنجزته في التكرار الأخير لتكوين أفضل تصور لفريقك.', 'Look at other teams and what they did in the last iteration to give the best idea for your team.', false),
  (0, 42, 0, 'متوسط سرعة الفريق عبر التكرارات السابقة هو أفضل مؤشر للتنبؤ بالتكرارات المستقبلية.', 'The team’s average velocity across previous iterations is the best predictor of future iterations.', true),
  (0, 42, 1, 'تضمن السرعة ألا يعمل الفريق أبداً بجهد يفوق ما هو مطلوب منه.', 'The velocity ensures the team will never work harder than they have to.', false),
  (0, 42, 2, 'سكرم ماستر له الكلمة الأخيرة بشأن سرعة الفريق لضمان إنجاز العمل.', 'The scrum master has the final say over team velocity to ensure the work gets done.', false),
  (0, 42, 3, 'يوضح مخطط السرعة مدى سرعة التقاط الفريق للبنود الجديدة.', 'The velocity chart shows how quickly new items are picked up by the team.', false),
  (0, 43, 0, 'تجزئة الميزات إلى قصص مستخدم.', 'Break down the features into user stories.', false),
  (0, 43, 1, 'كتابة معايير القبول لبطاقات القصص مع الفريق.', 'Write the story card acceptance criteria with the team.', false),
  (0, 43, 2, 'اختيار القصص التي سيعمل عليها الفريق في التكرار.', 'Choose which stories the team will work on in the iteration.', false),
  (0, 43, 3, 'العمل مع مالك المنتج لترتيب أولويات القصص ذات القيمة الأعلى للعمل عليها.', 'Work with the product owner to prioritises the highest value ones to work on.', true),
  (0, 44, 0, 'اجتماع انطلاق المشروع حيث يجب أن يقف أصحاب المصلحة ليكون الجميع متيقظين.', 'A project kick-off meeting where stakeholders must stand so everyone is alert.', false),
  (0, 44, 1, 'اجتماع لمتابعة تقدم المشروع ترى فيه كيف يصمد الجدول الزمني المقترح أمام الجدول الزمني الفعلي.', 'A project progress meeting where you see how proposed schedule stands up against the actual schedule.', false),
  (0, 44, 2, 'اجتماع سريع جداً محدد بإطار زمني لا يتجاوز 15 دقيقة، يذكر فيه أعضاء الفريق ما أنجزوه ويبلغون عن أي عوائق.', 'A very quick meeting time-boxed at 15 minutes or less, where the team say what they have accomplished and report any blockers.', true),
  (0, 44, 3, 'اجتماع تدريبي للفريق يركز على التحسين المستمر للفريق.', 'A team training meeting focused on continuous improvement of the team.', false),
  (0, 45, 0, 'تنتظر حتى وقت لاحق من المشروع، إذ قد تُحل المشكلة بفعل ميزات أخرى يتم إدخالها.', 'Wait until later in the project, as the problem may be fixed by other features going in.', false),
  (0, 45, 1, 'تطلب من المطورين إيجاد طريقة للمضي قدماً دون تلك الميزة.', 'Ask the developers to find a way to proceed without that feature.', false),
  (0, 45, 2, 'تخطط لسبايك حول الخطر، وتحدد حلاً، ثم ترتّب أولوية تلك الميزة لتُنفذ في وقت أبكر من التطوير.', 'Plan a spike around the risk, identify a solution then prioritise that feature earlier in development.', true),
  (0, 45, 3, 'تزيل جميع بطاقات القصص الأخرى من السبرنت الحالي حتى يتمكن الفريق من التكاتف حول المشكلة وحلها.', 'Remove all other story cards from the current sprint so the team can swarm around the issue and fix it.', false),
  (0, 46, 0, 'قائمة أعمال المنتج المتراكمة، حيث يدير مالك المنتج قائمة ذات أولويات لبنود المنتج المخطط لها تتطور من سبرنت إلى آخر.', 'Product Backlog, where the product owner manages a prioritized list of planned product items which evolves from sprint to sprint.', false),
  (0, 46, 1, 'قائمة أعمال السبرنت المتراكمة، وهي البنود المختارة في تخطيط السبرنت للسبرنت القادم.', 'Sprint Backlog, which are the items selected in Sprint Planning for the upcoming sprint.', false),
  (0, 46, 2, 'الزيادات (Increments) أو الميزات، وهي جميع بنود قائمة أعمال المنتج المتراكمة التي أُنجزت خلال السبرنت وتمثل خطوة نحو الرؤية الرئيسية.', 'Increments, or Features, which are all the Product Backlog items completed during a Sprint and a step toward the main vision.', false),
  (0, 46, 3, 'منطقة الفريق، وهي المكان الذي يجلس فيه الفريق المتواجد في مكان واحد لتحقيق تعاون سريع.', 'Team Area, which is where the co-located team sits for fast collaboration.', true),
  (0, 47, 0, 'تخطيط السبرنت، حيث يختار فريق سكرم البنود ذات الأولوية الأعلى.', 'Sprint Planning, where the Scrum team selects the highest priority items.', false),
  (0, 47, 1, 'سكرم اليومي، حيث يجتمع الفريق لاستعراض مهام المشروع، غالباً على لوحة كانبان.', 'Daily Scrum, where the team meets to walk through project tasks, often on a Kanban board.', false),
  (0, 47, 2, 'مراجعة السبرنت، حيث يقدم فريق التطوير عرضاً توضيحياً للمنتج إلى مالك المنتج لاعتماده أو تغييره.', 'Sprint Review, where the development team gives a demo on the product to the product owner for sign-off or change.', false),
  (0, 47, 3, 'مجلس مراقبة التغيير، حيث تُراجع جميع التغييرات المقترحة قبل إضافتها إلى قائمة الأعمال المتراكمة.', 'Change Control Board, where all proposed changes are reviewed before adding to the backlog.', true),
  (0, 48, 0, 'مالك المنتج، الذي يمثل العميل ويتحمل مسؤولية تعظيم قيمة المنتج.', 'Product Owner, representing the customer and responsible for maximising the value of the product.', false),
  (0, 48, 1, 'فريق التطوير، الذي يطوّر المنتج ويختبره، وهو متعدد الوظائف وذاتي التنظيم ويضم جميع الأدوار اللازمة لتسليم المنتج.', 'Development Team, developing and testing the product, cross functional, self-organising with all the roles needed to deliver the product.', false),
  (0, 48, 2, 'سكرم ماستر (Scrum Master)، الذي يضمن تطبيق عمليات سكرم مثل اجتماعات الوقوف والاجتماعات الاستعادية، ويوجّه الفريق ويزيل العوائق.', 'Scrum Master, ensuring the Scrum processes such as stand-ups and retrospectives, coaching the team and removing blockers.', false),
  (0, 48, 3, 'مدير المخاطر، الذي يرصد المخاطر ويراجعها ويضمن أن لكل منها مالكاً محدداً.', 'Risk Manager, capturing and reviewing risks and ensuring each one has an assigned owner.', true),
  (0, 49, 0, 'تعزيز الوعي الذاتي ومساعدة الأفراد على النمو.', 'Promoting self-awareness and helping people grow.', false),
  (0, 49, 1, 'الإنصات إلى الآخرين أكثر من التحدث بنفسك.', 'Listening to others more than speaking yourself.', false),
  (0, 49, 2, 'خدمة أعضاء الفريق من خلال إزالة العوائق.', 'Serving those on the team by removing blockers.', false),
  (0, 49, 3, 'الإبلاغ عن ذوي الأداء المنخفض لضمان بقاء الفريق مُحكماً.', 'Reporting on low-performers to ensure the team is streamlined.', true);
INSERT INTO new_choices (exam_no, question_index, position, text_ar, text_en, is_correct) VALUES
  (0, 50, 0, 'يواصل مالك المنتج إضافة نطاق إلى المشروع', 'The product owner keeps adding scope to the project', false),
  (0, 50, 1, 'الدين التقني يتراكم من الإصدارات السابقة', 'Technical debt is being built on from previous releases', true),
  (0, 50, 2, 'أعضاء الفريق لا يعملون كامل ساعاتهم المخصصة', 'Team members are not working their full allotted hours', false),
  (0, 50, 3, 'أعضاء الفريق يعملون بجهد مفرط ويعانون من الإرهاق', 'Team members are working too hard and being burnt out', false),
  (0, 51, 0, 'متوسط وقت إجازات الفريق، ومتوسط وقت حضور الفريق.', 'The average time for team leave, and the average time for team attendance.', false),
  (0, 51, 1, 'متوسط الوقت اللازم لإتمام اجتماعات الوقوف، ومتوسط الوقت اللازم لإتمام الاجتماعات الاستعادية.', 'The average time to complete stand-ups, and the average time to complete retrospectives.', false),
  (0, 51, 2, 'متوسط الوقت اللازم لإنجاز بطاقات القصص، ومتوسط الوقت اللازم لإنجاز الميزات.', 'The average time to complete story cards, and the average time to complete features.', true),
  (0, 51, 3, 'متوسط وقت توقف الفريق، ومتوسط الوقت اللازم لإتمام الإصدارات.', 'The average team downtime, and the average time to complete releases.', false),
  (0, 52, 0, 'أزال الفريق بعض الدين التقني.', 'The team removed some of the technical debt.', true),
  (0, 52, 1, 'لم يعد الفريق يختبر كل بطاقة لأنه أصبح يفهمها جيداً.', 'The team no longer tests each card because they already have a good understanding of it.', false),
  (0, 52, 2, 'قدّر الفريق بطاقات القصص بدقة أكبر.', 'The team estimated the story cards more accurately.', false),
  (0, 52, 3, 'أزال مالك المنتج بعض الميزات من قائمة الأعمال المتراكمة.', 'The product owner removed some features from the backlog of work.', false),
  (0, 53, 0, 'عدد العيوب التي اكتُشفت في ذلك التكرار.', 'How many defects were discovered in that iteration.', false),
  (0, 53, 1, 'الوقت الذي استغرقه إصلاح العيب منذ لحظة اكتشافه حتى لحظة إصلاحه.', 'How long it took to fix a defect from the time it was found to the time it was fixed.', true),
  (0, 53, 2, 'عدد الدورات اللازمة لرفع عيب إلى المطورين.', 'How many cycles it takes to raise a defect for the developers.', false),
  (0, 53, 3, 'عدد الميزات في قائمة الأعمال المتراكمة التي ظهرت فيها عيوب.', 'The number of features in the backlog that have experienced defects.', false),
  (0, 54, 0, 'ميزة لم تكتمل بحلول نهاية التكرار.', 'A feature that was not completed by the end of the iteration.', false),
  (0, 54, 1, 'شيفرة تحتاج إلى إعادة هيكلة قبل أن يبدأ التكرار التالي.', 'Code that needs to be refactored before the next iteration can begin.', false),
  (0, 54, 2, 'عيوب تجاوزت مرحلة الاختبار وضمان الجودة.', 'Defects that have made it through testing and quality assurance.', true),
  (0, 54, 3, 'أعضاء الفريق الذين لم يحضروا اجتماع الوقوف اليومي في هذا التكرار.', 'Team members who did not attend the daily stand-up this iteration.', false),
  (0, 55, 0, 'الغاية، الأفراد، العملية.', 'Purpose, People, Process.', true),
  (0, 55, 1, 'الأفراد، الأنظمة، التكنولوجيا.', 'People, Systems, Technology.', false),
  (0, 55, 2, 'المعلومات، التقارير، العملية.', 'Information, Reporting, Process.', false),
  (0, 55, 3, 'المصنع، الأفراد، الآلة.', 'Plant, People, Machine.', false),
  (0, 56, 0, 'التوجيه (Coaching) بدلاً من التحكم.', 'Coaching versus controlling.', false),
  (0, 56, 1, 'تعزيز الأمان والاحترام والثقة.', 'Promoting safety, respect, and trust.', false),
  (0, 56, 2, 'تعزيز طاقة الآخرين وذكائهم.', 'Promoting the energy and intelligence of others.', false),
  (0, 56, 3, 'ضمان أن يفعل الفريق ما تقوله.', 'Ensuring the team does what you say.', true),
  (0, 57, 0, 'أولويتنا القصوى هي إرضاء العميل من خلال التسليم المبكر والمستمر للبرمجيات ذات القيمة.', 'Our highest priority is to satisfy the customer through early and continuous delivery of valuable software.', true),
  (0, 57, 1, 'أولويتنا القصوى هي ضمان دعم الإدارة التنفيذية من خلال تسليم البنود عالية القيمة.', 'Our highest priority is to ensure executive buy-in by delivering high value items.', false),
  (0, 57, 2, 'أولويتنا القصوى هي الحد من أثر التغيير من خلال إبقاء المعلومات عند الحد الأدنى.', 'Our highest priority is to reduce the impact of change by keeping information to a minimum.', false),
  (0, 57, 3, 'أولويتنا القصوى هي التخطيط بدقة والتنفيذ بانضباط.', 'Our highest priority is to plan thoroughly and execute with discipline.', false),
  (0, 58, 0, 'يمثل مالك المنتج العميل، ويُنشئ قائمة أعمال المنتج المتراكمة ويحافظ عليها ويحدد أولوياتها لضمان أعلى قيمة تجارية دون إحداث هدر.', 'The Product Owner represents the customer and generates, maintains, and prioritizes the product backlog to ensure the highest business value without creating waste.', false),
  (0, 58, 1, 'يجب أن يمتلك مالك المنتج خبرة سابقة في أجايل للعمل ضمن الفريق.', 'The Product Owner must have previous experience in Agile to work in the team.', true),
  (0, 58, 2, 'قد يعمل مالك المنتج مع أصحاب المصلحة والعملاء والفرق لتحديد اتجاه المنتج، وترتيب العمل بناءً على قيمته التجارية.', 'The Product Owner may work with stakeholders, customers, and the teams to define the product direction, and rank the work based on its business value.', false),
  (0, 58, 3, 'عادةً ما يكون لمالكي المنتج خلفية في الأعمال ويقدمون خبرة عميقة في مجال التخصص لدعم القرارات.', 'Product owners typically have a business background and bring deep subject matter expertise to the decisions.', false),
  (0, 59, 0, 'المشكلات الناشئة عن العمليات الاعتيادية، والمشكلات الناشئة عن حالة فريدة أو جديدة.', 'Issues that arose from normal operations, and issues that arose from a unique or new condition.', true),
  (0, 59, 1, 'المشكلات الناجمة عن المنطقة المشتركة، والمشكلات الناجمة عن البرمجيات الخاصة.', 'Issues caused by the common area, and issues caused by the special software.', false),
  (0, 59, 2, 'المشكلات التي وُجدت في الإصدار السابق، والمشكلات التي وُجدت في هذا الإصدار.', 'Issues found in the last release, and issues found in this release.', false),
  (0, 59, 3, 'المشكلات الناجمة عن التكامل المستمر، والمشكلات الناجمة عن غياب التكامل.', 'Issues caused by continuous integration, and issues caused by no integration.', false),
  (0, 60, 0, 'دفع الفريق لإنجاز خمس نقاط إضافية فوق الحد الأقصى، وترحيل أي بطاقات غير مكتملة إلى التكرار التالي.', 'Push the team to complete five more than the maximum, and roll over any incomplete cards to the next iteration.', false),
  (0, 60, 1, 'تحديد 35 كحد للعمل قيد التنفيذ (WIP)، وتعديله خلال التكرارات المستقبلية إذا تمكن الفريق من سحب عمل أكثر مما خُصص له.', 'Set 35 as the Work in Progress (WIP) limit, and adjust it during future iterations if the team is able to pull more work than assigned.', true),
  (0, 60, 2, 'إضافة مزيد من الأفراد إلى الفريق لإنجاز العمل، لأن 35 ليست كافية.', 'Add more people to the team to complete the work, because 35 is not enough.', false),
  (0, 60, 3, 'تقليل عدد الميزات في قائمة أعمال المنتج المتراكمة لتتناسب مع سرعة الفريق.', 'Reduce the number of features in the product backlog to suit the team velocity.', false),
  (0, 61, 0, 'تدوين آثار المخاطر بالدولار مقابل العائد بالدولار، ثم إعادة ترتيب أولويات قائمة الأعمال المتراكمة.', 'Note the risk impacts in dollars against the return in dollars, then reprioritise the backlog.', false),
  (0, 61, 1, 'تعديل قائمة الأعمال المتراكمة للتركيز على أكبر الميزات أولاً.', 'Adjust the backlog to focus on the largest features first.', false),
  (0, 61, 2, 'إضافة بطاقات قصص المستخدم للاستجابات للمخاطر إلى قائمة الأعمال المتراكمة، ثم ترتيب أولويات القائمة بحيث تأتي الميزات الأعلى قيمة والاستجابات الأعلى تكلفة أولاً.', 'Add User Story cards for risk responses to the backlog, then prioritize the backlog with the highest value features and highest cost responses first.', true),
  (0, 61, 3, 'إنشاء سجل مخاطر للمشروع، ثم اعتماده من مالكي المخاطر.', 'Create a risk register for the project, then have it signed off by the risk owners.', false),
  (0, 62, 0, 'تغيير المتطلبات لإزالة الخطر.', 'Change the requirements to remove the risk.', false),
  (0, 62, 1, 'جدولتها في وقت لاحق من المشروع حتى تتمكن من تسليم أقصى قيمة أولاً.', 'Schedule them later in the project so you can deliver maximum value first.', false),
  (0, 62, 2, 'جدولتها في وقت مبكر من المشروع لتقليل أثر الخطر بمرور الوقت.', 'Schedule them earlier in the project to reduce the risk impact over time.', true),
  (0, 62, 3, 'وضع جميع البنود عالية المخاطر في "تكرار مخاطر" يكون التركيز فيه على تقليل المخاطر.', 'Place all the high-risk items in a “risk iteration” where the focus is on reducing risk.', false),
  (0, 63, 0, 'الاجتماعات الاستعادية (Retrospectives)', 'Retrospectives', false),
  (0, 63, 1, 'كتابة قصص المستخدم', 'Writing user stories', true),
  (0, 63, 2, 'العروض التوضيحية للتكرار ومراجعاته', 'Iteration demonstrations and reviews', false),
  (0, 63, 3, 'إثارة العوائق في اجتماع الوقوف اليومي', 'Raising blockers in the daily-stand-up', false),
  (0, 64, 0, 'يمكن أن يُسمى ميسّر الفريق، أو القائد الخادم، مدير مشروع أو سكرم ماستر أو قائد فريق المشروع أو مدرّب الفريق أو مدير محفظة.', 'The Team Facilitator, or servant leader, can be called a project manager, scrum master, project team lead, team coach, or a portfolio manager.', false),
  (0, 64, 1, 'يجب أن يحمل ميسّر الفريق شهادة جامعية في الأعمال ليحظى بالاحترام الكافي.', 'The Team Facilitator must have a degree in business to be sufficiently respected.', true),
  (0, 64, 2, 'تحتاج جميع فرق أجايل إلى القيادة الخادمة ضمن الفريق.', 'All Agile teams need servant leadership on the team.', false),
  (0, 64, 3, 'ينبغي لأعضاء الفريق تنمية مهارات القيادة الخادمة الخاصة بهم في التيسير والتوجيه (Coaching) وإزالة العوائق.', 'Team members should build up their own servant leadership skills of facilitation, coaching, and removing blockers.', false),
  (0, 65, 0, 'متخصصون معمّمون (Generalizing Specialists)، لديهم تخصص واحد محوري ونطاق واسع من الخبرة في مهارات أخرى.', 'Generalising specialists, with one focus speciality and a wide range of experience in other skills.', true),
  (0, 65, 1, 'قادة فرق، متخصصون في القيادة حتى يتمكن الجميع من القيادة في فريق أجايل.', 'Team leaders, with a speciality in leadership so everyone can lead in the Agile team.', false),
  (0, 65, 2, 'متخصصون في المخاطر، لأن المخاطر أعلى في تسليم فرق أجايل.', 'Risk specialists, because there is a higher risk in Agile team delivery.', false),
  (0, 65, 3, 'لا تضف أعضاء إلى الفريق، بل ينبغي تقليص حجم الفريق وفقاً لمبادئ البرمجة القصوى (XP).', 'Don’t add team members – you should shrink the team in accordance with the XP principles.', false),
  (0, 66, 0, 'يعني نهج الفريق الكامل إشراك كل من يمتلك المعرفة والمهارات اللازمة لضمان نجاح المشروع.', 'The whole-team approach means involving everyone with the knowledge and skills necessary to ensure project success.', false),
  (0, 66, 1, 'ينبغي أن يكون الفريق صغيراً نسبياً (لوحظت فرق ناجحة تضم ما لا يقل عن ثلاثة أفراد وما لا يزيد عن تسعة).', 'The team should be relatively small (successful teams have been observed with as few as three people and as many as nine).', false),
  (0, 66, 2, 'غالباً ما تكون الفرق متفرغة بنسبة 100% للتسليم، لأن الأفراد عند التبديل بين المهام أو تعدد المهام يرتكبون أخطاء أكثر ويفقدون ما بين 20% و40% من إنتاجيتهم.', 'Teams are often 100% dedicated to the delivery, because when switching or multitasking people make more mistakes and experience between 20% and 40% loss of productivity.', false),
  (0, 66, 3, 'ينبغي ألا يكون أعضاء الفريق متعددي المهارات لأن ذلك قد يشتت وضوح الدور.', 'Teams should not be multi-skilled as this can distract from the clarity of the role.', true),
  (0, 67, 0, 'تتكون الفرق متعددة الوظائف من أعضاء يمتلكون جميع المهارات اللازمة لإنتاج منتج عامل.', 'Cross functional teams consist of team members with all the skills necessary to produce a working product.', false),
  (0, 67, 1, 'لا تحتاج الفرق إلى استخدام الإدارة المرئية لأنها بارعة أصلاً فيما تقوم به.', 'Teams do not need to use visual management because they are already good at what they do.', true),
  (0, 67, 2, 'في تطوير البرمجيات، تتألف الفرق متعددة الوظائف من المصممين والمطورين والمختبرين وأي أدوار أخرى مطلوبة.', 'In software development, cross functional teams are comprised of designers, developers, testers, and any other required roles.', false),
  (0, 67, 3, 'أعضاء الفريق متعدد الوظائف ذوو أهمية بالغة لأنهم يستطيعون تسليم عمل منجز في أقصر وقت ممكن، وبجودة أعلى، ودون اعتماديات خارجية.', 'Cross Functional team members are critical because they can deliver finished work in the shortest possible time, with higher quality, without external dependencies.', false),
  (0, 68, 0, 'مُنشئ الفريق', 'the Team Creator', false),
  (0, 68, 1, 'ميسّر الفريق', 'the Team Facilitator', true),
  (0, 68, 2, 'مُشغّل الفريق', 'the Team Runner', false),
  (0, 68, 3, 'مُمكِّن الفريق', 'the Team Enabler', false),
  (0, 69, 0, 'إثارة العائق في اجتماع الوقوف اليومي التالي (أو قبله) حتى يتكاتف الفريق حول المشكلة ويحلها بسرعة.', 'Raise a blocker at the next daily stand-up (or before) so the team can swarm around the problem and solve it quickly.', true),
  (0, 69, 1, 'نقل هذا الجزء من العمل إلى داخل الفريق حتى لا تضطر إلى القلق بعد الآن.', 'Bring the piece of work in-house so you don’t have to worry anymore.', false),
  (0, 69, 2, 'الطلب من مالك المنتج إزالة تلك الميزة في الوقت الحالي، ويمكنكم العودة إليها لاحقاً.', 'Ask the product owner to remove that feature for now, you can revisit it later.', false),
  (0, 69, 3, 'إضافة تكلفة إلى الميزانية وإيجاد طرف ثالث لإنجاز العمل.', 'Add cost to the budget and find a third party to complete the work.', false),
  (0, 70, 0, 'لكي يعرف قائد فريق أجايل مَن يلوم عندما تسوء الأمور.', 'So the Agile team lead knows who to blame when things go wrong.', false),
  (0, 70, 1, 'لكي يتمكن الفريق من إحصاء العيوب والأخطاء بدقة.', 'So the team can accurately count the defects and mistakes.', false),
  (0, 70, 2, 'لكي يشعر الفريق بحرية طلب المساعدة، والاعتراف بالمشكلات أو الإخفاقات، والتحسّن.', 'So the team feels free to ask for help, admit to problems or failures and improve.', true),
  (0, 70, 3, 'لكي يتمكن الفريق بأكمله من تمرير العمل إلى بعضهم بعضاً إذا علموا أن لديهم وقتاً متاحاً.', 'So the entire team can push work on to each other if they know they have time.', false),
  (0, 71, 0, 'عقد اجتماع مجموعة عمل أسبوعي مرة واحدة مع أصحاب المصلحة في المشروع', 'Having a once-weekly working group meting with project stakeholders', false),
  (0, 71, 1, 'إجراء مراجعات السبرنت أو العروض التوضيحية التي تشمل جميع أصحاب المصلحة.', 'Conducting sprint reviews or demonstrations that include all stakeholders.', true),
  (0, 71, 2, 'إرسال تقارير المشروع إلى أصحاب المصلحة في المشروع للاطلاع عليها.', 'Sending out project reports to project stakeholders to view.', false),
  (0, 71, 3, 'طلب التغذية الراجعة من أصحاب المصلحة فقط عندما يكون التطوير متوقفاً بسبب عائق.', 'Asking stakeholders for feedback only development is blocked.', false),
  (0, 72, 0, 'تعرض عليهم مخطط سرعة الفريق والنقاط المخصصة للبطاقات في قائمة الأعمال المتراكمة، وتطلب منهم ترتيب أولويات الميزات في تخطيط السبرنت القادم.', 'Show them the team velocity chart and the points allotted to cards in the backlog, and ask them to prioritise the features at the next sprint planning.', true),
  (0, 72, 1, 'تضيف المزيد من الأعضاء إلى الفريق حتى تتمكن من إنجاز العمل الذي يريدونه.', 'Add more members to the team so you can get the work they want done.', false),
  (0, 72, 2, 'تطلب ممثلاً آخر لجهة الأعمال يفهم التقنية بشكل أفضل.', 'Ask for another business representative who understands technology better.', false),
  (0, 72, 3, 'تحذف بعض الميزات بنفسك وترى ما إذا كان أحد سيلاحظ ذلك.', 'Remove some of the features yourself and see if anyone notices.', false),
  (0, 73, 0, 'القيادة الخادمة (Servant Leadership).', 'Servant Leadership.', false),
  (0, 73, 1, 'تخطيط السبرنت (Sprint Planning).', 'Sprint planning.', false),
  (0, 73, 2, 'اجتماع الوقوف اليومي (Daily Stand-up).', 'The daily stand-up.', false),
  (0, 73, 3, 'نهج الفريق الكامل (Whole Team Approach).', 'The whole team approach.', true),
  (0, 74, 0, 'تعمل مع مختلف مديري أعضاء الفريق الذين تحتاج إليهم وتجعلهم يخصصون الأفراد اللازمين للفريق متعدد الوظائف.', 'Work with the various managers of team members you need and have them dedicate the necessary individuals to the cross-functional team.', true),
  (0, 74, 1, 'ترفع طلب تغيير لمراجعته من قِبل مجلس مراقبة التغيير في المشروع نظراً لأن العمل سيتأخر.', 'Raise a change request for review by the project Change Control Board as the work will be delayed.', false),
  (0, 74, 2, 'تسجّل مشكلة في سجل المشكلات لمراجعتها وإدارتها من قِبل فريق المشروع.', 'Raise an issue in the issue log for review and management by the project team.', false),
  (0, 74, 3, 'تعمل مع فريق المخاطر لتسجيل خطر على المشروع، وتعيّن له مالكاً، وتضع ضوابط لتلك المخاطر.', 'Work with the risk team to raise a project risk, assign it to an owner and create controls for those risks.', false),
  (0, 75, 0, 'لا يستخدم أجايل العمليات، لأنه يفضّل الأفراد والتفاعلات على العمليات والأدوات.', 'Agile does not use processes, as it prefers individuals and interactions over processes and tools.', false),
  (0, 75, 1, 'تُشرك عمليات أجايل الفريق وتدعمه من خلال ضمان حصول الرعاة والمطورين والمستخدمين جميعاً على ما يريدون.', 'Agile processes engage and support the team by ensuring sponsors, developers and users all get what they want.', false),
  (0, 75, 2, 'تعزز عمليات أجايل التطوير المستدام. وينبغي أن يكون الرعاة والمطورون والمستخدمون قادرين على الحفاظ على وتيرة ثابتة إلى أجل غير مسمى.', 'Agile processes promote sustainable development. The sponsors, developers, and users should be able to maintain a constant pace indefinitely.', true),
  (0, 75, 3, 'تساعد عمليات أجايل على إنجاز أكبر قدر ممكن من العمل. وعندما يظن الفريق أنه لا يستطيع المضي أبعد من ذلك، يدفعه أجايل إلى بذل جهد إضافي.', 'Agile processes help as much work get done as possible. When the team thinks they can’t go any further, Agile pushes them to go the extra mile.', false),
  (0, 76, 0, 'يضمن التدفق المستمر إنجاز العمل بوتيرة معقولة واكتشاف العيوب.', 'Continuous flow ensures work is done at a reasonable pace and defects are caught.', false),
  (0, 76, 1, 'يُجرى الاختبار على جميع المستويات، من اختبار الوحدات إلى الاختبار الشامل من البداية إلى النهاية.', 'Testing is done at all levels, from unit testing to end to end testing.', false),
  (0, 76, 2, 'الاهتمام المستمر بالتميز التقني والتصميم الجيد يعزز الجودة.', 'Continuous attention to technical excellence and good design enhances quality.', true),
  (0, 76, 3, 'الجودة مسؤولية الجميع في فريق أجايل، مما يعني أن الجميع سيختبرون المنتج.', 'Quality is everyone’s responsibility in an Agile team, meaning everyone will test the product.', false),
  (0, 77, 0, 'البساطة ممكنة فقط عندما يفهم الفريق أولاً مدى تعقيد النظام.', 'Simplicity is only possible when the team first understands how complex the system is.', false),
  (0, 77, 1, 'البساطة جزء من كل مشروع، فالجميع يبسّطون العمل بشكل طبيعي كجزء من دورهم.', 'Simplicity is part of every project, everyone naturally simplifies the work as part of their role.', false),
  (0, 77, 2, 'البساطة تقلل التكلفة في المشروع، مما يضمن أن المديرين التنفيذيين يبسّطون العملية والنظام دائماً.', 'Simplicity reduces cost in a project, ensuring executives are always simplifying the process and the system.', false),
  (0, 77, 3, 'البساطة – فن تعظيم كمية العمل غير المنجَز – أمر أساسي.', 'Simplicity – the art of maximising the amount of work not done – is essential.', true),
  (0, 78, 0, 'السؤال عن مَن وماذا وأين ومتى للعثور على سبب المشكلة.', 'To ask who, what, where and when to find the cause of the problem.', false),
  (0, 78, 1, 'السؤال عن سبب حدوث المشكلة، ثم السؤال "لماذا" عن كل سبب بعد ذلك، حتى يتم العثور على السبب الجذري.', 'To ask why the issue happened, then why for each reason after that, until the cause is found.', true),
  (0, 78, 2, 'السؤال عن سبب عمل الفريق على كل ميزة، لمنح الفريق هدفاً.', 'To ask why the team is working on each feature, to give the team purpose.', false),
  (0, 78, 3, 'تخصيص خمسة أسباب لكل بطاقة قصة لضمان معرفة الفريق بسبب العمل عليها.', 'To allocate five whys to each story card to ensure the team knows the reason for working on in.', false),
  (0, 79, 0, 'عدد مرات اجتماع الفريق خلال الأسبوع.', 'How often the team meets during the week.', false),
  (0, 79, 1, 'عدد بطاقات القصص التي أكملها الفريق خلال هذا التكرار.', 'How many story cards the team have completed during this iteration.', false),
  (0, 79, 2, 'مقدار المكافأة السنوية التي ينبغي أن يحصل عليها الفريق.', 'How much yearly bonus the team should receive.', false),
  (0, 79, 3, 'كيف يؤدي الفريق عمله ويسلّم معاً.', 'How the team performs and delivers together.', true),
  (0, 80, 0, 'تعرض خطة إدارة المخاطر من خطة إدارة المشروع الخاصة بك على ممثل جهة الأعمال.', 'Show the risk management plan from your project management plan to the business rep.', false),
  (0, 80, 1, 'تسأل فريق التطوير عما إذا كانوا يحبون الميزة.', 'Ask the development team if they like the feature.', false),
  (0, 80, 2, 'تعقد جلسة تشريح مسبق (Pre-mortem)، حيث يكتب كل عضو في الفريق الأسباب التي يعتقد أنها قد تؤدي إلى فشل المهمة أو الميزة حتى يمكن مناقشتها.', 'Hold a pre-mortem, where each team member writes reasons they think the task or feature might fail so these can be discussed.', true),
  (0, 80, 3, 'تتحقق من إحساسك الداخلي تجاه الميزة، وإذا لم يكن الأمر يبدو صحيحاً فتبحث فيه بعمق أكبر.', 'Check your gut-feel for the feature, and if it doesn’t feel right look into it more deeply.', false),
  (0, 81, 0, 'تُجري تحليل عظم السمكة (Fishbone Analysis)', 'Perform fishbone analysis', true),
  (0, 81, 1, 'تُجري تحليل كانو (Kano Analysis)', 'Perform Kano analysis', false),
  (0, 81, 2, 'تُجري تحليل الانحدار (Regression Analysis)', 'Perform regression analysis', false),
  (0, 81, 3, 'تُجري تحليل مخطط التباين المتعدد (Multi-vari Chart Analysis)', 'Perform multi-vari chart analysis', false),
  (0, 82, 0, 'سيجتمع الفريق يومياً لبناء شبكة داعمة من العاملين.', 'The team will meet daily to build a supportive network of workers.', false),
  (0, 82, 1, 'على فترات منتظمة، يتأمل الفريق في كيفية أن يصبح أكثر فعالية، ثم يضبط سلوكه ويعدّله وفقاً لذلك.', 'At regular intervals, the team reflects on how to become more effective, then tunes and adjusts its behaviour accordingly.', true),
  (0, 82, 2, 'تُحسَّن الميزات بانتظام من خلال إعادة هيكلة الشفرة البرمجية.', 'Features are regularly improved through refactoring of the code.', false),
  (0, 82, 3, 'يبدّل راعي المشروع أدوار أعضاء الفريق بانتظام للحفاظ على تعلّم الجميع ونموهم.', 'The project sponsor regularly swaps team member roles to keep everyone learning and growing.', false),
  (0, 83, 0, 'أولويتنا القصوى هي إرضاء العميل من خلال التسليم المبكر والمستمر للبرمجيات القيّمة.', 'Our highest priority is to satisfy the customer through early and continuous delivery of valuable software.', false),
  (0, 83, 1, 'ضمان الالتزام بالجداول الزمنية للتسليم بأي ثمن.', 'Ensure delivery timelines are met at all costs.', true),
  (0, 83, 2, 'الترحيب بالمتطلبات المتغيرة، حتى في مرحلة متأخرة من التطوير. فعمليات أجايل تسخّر التغيير لصالح الميزة التنافسية للعميل.', 'Welcome changing requirements, even late in development. Agile processes harness change for the customer’s competitive advantage.', false),
  (0, 83, 3, 'تسليم البرمجيات العاملة بشكل متكرر، خلال فترة تتراوح من بضعة أسابيع إلى بضعة أشهر، مع تفضيل الإطار الزمني الأقصر.', 'Deliver working software frequently, from a couple of weeks to a couple of months, with a preference to the shorter timescale.', false),
  (0, 84, 0, 'إنشاء البطاقة (Card)، وهي الوسيط المادي (أو البرمجي) الذي يصف قصة المستخدم.', 'Create the card, which is the physical (or software driven) media describing a user story.', true),
  (0, 84, 1, 'تأكيد (Confirmation) معايير القبول التي ستُدرج في قصة المستخدم.', 'Confirm the acceptance criteria to go into the user story.', false),
  (0, 84, 2, 'إجراء محادثة (Conversation) مع الفريق لتفصيل المتطلبات والمعايير.', 'Have a Conversation with the team to flesh out the requirements and criteria.', false),
  (0, 84, 3, 'اكتشاف العيوب قبل تطويرها من خلال العمل مع مختبري الجودة قبل التطوير وبعده.', 'Catch defects before they are developed by working with Quality testers before and after.', false),
  (0, 85, 0, 'المخاطر الرئيسية للمشروع وللميزة التي يتم تسليمها، مع مالكيها وإجراءات التخفيف الخاصة بها.', 'Key risks of the project and the feature being delivered, with their owners and mitigations.', false),
  (0, 85, 1, 'إطار هيكلي (Wireframe) للميزة المراد تطويرها يمكن للمطورين العمل به.', 'A wireframe of the feature to be developed that developers can work with.', false),
  (0, 85, 2, 'المتطلب، ودرجة أهميته الحرجة، والمدة المتوقعة للتطوير والاختبار، ومعايير القبول لتلك القصة.', 'The requirement, its criticality, expected development and test duration, and the acceptance criteria for that story.', true),
  (0, 85, 3, 'فائدة الميزة حتى يكون أصحاب المصلحة الرئيسيون على علم بما سيحصلون عليه.', 'The benefit of the feature so key stakeholders are aware of what they will get.', false),
  (0, 86, 0, 'تضع البطاقة على لوحة كانبان حتى يتمكن الفريق من رؤية العمل المستقبلي بوضوح.', 'Place the card on the Kanban board so the team can clearly see the future work.', false),
  (0, 86, 1, 'تُجري محادثة مع المطورين حول كيفية استخدام البرمجيات، وتؤكد معايير القبول وتعريف الإنجاز.', 'Have a conversation with developers about how the software will be used, confirm the acceptance criteria and definition of done.', true),
  (0, 86, 2, 'ترتّب أولوية البطاقة في قائمة أعمال السبرنت القادم المتراكمة لضمان إنجاز العمل.', 'Prioritise the card in the upcoming sprint backlog to ensure the work gets done.', false),
  (0, 86, 3, 'تُبلغ راعي المشروع ومدير المخاطر بتفاصيل الميزة لضمان تسجيل المخاطر.', 'Advise the project sponsor and risk manager of the feature details to ensure risks are captured.', false),
  (0, 87, 0, 'التركيز على تعريف النجاح كما يحدده مدير المشروع', 'Focus on the definition of success as defined by the project manager', false),
  (0, 87, 1, 'التركيز بشكل أساسي على الأفراد والتفاعلات المعنية', 'Focus primarily on the individuals and interactions involved', true),
  (0, 87, 2, 'التركيز بشكل أساسي على نطاق المشروع', 'Focus primarily on the scope of the project', false),
  (0, 87, 3, 'التركيز بشكل أساسي على الأشخاص المشاركين في المشروع', 'Focus primarily on the people involved in the project', false),
  (0, 88, 0, 'اختيار شخص من كل جزء من المنظمة للمساعدة، لضمان التنوع.', 'Select a person from each part of the organisation to assist, to ensure diversity.', false),
  (0, 88, 1, 'جعل المدير الوظيفي يختار أصدقاءه أو أعضاء الفريق المفضلين لديه.', 'Have the functional manager select their friends or favourite team members.', false),
  (0, 88, 2, 'تشجيع تشكيل فريق ذاتي التنظيم، يضم الأشخاص الذين طلبوا المتطلبات والنتائج في المقام الأول.', 'Encourage a self-organizing team to form, including the people who asked for the requirements and outcomes in the first place.', true),
  (0, 88, 3, 'توظيف استشاريين خارجيين لإدارة المشروع وإنشاء المنتج.', 'Hire external consultants to run the project and create the product.', false),
  (0, 89, 0, 'تتفاوض على نطاق المشروع وتكاليفه مع راعي المشروع.', 'Negotiate the scope and costs of the project with the project sponsor.', false),
  (0, 89, 1, 'تستعرض مع الفريق ثلاثة أسئلة: ماذا فعلتُ بالأمس؟ ماذا سأفعل اليوم؟ هل هناك ما يعيقني؟', 'Walk through three questions with the team—What did I do yesterday? What will I do today? Is anything blocking me?', false),
  (0, 89, 2, 'يعرض فريق التطوير الميزة العاملة على مالك المنتج، الذي يحددها على أنها مكتملة.', 'The development team demonstrates the working feature to the product owner, who marks it as complete.', false),
  (0, 89, 3, 'يشارك مالك المنتج قائمة الأعمال المتراكمة المحدّثة، ويناقشها الفريق لضمان فهم مشترك.', 'The product owner shares the updated backlog, and the team discusses it to ensure a shared understanding.', true),
  (0, 90, 0, 'اجتماعات الوقوف اليومية', 'Daily stand-ups', false),
  (0, 90, 1, 'الميزات غير الضرورية', 'Unnecessary features', true),
  (0, 90, 2, 'مراجعات السبرنت', 'Sprint reviews', false),
  (0, 90, 3, 'الاختبار', 'Testing', false),
  (0, 91, 0, 'عقد الاجتماع الاستعادي للسبرنت مع الفريق', 'Hold a sprint retrospective with the team', true),
  (0, 91, 1, 'إجراء تنقيح قائمة أعمال المنتج المتراكمة مع مالك المنتج', 'Perform product backlog refinement with the product owner', false),
  (0, 91, 2, 'إجراء تفصيل بطاقات القصص مع الأصدقاء الثلاثة (Three Amigos) (الأعمال، التطوير، الاختبار)', 'Perform story card elaboration with the three amigos (Business, Development, Testing)', false),
  (0, 91, 3, 'عقد سكرم يومي', 'Hold a Daily Scrum', false),
  (0, 92, 0, 'متى سينتهي المشروع؟ ماذا نفعل بالمنتج؟', 'When will the project end? What do we do with the product?', false),
  (0, 92, 1, 'ماذا يعني "الإنجاز" بالنسبة للمشروع؟ كيف سنعمل معاً؟', 'What does “done” mean for the project? How are we going to work together?', true),
  (0, 92, 2, 'ما مقدار المخاطر في المشروع؟ ما نطاق المشروع؟', 'How much risk is on the project? What is the project scope?', false),
  (0, 92, 3, 'كم عدد العيوب المسموح بها في المنتج؟ كم عدد المختبرين؟', 'How many defects are allowed in the product? How many testers are there?', false),
  (0, 93, 0, 'إدارة القيمة المكتسبة ومؤشر أداء الجدول الزمني', 'Earned value management and the schedule performance index', false),
  (0, 93, 1, 'تحليل التباين والتقدير حتى الإكمال', 'Variance Analysis and the Estimate to Complete', false),
  (0, 93, 2, 'مخطط الإنجاز التنازلي للميزات (الميزات المسلَّمة) ورضا العميل', 'Feature burndown chart (features delivered) and customer satisfaction', true),
  (0, 93, 3, 'التباين عند الإكمال ومؤشر أداء التكلفة', 'Variance at Completion and the cost performance index', false),
  (0, 94, 0, 'خطة إدارة المشروع، ميثاق المشروع', 'Project Management Plan, Project Charter', false),
  (0, 94, 1, 'إطار أجايل الموسّع (SAFe)، سكرم واسع النطاق (LeSS)', 'Scaled Agile Framework, Large Scale Scrum', true),
  (0, 94, 2, 'اجتماعات مجموعات العمل، مراجعات ما بعد انتهاء المشروع', 'Working Group Meetings, Project Post Mortems', false),
  (0, 94, 3, 'مخططات التدفق، مخططات التقارب', 'Flow Charting, Affinity Diagrams', false),
  (0, 95, 0, 'تقدير بنود العمل وتنقيحها', 'Estimate and refine the work items', true),
  (0, 95, 1, 'ترتيب أولويات بنود العمل', 'Prioritize the work items', false),
  (0, 95, 2, 'إضافة ميزات إلى قائمة أعمال المشروع المتراكمة', 'Add features to the project backlog', false),
  (0, 95, 3, 'تحديد الإصلاحات', 'Identify fixes', false),
  (0, 96, 0, 'تخطط فرق كانبان عملها في سبرنتات أو تكرارات.', 'Kanban teams plan their work in sprints or iterations.', false),
  (0, 96, 1, 'لا توجد حدود للعمل قيد التنفيذ (WIP) في كانبان.', 'There are no WIP limits in Kanban.', false),
  (0, 96, 2, 'تعمل فرق كانبان على المشروع ككل.', 'Kanban teams work on a project as a whole.', false),
  (0, 96, 3, 'تستخدم فرق كانبان نظام السحب.', 'Kanban teams employ a pull system.', true),
  (0, 97, 0, 'إنه يفضّل العمل ضمن عمليات محددة مسبقاً', 'He likes to work within set processes', false),
  (0, 97, 1, 'إنه يعمل في الشركة منذ أكثر من خمس سنوات', 'He has been with the company for more than five years', false),
  (0, 97, 2, 'إنه يُظهر القيادة الخادمة ويُشرك الفريق في القرارات', 'He shows servant leadership and engages the team in decisions', true),
  (0, 97, 3, 'إنه يلتزم بالخطة ولا يغيّرها', 'He sticks to the plan and does not change', false),
  (0, 98, 0, 'تخمين العدد ثم تغيير الموضوع', 'Guess the number then change the subject', false),
  (0, 98, 1, 'إخبار شريك الأعمال بأنك سترسل إليه بريداً إلكترونياً يتضمن المعلومات', 'Tell the business partner you will send an e-mail to him with the information', false),
  (0, 98, 2, 'اصطحابه إلى منطقة الفريق، حيث تُعرض “لوحة عرض المعلومات” (Information Radiator) التي تحتوي على معلومات المشروع', 'Take him into the team area, where the “information radiator” with project information is displayed', true),
  (0, 98, 3, 'الطلب من شريك الأعمال الاتصال بسكرم ماستر للحصول على إجابة صحيحة', 'Ask the business partner to call the Scrum Master to get a correct answer', false),
  (0, 99, 0, 'يعمل فريق أجايل مباشرة مع مالك الأعمال أو ممثله لترتيب أولويات القيمة المسلَّمة باستمرار', 'The Agile team works directly with a business owner or representative to constantly prioritise delivered value', true),
  (0, 99, 1, 'يسلّم فريق أجايل المنتج دفعة واحدة', 'The Agile team delivers the product all in one go', false),
  (0, 99, 2, 'فريق أجايل مخصص للمطورين فقط، لذا سيتحسن التطوير', 'The Agile team is for developers only, so development will improve', false),
  (0, 99, 3, 'يطلب ممثلو الأعمال توصيات بشأن الميزات', 'The business representatives ask for feature recommendations', false);
INSERT INTO new_choices (exam_no, question_index, position, text_ar, text_en, is_correct) VALUES
  (0, 100, 0, 'قائمة الأعمال المتراكمة هي القائمة المرتبة لكل الأعمال، المعروضة في شكل “قصص”، لفريق ما.', 'The backlog is the ordered list of all the work, presented in “story” form, for a team.', false),
  (0, 100, 1, 'يشجع مدرّب المشروع الفريق على العمل بمعزل عن الآخرين، حتى لا يزعجهم أحد.', 'The project coach encourages the team to work alone, so no one bothers them.', true),
  (0, 100, 2, 'يشجع الميسّر الفريق على العمل في مجموعات ثلاثية تضم مطوراً ومختبِراً ومالك المنتج/محلل الأعمال.', 'The facilitator encourages the team to work in triads of a developer, tester, and product owner/business analyst.', false),
  (0, 100, 3, 'تناقش المجموعة الثلاثية القصص وتكتبها، ثم تضع عدداً كافياً من القصص في تكرار واحد، وعدداً كافياً من الميزات لإصدار أول.', 'The triad discuss, write, and then place enough stories into an iteration, and enough features for a first release.', false),
  (0, 101, 0, 'اصنع، اشترِ، نفّذ (Make, Buy, Do)', 'Make, Buy, Do', false),
  (0, 101, 1, 'أخبر، أظهر، كرّر (Tell, Show, Repeat)', 'Tell, Show, Repeat', false),
  (0, 101, 2, 'ابحث، أنشئ، أدِّ (Find, Create, Perform)', 'Find, Create, Perform', false),
  (0, 101, 3, 'بافتراض، عندما، عندئذٍ (Given, When, Then)', 'Given, When, Then', true),
  (0, 102, 0, 'قيم الفريق، مثل الوتيرة المستدامة وساعات العمل الأساسية.', 'Team values, such as sustainable pace and core hours.', false),
  (0, 102, 1, 'اتفاقيات العمل، مثل تحديد معنى “الجاهزية” حتى يتمكن الفريق من قبول العمل، ومعنى “الإنجاز” حتى يتمكن الفريق من الحكم على الاكتمال بشكل متسق.', 'Working agreements, such as what “ready” means so the team can take in work, and what “done” means so the team can judge completeness consistently.', false),
  (0, 102, 2, 'القواعد الأساسية، مثل تحدث شخص واحد فقط في الاجتماع.', 'Ground rules, such as one person talking in a meeting.', false),
  (0, 102, 3, 'مؤشر أداء الجدول الزمني ومؤشر أداء التكلفة للمشروع.', 'Schedule performance index and cost performance index for the project.', true),
  (0, 103, 0, 'تعرض مراجعات السبرنت العمل المكتمل في السبرنت. أما الاجتماعات الاستعادية للسبرنت فتنظر في كل العمل المكتمل في المشروع.', 'Sprint reviews demonstrate the work completed in the sprint. Sprint retrospectives look at all the work completed in the project.', false),
  (0, 103, 1, 'تناقش مراجعات السبرنت ما يتم العمل عليه في السبرنت. أما الاجتماعات الاستعادية للسبرنت فتُعقد في نهاية المشروع كفرصة لاستخلاص الدروس المستفادة.', 'Sprint reviews discuss what is worked on in the sprint. Sprint retrospectives are done at the end of the project for a lessons learned opportunity.', false),
  (0, 103, 2, 'تراجع مراجعات السبرنت الدروس المستفادة. أما الاجتماعات الاستعادية للسبرنت فتنظر في تاريخ المنتج بأثر رجعي.', 'Sprint reviews review the lessons learned. Sprint retrospectives look at the history of the product retrospectively.', false),
  (0, 103, 3, 'مراجعات السبرنت مخصصة للعروض التوضيحية للمنتج. أما الاجتماعات الاستعادية للسبرنت فمخصصة للدروس المستفادة.', 'Sprint reviews are for product demonstrations. Sprint retrospectives are for lessons learned.', true),
  (0, 104, 0, 'كم سيستغرق المشروع من الوقت؟', 'How long will the project last?', false),
  (0, 104, 1, 'ما هي القيمة التجارية؟', 'What is the business value?', true),
  (0, 104, 2, 'ما مقدار الميزانية المتاحة؟', 'How much is in the budget?', false),
  (0, 104, 3, 'كم عدد أعضاء الفريق الذين سيشاركون؟', 'How many team members will participate?', false),
  (0, 105, 0, 'ينبغي ترتيب أولويات الميزات وتطويرها واختبارها وتسليمها بشكل تزايدي', 'The features should be prioritized, developed, tested and delivered incrementally', true),
  (0, 105, 1, 'ينبغي تسليم الميزات بسرعة، سواء كانت مكتملة أم لا، لجمع التغذية الراجعة', 'The features should be delivered quickly, whether or not they are complete, to gather feedback', false),
  (0, 105, 2, 'ينبغي تسليم الميزات وفقاً لخطة المشروع', 'The features should be delivered according to the project plan', false),
  (0, 105, 3, 'ينبغي تسليم جميع الميزات في نهاية المشروع', 'All features should be delivered at the end of the project', false),
  (0, 106, 0, 'اتباع خطة المشروع التي وُضعت في وقت مبكر من المشروع', 'Follow the project plan developed early in the project', false),
  (0, 106, 1, 'اتباع توجيهات مكتب إدارة المشاريع (PMO)، الذي حدد بالفعل كيفية سير المشروع', 'Follow the PMO, who has already determined how the project should progress', false),
  (0, 106, 2, 'سؤال مالك المنتج، الذي يرتب أولويات قائمة الأعمال المتراكمة باستمرار', 'Ask the product owner, who continuously prioritizes the backlog', true),
  (0, 106, 3, 'الطلب من مدرّب المشروع أو قائد الفريق تحديد التكرار التالي', 'Ask the project coach or team leader to determine the next iteration', false),
  (0, 107, 0, 'الطلب من الفريق العمل لساعات إضافية من أجل تسليم المشروع', 'Tell the team to work overtime in order to deliver the project', false),
  (0, 107, 1, 'الوقوف إلى جانب فريقك وإخبار العملاء بأن المشروع لن يُسلَّم في الوقت المحدد', 'Stand by your team and tell the customers the project will not be delivered on time', false),
  (0, 107, 2, 'التأكد من أن العملاء يدركون أن الميزات ذات الأولوية الأدنى قد لا تكتمل على الإطلاق', 'Be sure the customers understand that lower priority features may not be completed at all', true),
  (0, 107, 3, 'وضع الميزات الجديدة في "ساحة انتظار" (Parking Lot) يمكن إكمالها إذا سمح الوقت', 'Place the new features in a "parking lot" that can be completed if time allows', false),
  (0, 108, 0, 'تخطيط التكرار على مستوى الفريق', 'Team Iteration Planning', false),
  (0, 108, 1, 'الإنشاء التعاوني لقصص المستخدم بين جهة الأعمال والعميل والمطورين والمختبِرين', 'Collaborative User Story Creation between the business, customer, developers and testers', false),
  (0, 108, 2, 'العروض التوضيحية والمراجعات للميزات التي تم تطويرها', 'Demonstrations and Reviews of the features developed', false),
  (0, 108, 3, 'القيادة الاستبدادية، لضمان إنجاز العمل', 'Autocratic Leadership, to ensure the work gets done', true),
  (0, 109, 0, 'تتناول قصة المستخدم المتطلبات الوظيفية وغير الوظيفية على حد سواء.', 'A user story addresses both functional and non-functional requirements.', false),
  (0, 109, 1, 'يجب على راعي المشروع اعتماد جميع قصص المستخدم مسبقاً.', 'The project sponsor must sign off on all user stories in advance.', true),
  (0, 109, 2, 'تتضمن قصة المستخدم معايير القبول للميزة المراد تطويرها.', 'A user story includes acceptance criteria for the feature to be developed.', false),
  (0, 109, 3, 'يجب أن تكون خصائص معايير القبول: قابلة للتقدير، وصغيرة، وقابلة للاختبار.', 'Characteristics for acceptance criteria must be: Estimable, Small, and Testable.', false),
  (0, 110, 0, 'لا تمثل مشكلة أثناء التكامل المستمر، مما يجعله طريقة أجايل مثالية.', 'not an issue during continuous integration, making it an ideal Agile method.', false),
  (0, 110, 1, 'تُكتشف بسرعة أكبر لأن الفريق يدمج عمله ويبنيه ويختبره باستمرار.', 'detected more quickly because they constantly integrate their work, build and test.', true),
  (0, 110, 2, 'تُدمج في عمل الفريق خلال هذه المرحلة كجزء من التطوير المعتمد على الاختبار.', 'integrated into their work during this phase as part of Test Driven Development.', false),
  (0, 110, 3, 'تُجمع وتُصلح في تكرار في نهاية المشروع، لتجنب التأخير.', 'collected and fixed in an iteration at the end of the project, to avoid delay.', false),
  (0, 111, 0, 'نهج الفريق الكامل، حيث يُضم أي شخص مطلوب إلى فريق المشروع.', 'The whole team approach, where any person needed is brought into the project team.', false),
  (0, 111, 1, 'التغذية الراجعة المبكرة والمتكررة، لضمان فهم مشترك للمنتج.', 'Early and frequent feedback, to ensure a common understanding of the product.', false),
  (0, 111, 2, 'اجتماعات الوقوف اليومية، للإبلاغ عن التقدم وطرح العوائق.', 'Daily stand-ups, to report on progress and raise blockers.', false),
  (0, 111, 3, 'رفع التقارير إلى المديرين التنفيذيين، لضمان رضاهم عن مشروعك.', 'Reporting to executives, to ensure they are happy with your project.', true),
  (0, 112, 0, 'لإظهار التقدم الذي يحرزه فريق التطوير للمديرين التنفيذيين', 'To show executives that progress is being made by the development team', false),
  (0, 112, 1, 'للحفاظ على قِصر مدة المشروع', 'To keep the project duration short', false),
  (0, 112, 2, 'لتمكين المستخدمين من اختبار جودة المنتج وتقديم التغذية الراجعة', 'To enable users to test the product for quality, and give feedback', false),
  (0, 112, 3, 'لتمكين جهة الأعمال من الحصول على القيمة بسرعة، مع تسليم الميزات', 'To enable the business to get value quickly, as features are delivered', true),
  (0, 113, 0, 'يستخدم الفريق أدوات منخفضة التقنية حتى يتمكن الأشخاص ذوو المعرفة التقنية المحدودة من فهمها.', 'The team are using low-tech tools so low-tech people can understand them.', false),
  (0, 113, 1, 'السبورة البيضاء هي في الواقع شيء معقد، لكنهم لا يدركون ذلك بعد.', 'A whiteboard is actually a complex thing, they just don’t know it yet.', false),
  (0, 113, 2, 'يطبّق الفريق مبدأ الإدارة المرئية، وباستخدام لوحة مادية تكون المعلومات شفافة لأي شخص يحتاج إليها.', 'The team is using the principle of visual management, and by using a physical board it is transparent to anyone who needs the information.', true),
  (0, 113, 3, 'سيترك الفريق كل شيء ويطوّر لوحة كانبان برمجية جديدة لتجنب الإحراج.', 'The team will drop everything and develop a new software-based Kanban board to avoid embarrassment.', false),
  (0, 114, 0, 'تمكّن الفريق من اكتشاف الأخطاء والمتطلبات المغفلة مبكراً', 'It enables the team to catch mistakes and missed requirements early', false),
  (0, 114, 1, 'تُبقي الجميع مشغولين وتمنحهم شيئاً يفعلونه', 'It keeps everyone busy and gives them something to do', true),
  (0, 114, 2, 'تضمن حلقة تغذية راجعة مبكرة بين العميل والمطورين', 'It ensures an early feedback loop between the customer and developers', false),
  (0, 114, 3, 'تقلل من تجاوزات التكلفة حيث يتم اكتشاف الأخطاء وإصلاحها في وقت أبكر', 'It reduces cost overruns as mistakes are found and fixed earlier', false),
  (0, 115, 0, 'التكامل المستمر (Continuous Integration)', 'Continuous integration', true),
  (0, 115, 1, 'البناء اليومي واختبارات الدخان', 'Daily build and smoke tests', false),
  (0, 115, 2, 'اختبار قابلية الاستخدام', 'Usability testing', false),
  (0, 115, 3, 'الاختبار الاستكشافي', 'Exploratory testing', false),
  (0, 116, 0, 'عند اكتمال التكرار الأول', 'When the first iteration is complete', false),
  (0, 116, 1, 'أثناء تقدير البطاقة وتفصيلها، بالاشتراك مع مالك المنتج ومحللي الأعمال وفريق التطوير', 'During estimation and elaboration of the card, with the product owner, business analysts and development team', true),
  (0, 116, 2, 'قبل تحديد أولوية المنتج أو الميزة', 'Before the product or feature is prioritised', false),
  (0, 116, 3, 'في نهاية المشروع', 'At the end of the project', false),
  (0, 117, 0, 'يفصل كل ميزة في مجموعة تطوير خاصة بها', 'separates each feature into its own development pool', false),
  (0, 117, 1, 'يضمن عدم تغيير أي شيفرة برمجية، لتجنب التعقيد', 'ensures no code is changed, to avoid complication', false),
  (0, 117, 2, 'يدمج جميع المكوّنات المتغيرة بانتظام، مرة واحدة يومياً على الأقل', 'integrates all changed components regularly, at least once a day', true),
  (0, 117, 3, 'يتيح ميزات جديدة لقائمة أعمال المنتج المتراكمة', 'enables new features for the product backlog', false),
  (0, 118, 0, 'الأشخاص، والتفاعل، والمجتمع.', 'People, Interaction, and Community.', true),
  (0, 118, 1, 'إيجاد الأشخاص، وبناء الأشخاص، وقيادة الأشخاص.', 'Finding people, building people, leading people.', false),
  (0, 118, 2, 'بناء المنتجات، وشراء المنتجات، وبيع المنتجات.', 'Building products, buying products, selling products.', false),
  (0, 118, 3, 'الربح، والمثابرة، والسلطة.', 'Profit, Persistence, and Power.', false),
  (0, 119, 0, 'كريستال الأزرق والنيلي والبنفسجي، بناءً على عدد الميزات في قائمة الأعمال المتراكمة.', 'Crystal blue, indigo and violet, based on number of features in the backlog.', false),
  (0, 119, 1, 'كريستال الشفاف أو الأصفر أو الأحمر، بناءً على عدد الأشخاص المشاركين.', 'Crystal clear, yellow or red, based on number of people involved.', true),
  (0, 119, 2, 'كريستال المعدن والخشب والماء، بناءً على تدفق بطاقات القصص عبر لوحة كانبان.', 'Crystal metal, wood and water, based on the flow of story cards through the Kanban board.', false),
  (0, 119, 3, 'كريستال العالي والمنخفض والمتوسط، بناءً على الدولارات المنفقة على المشروع.', 'Crystal High, Low, and Medium, based on dollars spent on the project.', false),
  (0, 120, 0, 'الالتزام المصغّر تجاه الفريق', 'To micro commit to the team', false),
  (0, 120, 1, 'كشف العوائق وإزالتها', 'To uncover and remove blockers', false),
  (0, 120, 2, 'ضمان تدفق العمل بحرية عبر الفريق', 'To ensure work flows freely through the team', false),
  (0, 120, 3, 'رفع التقارير إلى الفريق التنفيذي', 'To report to the executive team', true),
  (0, 121, 0, 'مراجعة لوحة كانبان والعمل قيد التنفيذ (WIP) الحالي', 'Review the Kanban board and the current WIP', false),
  (0, 121, 1, 'التحقق من قائمة أعمال المنتج المتراكمة لمعرفة الميزات المتبقية', 'Check the product backlog for remaining features', false),
  (0, 121, 2, 'مراجعة سرعة الفريق، ومخطط الإنجاز التنازلي للمنتج، ومؤشرات الأداء الرئيسية الأخرى', 'Review the team velocity, product burndown chart and other key performance indicators', true),
  (0, 121, 3, 'عقد اجتماع للفريق وتسجيل حالة كل فرد', 'Have a team meeting and log everyone’s status', false),
  (0, 122, 0, 'باستخدام الأولوية 1، والأولوية 2، والأولوية 3، والأولوية 4', 'Using Priority 1, Priority 2, Priority 3, Priority 4', false),
  (0, 122, 1, 'باستخدام منخفض، ومتوسط، وعالٍ', 'Using Low, medium, high', false),
  (0, 122, 2, 'باستخدام يجب أن يتوفر، وينبغي أن يتوفر، ويمكن أن يتوفر، ولن يتوفر', 'Using must have, should have, could have, will not have', true),
  (0, 122, 3, 'باستخدام نقاط متعددة يمكن للأشخاص تخصيصها للميزات التي يفضلونها', 'Using multiple dots that people can assign to the features they like', false),
  (0, 123, 0, 'ستزيل الحدود وتدفع أكبر قدر ممكن من العمل', 'You will remove the limits and push as much work through as possible', false),
  (0, 123, 1, 'ستفرض العمل الإضافي ومنع الإجازات على الفريق لإنجاز الأمور', 'You will dictate overtime and no holidays for the team to get things done', false),
  (0, 123, 2, 'تضمن حدود العمل قيد التنفيذ (WIP) تركيز الفريق على أمر رئيسي واحد في كل مرة، وتتجنب التكلفة الزمنية للتبديل بين المهام', 'WIP Limits ensure the team focuses on one main thing at a time, and avoids the time cost of switching tasks', true),
  (0, 123, 3, 'يمكن رؤية العمل قيد التنفيذ (WIP) على لوحة كانبان، لذا لا يهم ما هو الحد', 'WIP can be seen on the Kanban board, so it doesn’t matter what the limit is', false),
  (0, 124, 0, 'تثقيف أصحاب المصلحة، ومعالجة مخاوفهم، والحفاظ على إشراكهم', 'Educate the stakeholders, address their concerns, and keep them engaged', true),
  (0, 124, 1, 'إخبارهم بأن الأسلوب نجح في الماضي، وسينجح هنا أيضاً', 'Tell them is has worked in the past, it will work here too', false),
  (0, 124, 2, 'إملاء أصحاب المصلحة بأن هذه هي الطريقة التي يجب تنفيذ جميع المشاريع المستقبلية بها', 'Dictate to the stakeholders that this is how all future projects must be executed', false),
  (0, 124, 3, 'العودة إلى أسلوب إدارة المشاريع بطريقة الشلال (Waterfall)', 'Go back to a Waterfall style project management method', false),
  (0, 125, 0, 'لطرح التغييرات وإدارتها، وتحديد المخاطر والمشكلات المحتملة', 'To raise and manage changes, and identify potential risks and issues', true),
  (0, 125, 1, 'لإبلاغ أصحاب المصلحة بتوجه فريق التطوير', 'To inform the stakeholders of the development team’s direction', false),
  (0, 125, 2, 'لضمان أن يسمع المسؤولون التنفيذيون في الأعمال عن قيمة الفريق من خلال اجتماعات متعددة', 'To ensure business executives hear about the team’s value with multiple meetings', false),
  (0, 125, 3, 'لجعلهم يستثمرون مزيداً من الوقت في المشروع حتى يصبحوا ملتزمين', 'To have them invest more time in the project so they are committed', false),
  (0, 126, 0, 'غالباً ما تكون محددة بإطار زمني مدته 15 دقيقة.', 'They are often time-boxed to 15 minutes.', false),
  (0, 126, 1, 'يمكن لأي عضو في الفريق تيسير اجتماع الوقوف.', 'Any team-member may facilitate the standup.', false),
  (0, 126, 2, 'تُستخدم لطرح العوائق ودفع أجزاء العمل قُدماً.', 'They are used to raise blockers and advance pieces of work.', false),
  (0, 126, 3, 'تُستخدم كاجتماع حالة لإطلاع الفريق على المستجدات.', 'They are used as a status meeting to update the team.', true),
  (0, 127, 0, 'لا تحدث إلا في نهاية المشروع، أو عندما يكون أصحاب المصلحة متاحين.', 'only occur at the end of a the project, or when stakeholders are available.', false),
  (0, 127, 1, 'غالباً ما تحدث في نهاية التكرار، أو عند اكتمال عدد كافٍ من الميزات لتشكّل مجموعة متماسكة.', 'often occur at the end of an iteration, or when enough features have been completed into a set that is coherent.', true),
  (0, 127, 2, 'غالباً ما تحدث في بداية المشروع حتى يعرف الجميع ما عليهم تسليمه.', 'often occur at the start of the project so everyone knows what they have to deliver.', false),
  (0, 127, 3, 'غالباً ما تحدث عندما يرغب الفريق في ذلك، لأنهم مشغولون جداً بالعمل على أي حال.', 'often occur when the team wants to, as they are so busy working anyway.', false),
  (0, 128, 0, 'حيث لا تُطوَّر أي شيفرة برمجية أثناء الحالة الحمراء، وتُطوَّر بعض الشيفرة أثناء الحالة الخضراء، وتُستقبل ميزات جديدة أثناء حالة إعادة الهيكلة.', 'Where no code is developed during a red status, some code is developed during a green status, and new features are taken in during refactor status.', false),
  (0, 128, 1, 'نهج إشارة المرور لإدخال الميزات الجديدة.', 'A traffic light approach to bringing in new features.', false),
  (0, 128, 2, 'إصدار الميزات فقط عندما تُمنح الضوء الأخضر.', 'Only releasing features when they are given the green light.', false),
  (0, 128, 3, 'حيث يُكتب اختبار أولاً يفشل، ثم ينجح بمجرد تطوير الحل، ويمكن بعد ذلك إعادة هيكلة الشيفرة أو تبسيطها.', 'Where a test is written first that fails, then passes once the solution is developed, and can then be refactored or streamlined.', true),
  (0, 129, 0, 'ينبغي أن تدخل جميع التسليمات حيز التشغيل في نهاية المشروع فقط.', 'All deliverables should go live only at the end of the project.', false),
  (0, 129, 1, 'ينبغي تسليم المهام دون اختبارها، لإيصال القيمة إلى العميل بأسرع ما يمكن.', 'The tasks should be delivered but not tested, to get value to the customer as quickly as possible.', false),
  (0, 129, 2, 'ينبغي تحديد أولويات المهام وتطويرها واختبارها بشكل تزايدي.', 'The tasks should be prioritized, developed and tested incrementally.', true),
  (0, 129, 3, 'ينبغي تخطيط المهام بعناية وتسليمها وفقاً لخطتها.', 'The tasks should be planned carefully and delivered according to their plan.', false),
  (0, 130, 0, 'لإنجاز كل العمل حتى يتمكن الفريق من الاسترخاء.', 'To get all the work out of the way so the team can relax.', false),
  (0, 130, 1, 'حتى يمكن تقصير دورة حياة المشروع.', 'So the project lifecycle can be shortened.', false),
  (0, 130, 2, 'حتى تتمكن مالكة المنتج من إبلاغ مديرها التنفيذي بأن العمل يجري إنجازه.', 'So the product owner can report to her executive manager that work is being done.', false),
  (0, 130, 3, 'لتقليل مخاطر ألا تعود الميزة توفر قيمة للعميل.', 'To reduce the risk of the feature no longer providing value for the customer.', true),
  (0, 131, 0, 'ضمان أن يدوّن الفريق الأنشطة عالية المخاطر ويجدولها في وقت مبكر من المشروع حتى يتم تخفيفها بسرعة.', 'Ensure the team notes and schedules high-risk activities early in the project so that they are mitigated quickly.', true),
  (0, 131, 1, 'ضمان أن يحدد الفريق المخاطر، ويضعها في سجل، ويخففها بحلول نهاية المشروع.', 'Ensure the team identifies risks, places them in a register and mitigates them by the end of the project.', false),
  (0, 131, 2, 'ضمان أن يحتفظ الفريق بسجل المخاطر لنفسه، حتى لا يقلّل أصحاب المصلحة الآخرون من شأن المشروع.', 'Ensure the team keeps the risk register to itself, so other stakeholders don’t think less of the project.', false),
  (0, 131, 3, 'ضمان أن تُرصد المخاطر المتعلقة بالأشخاص فقط، لأن فريق أجايل يفضّل الأفراد والتفاعلات على العمليات والأدوات.', 'Ensure risk is only captured around people because an Agile team prefers individuals and interactions over processes and tools.', false),
  (0, 132, 0, 'طلب أن يكون العقد من النوع الذي يستوعب التغييرات في نطاق المنتج.', 'Request that the contract is one that accommodates changes to product scope.', true),
  (0, 132, 1, 'العودة إلى جهة الأعمال وطلب أن تقوم هي بتسليم الميزة', 'Go back to the business and ask them to deliver the feature', false),
  (0, 132, 2, 'رفع خطر يهدد تسليم مشروعك بسبب المورّد الخارجي', 'Raise a risk to the delivery of your project based on the external vendor', false),
  (0, 132, 3, 'البحث عن عقد "الوقت والمواد" (Time and Materials) قائم ضمن أصول العمليات التنظيمية للمنظمة.', 'Find an existing “time and materials” contract from the organisation’s Organisational Process Assets.', false),
  (0, 133, 0, 'تجنب سوء فهم المتطلبات، الذي ربما لم يكن ليُكتشف إلا في وقت لاحق من دورة التطوير حين يكون إصلاحه أكثر تكلفة.', 'Avoiding requirements misunderstandings, which may not have been detected until later in the development cycle when they are more expensive to fix.', false),
  (0, 133, 1, 'توضيح طلبات العميل للميزات، وإتاحتها لاستخدام العميل مبكراً.', 'Clarifying customer feature requests, making them available for customer use early.', false),
  (0, 133, 2, 'اكتشاف مشكلات الجودة وعزلها وحلّها مبكراً.', 'Discovering, isolating, and resolving quality problems early.', false),
  (0, 133, 3, 'الحصول على إصدار واحد كبير في نهاية المشروع يمكن للجميع الاحتفال به.', 'Having one big release at the end of the project that everyone can celebrate.', true),
  (0, 134, 0, 'التعامل مع التغيير كمشروع أجايل، له قائمة أعمال متراكمة خاصة به من التغييرات التي يمكن للفريق إدخالها بناءً على القيمة المتصوَّرة.', 'Treat the change as an Agile project, with its own backlog of changes that could be introduced by the team based on perceived value.', false),
  (0, 134, 1, 'التعامل مع كل تغيير كتجربة، تُختبر لفترة زمنية قصيرة لتحديد مدى ملاءمتها أو الحاجة إلى مزيد من التنقيح.', 'Treat each of the changes as an experiment, tested for a short period of time to determine suitability or the need for further refinement.', false),
  (0, 134, 2, 'استخدام لوحات كانبان لتتبع التقدم، بحيث تُعرض الأساليب الجديدة قيد الاستخدام على أنها "منجزة"، والأمور التي تُجرَّب على أنها "قيد التنفيذ".', 'Use Kanban boards to track progress, showing new approaches in use as “done”, and things being tried as “in progress”.', false),
  (0, 134, 3, 'توجيه الفرق لتبنّي أجايل دفعة واحدة، والمضي قُدماً دون تردد.', 'Direct the teams to take on Agile in one go, moving ahead without wavering.', true),
  (0, 135, 0, 'ستوثّق قيم الفريق وإرشادات التواصل وعملية اتخاذ القرار بشكل منفصل عن الغرض من المشروع ومتطلباته وجدوله الزمني الموجز.', 'You will capture the Team values, Communication guidelines and Decision-making process separately to the project purpose, requirements and summary schedule.', true),
  (0, 135, 1, 'ستُعدّ خطة مشروع تتضمن الخطوط العريضة للنطاق والجدول الزمني والتكلفة والجودة لاتباعها.', 'You will create a project plan with Scope, Schedule, Cost and Quality outlines to follow.', false),
  (0, 135, 2, 'ستتولى الأمر بدلاً من راعي المشروع وتوجّه الفريق بشأن متطلبات العميل المستقبلية.', 'You will take over from the project sponsor and direct the team on future customer requirements.', false),
  (0, 135, 3, 'ستُحيل جميع الاستفسارات إلى الفريق على طريقة القائد الخادم.', 'You will defer to the team for all queries in the way of a servant leader.', false),
  (0, 136, 0, 'الطلب من الفريق البدء في العمل فوراً، لأن فرق أجايل تتحرك بسرعة.', 'Ask the team to get to work straight away, because Agile teams move swiftly.', false),
  (0, 136, 1, 'إرسال ميثاق الفريق إلى راعي المشروع لاعتماده، حتى يتسنى بدء المشروع.', 'Send the Team Charter to the project sponsor for their sign off, so the project can begin.', false),
  (0, 136, 2, 'الاتفاق على "تعريف الإنجاز" (Definition of Done) لميزات الفريق ومهامه وإدراجه في الميثاق.', 'Agree on and include the “definition of done” for team features and tasks.', true),
  (0, 136, 3, 'تحديد اجتماع بعد أسبوعين حتى تتمكن من مواصلة تطوير الميثاق بشكل تكراري.', 'Set a meeting for two weeks time so you can continue to develop the charter iteratively.', false),
  (0, 137, 0, 'الطلب من أصحاب المصلحة تفصيل أفكارهم بشكل أفضل، وتحديد اجتماع آخر بعد أسبوع.', 'Ask the stakeholders to elaborate their ideas better, and set another meeting in a week’s time.', false),
  (0, 137, 1, 'تعليق تلك الميزة في الوقت الحالي والبدء في العمل على ميزة مفصّلة بشكل أفضل.', 'Park that feature for now and begin work on a feature that is elaborated better.', false),
  (0, 137, 2, 'رسم نموذج أولي على شكل لوحة قصصية (Storyboard) للمتطلب حتى يتمكن جميع أصحاب المصلحة من رؤيته وتعديله والاتفاق عليه.', 'Draw a storyboard prototype of the requirement so all stakeholders can see it, adjust it and agree.', true),
  (0, 137, 3, 'تقديم فهمك للميزة والطلب من أصحاب المصلحة الموافقة أو عدم الموافقة.', 'Give your understanding of the feature and ask the stakeholders to agree or disagree.', false),
  (0, 138, 0, 'ضمان التواصل عبر البريد الإلكتروني فقط مع صاحب المصلحة الرئيسي حتى يشعر بالارتياح.', 'Ensure you communicate by email only with the key stakeholder so they are comfortable.', false),
  (0, 138, 1, 'التوقف عن التواصل مع صاحب المصلحة الرئيسي إلى أن يحضر على الأقل بعض اجتماعات المشروع.', 'Stop communicating with the key stakeholder until they at least come to a few project meetings.', false),
  (0, 138, 2, 'الطلب من صاحب المصلحة الرئيسي التواجد في مكان واحد مع فريق أجايل لبضعة أيام في الأسبوع، لضمان التواصل وجهاً لوجه والوصول إلى معلومات المشروع المرئية.', 'Ask the key stakeholder to co-locate with the Agile team for a few days a week, to ensure face to face communication and access to the visual project information.', true),
  (0, 138, 3, 'تحديد اجتماعات مع صاحب المصلحة الرئيسي حتى تتمكن من إطلاعه على المستجدات شخصياً.', 'Set meetings with the key stakeholder so you can update them personally.', false),
  (0, 139, 0, 'تخبر فريقك بما يجب فعله خلال ساعات العمل، حتى يتمكنوا من التعلم منك.', 'Tell your team what to do during work hours, so they can learn from you.', false),
  (0, 139, 1, 'تكتب وثيقة عملية ليقرأها الفريق في وقت فراغه.', 'Write a process document for the team to read through in their spare time.', false),
  (0, 139, 2, 'تنشئ لوحة عرض المعلومات (Information Radiator) في منطقة الفريق.', 'Create an information radiator in the team area.', true),
  (0, 139, 3, 'تشكّل مجموعة رئيسية من أصحاب المصلحة التنفيذيين لمشاركة معلومات المشروع معهم، لضمان سمعتك الطيبة داخل الشركة.', 'Form a key group of executive stakeholders to share project information with, to ensure your good reputation within the company.', false),
  (0, 140, 0, 'إعادة الهيكلة (Refactoring) المنتظمة والنشر اليومي لقاعدة شفرة برمجية متكاملة', 'Regular refactoring and daily deployment of an integrated code base', true),
  (0, 140, 1, 'جعل مستخدمين حقيقيين يختبرون المنتج عند إصداره', 'Having real users test the product when it is released', false),
  (0, 140, 2, 'تنقّل أعضاء الفريق بين أدوار مختلفة لاكتساب خبرة مشتركة', 'Moving team members around to different roles for a shared experience', false),
  (0, 140, 3, 'ضمان قيام الفريق بما يقوله سكرم ماستر (Scrum Master) بالضبط', 'Ensuring the team does exactly what the Scrum Master says', false),
  (0, 141, 0, 'استخدام خدمة المراسلة "Slack" للتواصل كفريق.', 'To use the messaging service “Slack” to communicate as a team.', false),
  (0, 141, 1, 'السماح لأفضل المؤدّين في الفريق بـ"التراخي" كمكافأة على عملهم الشاق.', 'Allowing the best performers in the team to “slack” off as a reward for their hard work.', false),
  (0, 141, 2, 'إضافة بطاقة لإعادة هيكلة الشفرة البرمجية، يمكن استبدالها إذا طرأت حالة طارئة.', 'Adding a card for refactoring code, that can be replaced if an emergency comes up.', true),
  (0, 141, 3, 'إنشاء مخطط إنجاز تنازلي ومخطط إنجاز تصاعدي معاً.', 'Creating a burn-down chart and a burn-up chart together.', false),
  (0, 142, 0, 'تحديد أفضل مؤدٍّ في الفريق حتى تعرف من يمكنك الاعتماد عليه.', 'Find the best performer in the team so you know who you can rely on.', false),
  (0, 142, 1, 'تحديد سرعة (Velocity) فريقك على مدى السبرنتات القليلة القادمة حتى تتمكن من تحديد وتيرة مستدامة.', 'Find your team''s velocity over the next few sprints so you can set a sustainable pace.', true),
  (0, 142, 2, 'عقد اجتماع لمجموعة عمل لكسب تأييد الإدارة التنفيذية.', 'Set a working group meeting to gain executive buy-in.', false),
  (0, 142, 3, 'إنشاء خطة إدارة المشروع ورسم الجدول الزمني مسبقاً.', 'Create the project management plan and draw out the schedule in advance.', false),
  (0, 143, 0, 'إنشاء مراسم مثل اجتماع الوقوف اليومي، واجتماع تخطيط التكرار، والعروض التوضيحية والمراجعات، والاجتماعات الاستعادية التي تشجع تفاعل الفريق.', 'Create ceremonies such as the daily stand-up, iteration planning meeting, demos & reviews and retrospectives that encourage team interaction.', true),
  (0, 143, 1, 'إنشاء عملية ليراجعها الفريق توضح أسلوب العمل.', 'Create a process for the team to review that shows the way of work.', false),
  (0, 143, 2, 'الطلب من راعي المشروع التفاعل مع الفريق من خلال مشاركة بعض من مسيرته.', 'Ask the project sponsor to interact with the team by sharing some of their journey.', false),
  (0, 143, 3, 'ضمان أن تكون الأدوات التي يعمل بها الفريق حلولاً برمجية متطورة.', 'Ensure the tools the team have to work with are state of the art software solutions.', false),
  (0, 144, 0, 'القيادة الخادمة، حيث تقود الفريق من خلال تلبية احتياجاته، وتنمية مهاراته، وإزالة العوائق.', 'Servant leadership, where you will lead the team by serving their needs, growing their skills, and removing blockers.', true),
  (0, 144, 1, 'القيادة التوجيهية، حيث تخبر الفريق بما يجب فعله بالضبط حتى لا يضطر إلى القلق.', 'Directive leadership, where you tell the team exactly what to do so they don’t have to worry.', false),
  (0, 144, 2, 'القيادة ذات الرؤية، حيث تركز على الميزات عالية المستوى ولا تهتم بالتفاصيل.', 'Visionary leadership, where you focus on the high level features and don’t worry about the detail.', false),
  (0, 144, 3, 'القيادة الحرة (Laissez-faire)، حيث تتبع نهج عدم التدخل، وتترك الفريق ينظم نفسه ذاتياً.', 'Laissez-faire leadership, where you take a hands off approach, and let the team self-organise.', false),
  (0, 145, 0, 'تسجيل خطر في سجل المخاطر يتعلق بأهداف المشروع، والطلب من راعي المشروع تخفيف الخطر.', 'Raise a risk in the risk register around project goals, and ask the project sponsor to mitigate the risk.', false),
  (0, 145, 1, 'عقد جلسة توجيه (Coaching) مع الفريق لتعليمهم "ماهية" مراسم أجايل و"سبب" وجودها، وضمان أن يكون لكل اجتماع نتيجة ووقت وجدول أعمال واضح.', 'Have a coaching session with the team teaching the “what” and “why” behind Agile ceremonies, and ensure each meeting has a clear outcome, time and agenda.', true),
  (0, 145, 2, 'إلغاء جميع الاجتماعات في الوقت الحالي، وكتابة بعض الوثائق للفريق حول ما تريد منهم فعله.', 'Cancel all meetings for now, and write some documentation for the team on what you’d like them to do.', false),
  (0, 145, 3, 'اتخاذ القرارات بنفسك وإملاء النتائج على الفريق.', 'Make the decisions yourself and dictate the outcomes to the team.', false),
  (0, 146, 0, 'ضمان أن يتخذ الفريق التنفيذي جميع القرارات.', 'Ensure the executive team makes all the decisions.', false),
  (0, 146, 1, 'ضمان أن يتفق أصحاب المصلحة جماعياً على القرارات ويتشاركوها.', 'Ensure the stakeholders collectively agree on and share decisions.', true),
  (0, 146, 2, 'إحالة جميع القرارات إلى مالك المنتج وجهة الأعمال لاتخاذها.', 'Defer to the product owner and the business to make all the decisions.', false),
  (0, 146, 3, 'إيجاد شخص كفء للغاية في فريق المشروع وتفويض القرارات إليه.', 'Find an extremely competent person in the project team and delegate decisions to them.', false),
  (0, 147, 0, 'أجايل يتعلق بالبرمجيات، وينبغي للفريق استخدام البرمجيات للتصويت على القرار.', 'Agile is about software, and the team should use software to vote on the decision.', false),
  (0, 147, 1, 'قد لا يكون القرار في صالحك، لذا من الأفضل أن تتخذه بنفسك.', 'The decision may not go in your favour, so it’s best to just do it yourself.', false),
  (0, 147, 2, 'ينبغي أن تستغرق القرارات وقتاً لدراستها، لا أن يُصوَّت عليها بسرعة.', 'Decisions should take time to work through, not be voted on quickly.', false),
  (0, 147, 3, 'بجعل قراراتهم مرئية، قد يتأثر أعضاء الفريق بآخرين في الفريق (وخاصة التنفيذيين) دون الاستفادة من النقاش.', 'By making their decisions visible, team members may be influenced by others in the team (especially executives) without the benefit of discussion.', true),
  (0, 148, 0, 'سيعتمد فريقك على تصاميم الميزات السابقة في عملك.', 'Your team will rely on previous feature designs for your work.', false),
  (0, 148, 1, 'يتميز فريقك بقدرات معينة، ويعرضها على الفرق الأخرى.', 'Your team features certain abilities, and showcases them to other teams.', false),
  (0, 148, 2, 'يستمتع فريقك بميزة العمل بأجايل في منظمة تعمل بأجايل.', 'Your team enjoys the feature of working with Agile in an Agile organisation.', false),
  (0, 148, 3, 'سيجرّب فريقك تطوير نموذج شامل، ثم التخطيط والتصميم والبناء وفقاً لتلك الميزات.', 'Your team will trial developing an overall model, then planning, designing and building by those features.', true),
  (0, 149, 0, 'المحرك الرئيسي لسلوك التنفيذيين', 'the primary driver of executive behaviour', false),
  (0, 149, 1, 'المقياس الرئيسي للتقدم', 'the primary measure of progress', true),
  (0, 149, 2, 'الطريقة الرئيسية لدفع تكلفة فريق أجايل', 'the primary way to pay for the cost of an Agile team', false),
  (0, 149, 3, 'العامل الرئيسي لتمكين مشاركة الأفراد', 'the primary enabler of people’s engagement', false);
INSERT INTO new_choices (exam_no, question_index, position, text_ar, text_en, is_correct) VALUES
  (0, 150, 0, 'عضو الفريق لا يمانع القرار في أي من الاتجاهين.', 'The team member doesn’t mind about the decision either way.', false),
  (0, 150, 1, 'لدى عضو الفريق قلق أو اعتراض يحتاج إلى مزيد من النقاش.', 'The team member has a concern or conflict that needs further discussion.', true),
  (0, 150, 2, 'عضو الفريق يحيل القرار إلى الراعي التنفيذي ليقرر.', 'The team member defers to the executive sponsor to decide.', false),
  (0, 150, 3, 'القرار خارج نطاق خبرة عضو الفريق، وهو يختار عدم التصويت.', 'The decision is outside of the team member’s expertise and they choose not to vote.', false),
  (0, 151, 0, 'حتى تتمكن من مراقبة ما يفعلونه', 'So you can keep an eye on what they are doing', false),
  (0, 151, 1, 'حتى يتمكن ممثلو جهة الأعمال من إبلاغ مديريهم عن المشروع', 'So business representatives can report back to their managers on the project', false),
  (0, 151, 2, 'حتى يشعر الفريق بالأهمية، بحضور عدد كبير من أصحاب المصلحة', 'So the team feels important, with lots of stakeholders present', false),
  (0, 151, 3, 'حتى لا يرفض أصحاب المصلحة في المشروع قراراً لم يكن قرارهم', 'So the project stakeholders don’t reject a decision that wasn’t theirs', true),
  (0, 152, 0, 'إبعاد أي عضو في الفريق غير منخرط في المشروع.', 'Removing any team member who is not engaged in the project.', false),
  (0, 152, 1, 'إعطاء عمل إضافي لأعضاء الفريق الأكثر انخراطاً.', 'Giving extra work to the better engaged team members.', false),
  (0, 152, 2, 'ضمان وضوح العمل وشفافيته وتقدمه من خلال المخططات والمعلومات في منطقة الفريق المشتركة.', 'Ensuring visibility, transparency and progress of the work through charts and information in the common team area.', true),
  (0, 152, 3, 'عرض ترقية محتملة على عضو الفريق الأكثر انخراطاً في نهاية المشروع.', 'Offering a possible promotion to the most engaged team member at the end of the project.', false),
  (0, 153, 0, 'تتم تجربة منهجية أجايل كفريق متعدد التخصصات يشكّل نفسه ذاتياً.', 'The Agile methodology is being trialled as a cross-discipline self-forming team.', false),
  (0, 153, 1, 'تم اختيار شخص واحد لكل دور ضروري، ولا أكثر.', 'One person was selected for each role necessary, and no more.', false),
  (0, 153, 2, 'توصي أساليب أجايل بأن يكون فريق التسليم مكوناً من 12 عضواً أو أقل.', 'Agile methods recommend the delivery team to be 12 or fewer members.', true),
  (0, 153, 3, 'تتطلب أساليب أجايل أدواراً متخصصة للغاية.', 'Agile methods call for very specialized roles.', false),
  (0, 154, 0, 'شخص لديه معرفة مسطّحة في الأعلى، ومعرفة طويلة في الأسفل.', 'A person that has flat knowledge up top, and long knowledge down the bottom.', false),
  (0, 154, 1, 'شخص لديه مجموعة واسعة من المهارات العامة (مثل التصميم، والتطوير، والاختبار) ومهارة واحدة أو مجال معرفة واحد عميق.', 'A person with a wide range of general skills (i.e. design, development, testing) and one deep skill or knowledge area.', true),
  (0, 154, 2, 'شخص لديه مجموعة واسعة من المهارات القيادية، إذ ينبغي للجميع أن يقودوا في فريق أجايل.', 'A person with a wide range of leadership skills, as everyone should lead on an Agile team.', false),
  (0, 154, 3, 'شخص لديه علاقات أكثر في طبقات الإدارة، وعلاقات قليلة في طبقة الفريق.', 'A person that has more contacts in management layers, and few contacts in the team layer.', false),
  (0, 155, 0, 'الأفراد والتفاعلات أهم من العمليات والأدوات', 'Individuals and interactions over processes and tools', true),
  (0, 155, 1, 'التقارير التنفيذية أهم من التقارير التصاعدية', 'Executive reporting over bottom up reporting', false),
  (0, 155, 2, 'سكرم ماستر أهم من مديري المشاريع', 'Scrum masters over project managers', false),
  (0, 155, 3, 'أداء العمل أهم من مشاهدة العمل', 'Doing the work over viewing the work', false),
  (0, 156, 0, 'ما يقوله سكرم ماستر، لأنه الأعلم.', 'What the scrum master says, as he or she knows best.', false),
  (0, 156, 1, '"سرعة" الفريق (Velocity)، وهي المعدل الذي يستطيع الفريق به إكمال العمل.', 'The team''s “Velocity”, which is the rate at which a team can complete work.', true),
  (0, 156, 2, 'ما يريد الفريق العمل عليه، لضمان عمل الأفراد ضمن نقاط قوتهم.', 'What the team wants to work on, to ensure individuals work within their strengths.', false),
  (0, 156, 3, 'نموذج التطوير المعتمد على الميزات المراد إكماله.', 'The Feature Driven Development model to be completed.', false),
  (0, 157, 0, 'جلسة غداء وتعلّم للفريق', 'A team lunch and learn', false),
  (0, 157, 1, 'اجتماع مجموعة عمل', 'A working group meeting', false),
  (0, 157, 2, 'اجتماع الوقوف اليومي (Daily Stand-up)', 'A daily stand-up', true),
  (0, 157, 3, 'الاجتماع الاستعادي (Retrospective)', 'A retrospective', false),
  (0, 158, 0, 'دورة حياة مشروع الشلال (Waterfall)', 'Waterfall project lifecycle', false),
  (0, 158, 1, 'دورة حياة مشروع أجايل', 'Agile project lifecycle', false),
  (0, 158, 2, 'دورة حياة مشروع تكرارية', 'Iterative project lifecycle', false),
  (0, 158, 3, 'دورة حياة مشروع تزايدية', 'Incremental project lifecycle', true),
  (0, 159, 0, 'يستطيع الفريق إعداد قائمة بأسباب عدم إمكانية إكمال المهام.', 'The team is able to create a list of reasons why tasks cannot be completed.', false),
  (0, 159, 1, 'لا يوجد نزاع في الفريق لأنهم منسجمون جداً.', 'The team has no conflict as they get along so well.', false),
  (0, 159, 2, 'يتحمل قائد الفريق مسؤولية جميع القرارات المتخذة في المشروع.', 'The team leader takes responsibility for all decisions made in the project.', false),
  (0, 159, 3, 'يُشجَّع الفريق على المشاركة في النقاش والاختلاف في الرأي من أجل اتخاذ قرارات أفضل.', 'The team is encouraged to participate in discussion and disagreement in order to make better decisions.', true),
  (0, 160, 0, 'التطوير التفصيلي (Detailed Elaboration)', 'Detailed Elaboration', false),
  (0, 160, 1, 'تخطيط الشلال (Waterfall Planning)', 'Waterfall Planning', false),
  (0, 160, 2, 'تخطيط أجايل (Agile Planning)', 'Agile Planning', false),
  (0, 160, 3, 'التخطيط بالموجة المتدحرجة (Rolling Wave Planning)', 'Rolling Wave Planning', true),
  (0, 161, 0, 'مدير إدارة المشروع', 'Project director', false),
  (0, 161, 1, 'مدرّب المشروع', 'Project coach', true),
  (0, 161, 2, 'دعم المشروع', 'Project support', false),
  (0, 161, 3, 'المدير التنفيذي للمشروع', 'Project executive', false),
  (0, 162, 0, 'عقد اجتماع استعادي آخر لمحاولة استخلاص مزيد من المعلومات.', 'Hold another retrospective to try and extract more information.', false),
  (0, 162, 1, 'مواءمة أهداف المشروع مع الأهداف الشخصية لكل عضو من أعضاء الفريق.', 'Align the project goals to each team members’ personal goals.', true),
  (0, 162, 2, 'إجراء تصويت حول ما إذا كان ينبغي مواصلة المشروع أم لا.', 'Hold a vote on whether to continue the project or not.', false),
  (0, 162, 3, 'إشراك الإدارة التنفيذية حتى يرفع أعضاء الفريق مستوى مشاركتهم.', 'Get executive management involved so team members raise their engagement.', false),
  (0, 163, 0, 'ضمان إعداد التقارير أسبوعياً للإدارة التنفيذية.', 'Ensure reports are created weekly for executive management.', false),
  (0, 163, 1, 'إعداد مؤتمر عن بُعد مع الأجزاء المختلفة من فريق مشروعك.', 'Set up a teleconference with different parts of your project team.', false),
  (0, 163, 2, 'جمع الفريق في مكان واحد حيثما أمكن والتركيز على التواصل المباشر وجهاً لوجه بشكل متكرر.', 'Co-locate the team where possible and focus on frequent face-to-face communication.', true),
  (0, 163, 3, 'عقد اجتماعات فردية متكررة مع أعضاء فريق مشروعك للاطلاع على وجهات نظرهم على انفراد.', 'Have frequent one-on-ones with your project team to get their point of view in private.', false),
  (0, 164, 0, 'العمل قيد التنفيذ (Work in Progress) وتمكين "السحب" (Pull) و"التدفق" (Flow)', 'Work in Progress and enabling “Pull” and “Flow”', true),
  (0, 164, 1, 'الفريق وتمكين إعداد التقارير للإدارة التنفيذية', 'the team and enabling executive reporting', false),
  (0, 164, 2, 'سرعة العمل وتمكين تفصيل بطاقات القصص', 'work velocity and enabling story card elaboration', false),
  (0, 164, 3, 'سكرم ماستر وتمكين مشاركة الفريق', 'the scrum master and enabling team participation', false),
  (0, 165, 0, 'يتجمع الفريق حول لوحة سرعة الفريق كل صباح للتأكد من أن العمل يُنجز.', 'The team gathers around the team velocity board each morning to ensure work is being done.', false),
  (0, 165, 1, 'يسحب الفريق العمل فقط عندما يكون جاهزاً، بدلاً من تراكم العمل قيد التنفيذ باستمرار.', 'The team pulls work only when they are ready, instead of work in progress constantly building up.', true),
  (0, 165, 2, 'يعمل الفريق بنهج السحب والدفع بين المطورين والمختبرين.', 'The team works with a pull and push approach between the developers and testers.', false),
  (0, 165, 3, 'يطلب سكرم ماستر من الفريق سحب الأذرع المناسبة التي تتيح تطوير الميزات الصحيحة.', 'The Scrum Master tells the team to pull the appropriate levers that enable the right features to be developed.', false),
  (0, 166, 0, 'تصوير سير العمل بصرياً والحد من العمل قيد التنفيذ.', 'Visualise the workflow and limit work in progress.', false),
  (0, 166, 1, 'إدارة التدفق وتمكين "السحب".', 'Manage Flow and Enable "Pull“.', false),
  (0, 166, 2, 'تطبيق حلقات التغذية الراجعة والتحسين بشكل تعاوني.', 'Implement feedback loops and improve collaboratively.', false),
  (0, 166, 3, 'اتباع الإجراءات وعدم الحياد عن الخطة.', 'Follow procedures and don''t deviate from the plan.', true),
  (0, 167, 0, 'البدء بالوضع الحالي واحترام العملية الحالية.', 'Start with current state and respect the current process.', false),
  (0, 167, 1, 'الاتفاق على السعي إلى تغيير تزايدي وتطوري.', 'Agree to pursue incremental, evolutionary change.', false),
  (0, 167, 2, 'القيادة على جميع المستويات.', 'Lead at all levels.', false),
  (0, 167, 3, 'القيادة التوجيهية أهم من مشاركة الفريق المهدِرة للوقت.', 'Directive leadership over wasteful team participation.', true),
  (0, 168, 0, 'القيادة التوجيهية أهم من القيادة الخادمة', 'Directive leading over servant leading', false),
  (0, 168, 1, 'البرمجيات العاملة أهم من التوثيق الشامل', 'Working software over comprehensive documentation', true),
  (0, 168, 2, 'إنتاج ميزات كبيرة مفيدة أهم من إنتاج زيادات صغيرة', 'Making large useful features over making small increments', false),
  (0, 168, 3, 'دفع العمل بسرعة أهم من الحد من العمل قيد التنفيذ', 'Pushing work through quickly over limiting work in progress', false),
  (0, 169, 0, 'دليل إرشادات الفريق', 'The Team Guideline', false),
  (0, 169, 1, 'خطة إدارة المشروع', 'The Project Management Plan', false),
  (0, 169, 2, 'ميثاق المشروع', 'The Project Charter', false),
  (0, 169, 3, 'ميثاق الفريق', 'The Team Charter', true);
INSERT INTO public.questions (id, type, text_ar, text_en, explanation_ar, explanation_en, answer_count)
INSERT INTO public.choices (question_id, position, text_ar, text_en, is_correct)
  INSERT INTO public.exams (track_id, config_id, tag_id, display_order, name_ar, name_en,
